let busy = false;

const ctx = () => SillyTavern.getContext();

function settings() {
    const all = ctx().extensionSettings;
    if (!all[MODULE]) all[MODULE] = structuredClone(defaults);
    for (const k of Object.keys(defaults)) {
        if (all[MODULE][k] === undefined) all[MODULE][k] = defaults[k];
    }
    const s = all[MODULE];
    // Обновляем сохранённый стандартный промпт из старых версий (он не содержал новых разделов)
    if ((s.promptVersion || 0) < 2) {
        if (s.thinkPrompt.includes('Пауза в ролевой игре') && !s.thinkPrompt.includes('{{npcs}}')) {
            s.thinkPrompt = DEFAULT_THINK;
        }
        s.promptVersion = 2;
        ctx().saveSettingsDebounced();
    }
    if (s.promptVersion < 3) {
        // стандартный промпт v2 → v3 (добавлен раздел времени и места)
        if (s.thinkPrompt.includes('ведёшь свой рабочий блокнот') && !s.thinkPrompt.includes('{{time}}')) {
            s.thinkPrompt = DEFAULT_THINK;
        }
        s.promptVersion = 3;
        ctx().saveSettingsDebounced();
    }
    if ((s.promptVersion || 0) < 5) {
        if (!s.injectPrompt || s.injectPrompt.includes('любую задумку, бытовую деталь') || s.injectPrompt.includes('НЕ держи их мёртвым грузом')) {
            s.injectPrompt = DEFAULT_INJECT;
        }
        s.promptVersion = 5;
        ctx().saveSettingsDebounced();
    }
    // 2.3.0: стандартные промпты переведены на английский — заменяем, только если у пользователя стоял старый стандартный русский
    if ((s.promptVersion || 0) < 7) {
        if (s.thinkPrompt === NNB_OLD_RU_THINK) s.thinkPrompt = DEFAULT_THINK;
        if (s.injectPrompt === NNB_OLD_RU_INJECT) s.injectPrompt = DEFAULT_INJECT;
        s.promptVersion = 7;
        ctx().saveSettingsDebounced();
    }
    if ((s.promptVersion || 0) < 6) {
        if (!s.naiModel || s.naiModel === 'nai-diffusion-5-full' || s.naiModel === 'nai-diffusion-4-5-full') {
            s.naiModel = 'nai-diffusion-5-full-medium';
        }
        if (s.naiPrefix === 'very aesthetic, masterpiece, best quality, no text') {
            s.naiPrefix = '';
        }
        s.promptVersion = 6;
        ctx().saveSettingsDebounced();
    }
    return s;
}

function saveSettings() {
    ctx().saveSettingsDebounced();
}

// Хранилище текущего чата (null, если чат не открыт)
function store() {
    const c = ctx();
    if (!c.chatId || !c.chatMetadata) return null;
    if (!c.chatMetadata[MODULE]) {
        c.chatMetadata[MODULE] = {
            notes: [],
            archive: [],
            nextId: 1,
            lastThinkAt: c.chat?.length ?? 0,
            lastRaw: '',
        };
    }
    const st = c.chatMetadata[MODULE];
    if (!st.direction) st.direction = { genres: [], customGenre: '', inspiration: '' };
    if (!st.direction.mixMode) st.direction.mixMode = 'and';
    if (typeof st.direction.avoid !== 'string') st.direction.avoid = '';
    if (st.direction.intrigues === undefined) st.direction.intrigues = true;
    if (!st.rejected) st.rejected = [];
    if (!st.intrigues) st.intrigues = [];
    if (!st.nextIntrigueId) st.nextIntrigueId = 1;
    if (st.direction.npcs === undefined) st.direction.npcs = true;
    if (st.direction.spicyFriction === undefined) st.direction.spicyFriction = false;
    if (!st.npcs) st.npcs = [];
    if (!st.nextNpcId) st.nextNpcId = 1;
    if (st.direction.arcs === undefined) st.direction.arcs = true;
    if (!st.arcs) st.arcs = [];
    if (!st.evolved) st.evolved = [];
    if (!st.nextArcId) st.nextArcId = 1;
    if (!Array.isArray(st.relationships)) st.relationships = [];
    if (!st.nextRelId) st.nextRelId = 1;
    if (st.direction.time === undefined) st.direction.time = true;
    if (!st.time) st.time = { date: '', country: '', countryName: '', city: '', flavor: '', flavorLocked: false, custom: [] };
    if (!Array.isArray(st.time.custom)) st.time.custom = [];
    if (!Array.isArray(st.time.timeline)) st.time.timeline = [];
    if (typeof st.direction.lines !== 'string') st.direction.lines = '';
    if (st.direction.wardrobe === undefined) st.direction.wardrobe = true;
    if (!st.wardrobe || typeof st.wardrobe !== 'object') st.wardrobe = { active: null, history: [] };
    if (!Array.isArray(st.wardrobe.history)) st.wardrobe.history = [];
    if (!Array.isArray(st.wardrobe.box)) st.wardrobe.box = [];
    if (!Array.isArray(st.wardrobe.closet)) st.wardrobe.closet = [];
    if (!st.wardrobe.nextClosetId) st.wardrobe.nextClosetId = 1;
    if (!Array.isArray(st.wardrobe.equipped)) st.wardrobe.equipped = [];
    if (!st.wardrobe.nextItemId) st.wardrobe.nextItemId = 1;
    st.wardrobe.box.forEach(item => {
        if (item && (typeof item.id !== 'number' || Number.isNaN(item.id))) {
            item.id = st.wardrobe.nextItemId++;
        }
    });
    if (st.direction.autoBoxItems === undefined) st.direction.autoBoxItems = false;
    if (st.direction.notes === undefined) st.direction.notes = false;
    if (st.direction.rels === undefined) st.direction.rels = true;
    if (st.direction.worldInject === undefined) st.direction.worldInject = true;
    if (st.direction.worldEvents === undefined) st.direction.worldEvents = true;
    if (st.worldProfile === undefined) st.worldProfile = null;
    if (!st.wallet || typeof st.wallet !== 'object') {
        st.wallet = { balance: 1200, currency: '£' };
    }
    if (typeof st.wallet.balance !== 'number' || Number.isNaN(st.wallet.balance)) st.wallet.balance = 0;
    if (!st.wallet.currency) st.wallet.currency = '£';
    if (st.direction.gacha === undefined) st.direction.gacha = false;
    if (!st.gacha || typeof st.gacha !== 'object') st.gacha = { active: null, pity: 0, spins: [], pending: null, total: 0, choices: [], nextChoiceId: 1 };
    if (!Array.isArray(st.gacha.spins)) st.gacha.spins = [];
    if (!Array.isArray(st.gacha.choices)) st.gacha.choices = [];
    if (!st.gacha.nextChoiceId) st.gacha.nextChoiceId = 1;
    if (st.direction.map === undefined) st.direction.map = false;
    if (st.direction.livingWorld === undefined) st.direction.livingWorld = false;
    if (st.direction.shopMode === undefined) {
        st.direction.shopMode = !!(st.worldProfile?.job && isShopOwnerJob(st.worldProfile.job)) || (st.wardrobe?.box || []).some(x => x.onCounter);
    }
    if (!st.map || typeof st.map !== 'object') st.map = { places: [], current: null, nextId: 1, enteredAt: 0 };
    if (!Array.isArray(st.map.places)) st.map.places = [];
    if (st.mainCharCard === undefined) st.mainCharCard = null;
    if (!Array.isArray(st.topics)) st.topics = [];
    if (!st.nextTopicId) st.nextTopicId = 1;
    if (!Array.isArray(st.trends)) st.trends = [];
    if (!st.nextTrendId) st.nextTrendId = 1;
    if (!st.home || typeof st.home !== 'object') {
        st.home = { roomName: 'Уютная комната', styleDesc: '', baseEn: '', image: '', placed: [] };
    }
    if (!Array.isArray(st.home.placed)) st.home.placed = [];
    if (!st.dynasty || typeof st.dynasty !== 'object') {
        st.dynasty = { userFamily: '', charFamily: '', socialCircle: '' };
    }
    if (!Array.isArray(st.neighborStories)) st.neighborStories = [];
    if (!Array.isArray(st.dreams)) st.dreams = [];
    if (typeof st.storySummary !== 'string') st.storySummary = '';
    if (typeof st.wardrobe.customAppearanceEn !== 'string') st.wardrobe.customAppearanceEn = '';
    ensureHolidayState(st);
    return st;
}

function formatNotes(notes) {
    if (!notes.length) return '(empty so far)';
    const len = ctx().chat?.length ?? 0;
    return notes
        .map(n => `#${n.id}${n.tag ? ` [${n.tag}]` : ''} (noted ${Math.max(0, len - n.at)} msgs ago${n.ff ? ', ⏩ already started in the chat' : ''}): ${n.text}`)
        .join('\n');
}

function buildDirection(st) {
    const parts = [buildGenreDirection(st)];
    // Направление определяется только выбранными жанрами без вшитых указаний на бытовые трения/ссоры
    if (st?.rejected?.length) {
        parts.push('The player rejected these ideas — don\'t suggest them or anything similar:\n' + st.rejected.map(t => `— ${t}`).join('\n'));
    }
    return parts.filter(Boolean).join('\n\n');
}

function buildGenreDirection(st) {
    const d = st?.direction;
    if (!d) return '';
    const genres = [...d.genres];
    const custom = d.customGenre?.trim();
    if (custom) genres.push(custom);
    const declared = d.lines?.trim();
    if (!genres.length && !declared) return '';
    const lines = ['STORY DIRECTION — the main rule for every notebook section (ideas, secrets, development):'];
    const hint = g => GENRE_HINTS[g] ? `${g} (${GENRE_HINTS[g]})` : g;
    if (genres.length === 1) {
        lines.push(`— genre: ${hint(genres[0])}.`);
    } else if (genres.length > 1 && d.mixMode === 'or') {
        lines.push(`— genres: ${genres.map(hint).join('; ')}. Each idea belongs to ONE of these genres — don't mix them inside one idea; alternate genres between ideas.`);
    } else if (genres.length > 1) {
        lines.push(`— genres: ${genres.map(hint).join('; ')}. Each idea must combine these genres at once.`);
    }
    if (genres.length) {
        lines.push('— the genre defines what ideas are built from and what is at stake. Suggest only what serves the chosen genre. Don\'t drag in elements of other genres: with light genres, introduce no external threats, bureaucracy, pursuit or danger — conflicts stay small, personal and solvable.');
        lines.push('— secrets, rumours and intrigues fit any genre — only their nature changes. In comedy and slice of life they are neighbours\' gossip, silly rumours, misunderstandings, a secret kept for a surprise, someone\'s hidden habits; in romance — a secret admirer, rumours of an affair, flings, jealousy, hidden feelings. Banning threats and danger doesn\'t cancel intrigue — just keep it light.');
    }
    if (declared) lines.push(`— DECLARED LINES — the player wants to see them in the story: ${declared}. Keep them alive: start arcs, secrets, rumours and ideas for them and bring these characters back into the plot from time to time, even if they have not come up for a while.`);
    lines.push('Don\'t break the logic of the story already under way.');
    return lines.join('\n');
}

function formatIntrigues(list) {
    if (!list.length) return '(none yet)';
    const len = ctx().chat?.length ?? 0;
    return list.map(it => {
        let line = `T${it.id}${it.tag ? ` [${it.tag}]` : ''} (started ${Math.max(0, len - it.at)} msgs ago): ${it.text}`;
        line += it.clues.length
            ? '\n   Already revealed to the player: ' + it.clues.map(c => c.text).join('; ')
            : '\n   The player knows nothing about it yet.';
        return line;
    }).join('\n');
}

function normName(x) {
    return String(x || '').trim().toLowerCase().replaceAll('ё', 'е');
}

function stripParenRole(nameStr) {
    return normName(nameStr).replace(/\([^)]*\)/g, ' ').replace(/\[[^\]]*\]/g, ' ').replace(/\s+/g, ' ').trim();
}

function matchesCharacterName(nameA, nameB) {
    const rawA = normName(nameA);
    const rawB = normName(nameB);
    if (!rawA || !rawB) return false;
    if (rawA === rawB) return true;
    const cleanA = stripParenRole(rawA);
    const cleanB = stripParenRole(rawB);
    if (!cleanA || !cleanB) return false;
    if (cleanA === cleanB) return true;
    const tokA = cleanA.split(/[\s-]+/).filter(t => t.length >= 2);
    const tokB = cleanB.split(/[\s-]+/).filter(t => t.length >= 2);
    if (!tokA.length || !tokB.length) return false;
    // Если одно имя — сокращённое («Наоя» или «Виктор»), а другое — полное («Наоя Дзэнин» или «Виктор Морозов»)
    const [shortToks, longToks] = tokA.length <= tokB.length ? [tokA, tokB] : [tokB, tokA];
    if (shortToks.every(st => st.length >= 3 && longToks.some(lt => lt === st || (lt.length >= 4 && st.length >= 4 && (lt.startsWith(st.slice(0, -1)) || st.startsWith(lt.slice(0, -1))))))) {
        return true;
    }
    return false;
}

function findNpc(st, name) {
    if (!st || !Array.isArray(st.npcs) || !name) return undefined;
    const key = normName(name);
    const exact = st.npcs.find(n => normName(n.name) === key || stripParenRole(n.name) === stripParenRole(key));
    if (exact) return exact;
    const fuzzyMatches = st.npcs.filter(n => matchesCharacterName(n.name, name));
    return fuzzyMatches.length === 1 ? fuzzyMatches[0] : undefined;
}

function findHeroOrNpc(st, name) {
    if (!st || !name) return null;
    const mc = ensureMainCharCard(st);
    const exactNpc = st.npcs?.find(n => normName(n.name) === normName(name));
    if (exactNpc) return exactNpc;
    if (mc && (normName(mc.name) === normName(name) || matchesCharacterName(mc.name, name))) return mc;
    return findNpc(st, name) || (nnbIsMainCharName(st, name, mc) ? mc : null);
}

function findRel(st, a, b) {
    return (st.relationships || []).find(r => {
        if (r.arrow === '→') return matchesCharacterName(r.a, a) && matchesCharacterName(r.b, b);
        return (matchesCharacterName(r.a, a) && matchesCharacterName(r.b, b)) || (matchesCharacterName(r.a, b) && matchesCharacterName(r.b, a));
    });
}

const REL_INJECT_HEADER = '[Relationships and ties between characters — the canon of their dynamics. Keep to these lines in conversations, glances, sympathies and arguments.]';

function getActiveSceneHeroSet(st) {
    const active = new Set();
    const names = storyNames();
    if (names.user) active.add(normName(names.user));
    if (names.char) active.add(normName(names.char));
    (names.chars || []).forEach(c => { if (c) active.add(normName(c)); });
    if (!st) return active;

    const chat = (ctx().chat || []).filter(m => m && !m.is_system && m.mes);
    const recentMsgsText = chat.slice(-4).map(m => `${m.name || ''}: ${m.mes || ''}`).join('\n');
    const compText = st.map?.currentCompanion || '';
    const curPlace = st.map?.current ? (st.map.places || []).find(p => p.id === st.map.current) : null;
    const placeText = curPlace ? `${curPlace.title || ''} ${curPlace.desc || ''}` : '';
    const combinedRecent = [recentMsgsText, compText, placeText].join('\n');

    for (const n of (st.npcs || [])) {
        if (!n || !n.name) continue;
        if (n.favorite || n.isMainChar || isNameMentionedInText(n.name, combinedRecent)) {
            active.add(normName(n.name));
        }
    }
    return active;
}

function isHeroActiveInCurrentScene(heroName, activeSet, st) {
    if (!heroName || !activeSet) return true;
    const k = normName(heroName);
    if (activeSet.has(k)) return true;
    for (const aName of activeSet) {
        if (matchesCharacterName(heroName, aName)) return true;
    }
    return false;
}

function formatRelationships(st, forThink = false) {
    const list = st?.relationships || [];
    if (!list.length) return '(none yet)';
    return list.map(r => {
        const arrow = r.arrow || '↔';
        const typeStr = r.type ? ` [${r.type}]` : '';
        if (forThink) {
            let line = `R${r.id} ${r.a} ${arrow} ${r.b}${typeStr}: ${r.desc || ''}`;
            if (r.locked) line += ' (edited by hand — don\'t change)';
            return line;
        }
        return `— ${r.a} ${arrow} ${r.b}${typeStr}: ${r.desc || ''}`;
    }).join('\n');
}

