function parseDailyMoodValue(val) {
    const v = String(val || '').toLowerCase().trim();
    if (!v) return '';
    if (/^(выкл|off|нет|none|-)$/i.test(v)) return 'off';
    if (DAILY_MOOD_OPTIONS[v]) return v;
    if (/взвод|устал|раздраж|колюч|нервн|резк/.test(v)) return 'edgy';
    if (/ревн|собствен|подозр/.test(v)) return 'jealous';
    if (/упрям|спор|принцип|вредн/.test(v)) return 'stubborn';
    if (/задет|обид|недопоним|прохлад|дуется|хмур/.test(v)) return 'sulky';
    if (/тепл|тёпл|хорош|споко|располож|добр/.test(v)) return 'warm';
    return '';
}

function friendshipTierLabel(val) {
    const v = Number(val) || 0;
    if (v <= -50) return '⚡ Враги';
    if (v <= -15) return '🌩 Холодность / неприязнь';
    if (v < 15) return '🤝 Знакомые';
    if (v < 45) return '🌱 Приятели';
    if (v < 75) return '💚 Друзья и доверие';
    return '🌟 Близкие люди';
}

function romanceTierLabel(val) {
    const v = Number(val) || 0;
    if (v < 10) return '⚪ Нет романтики';
    if (v < 30) return '🌸 Зарождающийся интерес';
    if (v < 55) return '💓 Симпатия и флирт';
    if (v < 80) return '💕 Влюблённость и химия';
    return '❤️ Глубокое чувство';
}

function sparkTierLabel(val) {
    const v = Number(val) || 0;
    if (v < 15) return '🍃 Спокойно (нейтрально / отдых)';
    if (v < 35) return '🌬 Лёгкий ветерок (мимолётный отклик)';
    if (v < 60) return '☀️ Мягкое тепло и нежная томность';
    if (v < 85) return '✨ Сильное волнение и сбившееся дыхание';
    return '🔥 На грани / Пик страсти и желания';
}

function sparkBodyInstruction(val) {
    const v = Number(val) || 0;
    if (v < 15) {
        return 'Спокойное, расслабленное состояние (обычный разговор, дела или мягкое послевкусие после близости).';
    }
    if (v < 35) {
        return 'Лёгкий, мимолётный отклик на взгляд, голос или запах (если сцена переходит к близости — мгновенно поднимается выше по логике сцены).';
    }
    if (v < 60) {
        return 'Мягкое, согревающее тепло и приятная томность без спешки и надрыва (хочется быть ближе и ловить касания).';
    }
    if (v < 85) {
        return 'Сильное, горячее волнение: глубокое сбившееся дыхание, чуткость кожи к каждому прикосновению и острое притяжение.';
    }
    return 'На грани / пик желания: предельное физическое и эмоциональное напряжение в разгар близости.';
}

function isRomanticTarget(n) {
    return !!(n && (n.isMainChar || n.favorite));
}

function ensureNpcScales(n, st) {
    if (!n) return n;
    const text = `${n.card || ''}`.toLowerCase();
    if (typeof n.friendship !== 'number' || Number.isNaN(n.friendship)) {
        if (/враг|ненави|соперни|неприязн/.test(text)) n.friendship = -30;
        else if (/лучш\S+ подруг|лучш\S+ друг|близк\S+ друг|детств/.test(text)) n.friendship = 65;
        else if (/друг|подруг|приятел|коллег|сосед/.test(text)) n.friendship = 30;
        else n.friendship = 10;
    }
    if (!isRomanticTarget(n)) {
        // Обычным NPC (коллегам, подругам, знакомым) влюблённость и возбуждение не приписываем!
        n.romance = 0;
        n.spark = 0;
    } else {
        if (typeof n.romance !== 'number' || Number.isNaN(n.romance)) {
            if (/муж|жена|возлюблен|парень|девушка|жених|невеста|встречаются/.test(text)) n.romance = 65;
            else n.romance = 0;
        }
        if (typeof n.spark !== 'number' || Number.isNaN(n.spark)) {
            n.spark = 0;
        }
    }
    if (!n.greenLight || !GREEN_LIGHT_OPTIONS[n.greenLight]) {
        if (/робк|застенчив|скромн|неуверен/.test(text)) n.greenLight = 'user_initiative';
        else if (/холодн|закрыт|строг|недоверчив|осторожн|интроверт/.test(text)) n.greenLight = 'deep_romance';
        else n.greenLight = 'emotional_trust';
    }
    if (!n.bodyStyle || !BODY_STYLE_OPTIONS[n.bodyStyle]) {
        if (/холодн|сдержан|спокойн|хладнокров|строг|вежлив|невозмутим/.test(text)) n.bodyStyle = 'composed_subtle';
        else if (/пылк|страстн|вспыльчив|горяч|импульсивн/.test(text)) n.bodyStyle = 'intense_active';
        else if (/игрив|весел|шутл|легк|обаятельн/.test(text)) n.bodyStyle = 'playful_tactile';
        else n.bodyStyle = 'soft_warm';
    }
    if (typeof n.turnOns !== 'string') n.turnOns = '';
    if (typeof n.turnOffs !== 'string') n.turnOffs = '';
    if (typeof n.appearanceEn !== 'string') n.appearanceEn = '';
    if (typeof n.petPeeves !== 'string') n.petPeeves = '';
    if (typeof n.jealousyTriggers !== 'string') n.jealousyTriggers = '';
    if (!n.dailyMood || !DAILY_MOOD_OPTIONS[n.dailyMood]) n.dailyMood = 'off';
    if (typeof n.dream !== 'string') n.dream = '';
    if (typeof n.fear !== 'string') n.fear = '';
    if (typeof n.likes !== 'string') n.likes = '';
    if (typeof n.dislikes !== 'string') n.dislikes = '';
    if (typeof n.publicRole !== 'string') n.publicRole = '';
    if (!n.intimateRole || !INTIMATE_ROLE_OPTIONS[n.intimateRole]) n.intimateRole = 'equal';
    if (!n.intimateStyle || !INTIMATE_STYLE_OPTIONS[n.intimateStyle]) n.intimateStyle = 'tender_harmony';
    if (!Array.isArray(n.intimateTags)) n.intimateTags = [];
    if (!Array.isArray(n.diary)) n.diary = [];

    n.friendship = Math.max(-100, Math.min(100, Math.round(n.friendship)));
    n.romance = Math.max(0, Math.min(100, Math.round(n.romance)));
    n.spark = Math.max(0, Math.min(100, Math.round(n.spark)));
    return n;
}

function ensureMainCharCard(st) {
    if (!st) return null;
    const charName = storyNames().char || 'Персонаж';
    if (!st.mainCharCard || typeof st.mainCharCard !== 'object') {
        const relHint = st.worldProfile?.charRel || '';
        st.mainCharCard = {
            isMainChar: true,
            name: charName,
            card: relHint && !st.worldProfile?.freeWorld ? `Основной персонаж истории (${relHint}).` : 'Основной персонаж карточки чата.',
            status: '',
            favorite: !st.worldProfile?.freeWorld,
            locked: false,
        };
    }
    st.mainCharCard.isMainChar = true;
    st.mainCharCard.name = charName;
    ensureNpcScales(st.mainCharCard, st);
    nnbMergeMainCharDuplicates(st, st.mainCharCard);
    return st.mainCharCard;
}

// Имя совпадает с основным персонажем («Карточка чата»)? В групповом чате карточка общая («A, B») — только точное совпадение.
// Латинская форма имени для сравнения «Бруно» ↔ «Bruno» (карточка Таверны на английском, ролевая на русском)
const NNB_RU_LAT = { а:'a', б:'b', в:'v', г:'g', д:'d', е:'e', ж:'zh', з:'z', и:'i', й:'y', к:'k', л:'l', м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u', ф:'f', х:'kh', ц:'ts', ч:'ch', ш:'sh', щ:'shch', ъ:'', ы:'y', ь:'', э:'e', ю:'yu', я:'ya' };
function nnbLatinName(name) {
    return [...stripParenRole(name)].map(ch => NNB_RU_LAT[ch] ?? ch).join('');
}
function nnbSameHeroName(a, b) {
    if (normName(a) === normName(b) || stripParenRole(a) === stripParenRole(b) || (!!nnbLatinName(a) && nnbLatinName(a) === nnbLatinName(b))) return true;
    // одинаковое число слов и каждое совпало по латинице («Кайлар» ↔ «Kylar»)
    const cnt = x => stripParenRole(x).split(/[\s-]+/).filter(t => t.length >= 2).length;
    return cnt(a) > 0 && cnt(a) === cnt(b) && nnbLatinTokensMatch(a, b);
}
// Строгое «это тот же человек» для заведения карточек: слова совпадают целиком, допускается только падежное окончание
// («Кайлара» = «Кайлар»), по-латински тоже («Бруно» = «Bruno»). «Кайла» ≠ «Кайлар», «Мира» ≠ «Мирон».
const NNB_RU_CASE_END = /^(?:а|я|у|ю|е|и|ы|ой|ей|ом|ем|ам|ям|ами|ями|ах|ях|ого|его|ому|ему)$/;
function nnbNameStrictSame(a, b) {
    if (!a || !b) return false;
    if (normName(a) === normName(b) || stripParenRole(a) === stripParenRole(b)) return true;
    const toks = x => stripParenRole(x).split(/[\s-]+/).filter(t => t.length >= 2);
    const tokEq = (x, y) => {
        if (x === y) return true;
        const lx = nnbLatinName(x), ly = nnbLatinName(y);
        if (lx && lx === ly) return true;
        if (/[a-z]/.test(x) !== /[a-z]/.test(y) && nnbLatinTokensMatch(x, y)) return true;
        const [sh, lg] = x.length <= y.length ? [x, y] : [y, x];
        // Кайлар → Кайлару/Кайларом. Но «+а/я» к согласной — это женское имя («Ян»/«Яна», «Александр»/«Александра»), не падеж
        if (lg.startsWith(sh) && NNB_RU_CASE_END.test(lg.slice(sh.length)) && !(/^[ая]$/.test(lg.slice(sh.length)) && /[^аяоеыиуюйь]$/.test(sh))) return true;
        // Аня → Ани, Мира → Миру, Этель → Этели/Этелью: общая основа + окончания
        const stemOf = w => w.replace(/(?:ью|ью|ь|[аяоеыиуюй]|ой|ей|ом|ем|ам|ям|ами|ями|ах|ях)$/, '');
        const sx = stemOf(x), sy = stemOf(y);
        const restOk = (w, st0) => { const r = w.slice(st0.length); return !r || r === 'ь' || r === 'ью' || NNB_RU_CASE_END.test(r); };
        const femVsMasc = (w1, w2) => /^[ая]$/.test(w1.slice(sx.length)) && w2 === sx && /[^аяоеыиуюйь]$/.test(w2);
        if (femVsMasc(x, y) || femVsMasc(y, x)) return false;
        return sx.length >= 2 && sx === sy && restOk(x, sx) && restOk(y, sy);
    };
    const A = toks(a), B = toks(b);
    if (!A.length || !B.length) return false;
    const [sh, lg] = A.length <= B.length ? [A, B] : [B, A];
    return sh.every(t => lg.some(u => tokEq(t, u)));
}
// Единая проверка «такой герой уже есть» для ВСЕХ мест, где заводится карточка (размышление, старт мира, ручное добавление):
// похожий кандидат ищется обычным поиском, но признаётся тем же только при строгом совпадении имени
function nnbFindSameHero(st, name) {
    if (!st || !name) return null;
    const mc = ensureMainCharCard(st);
    const cand = findHeroOrNpc(st, name) || (nnbIsMainCharName(st, name, mc) ? mc : null);
    if (cand && nnbNameStrictSame(cand.name, name)) return cand;
    // поиск мог вернуть «не того» похожего — проверим всех строго
    return [mc, ...(st.npcs || [])].find(h => h && nnbNameStrictSame(h.name, name)) || null;
}
function nnbIsMainCharName(st, name, mc = st?.mainCharCard) {
    if (!mc || !name) return false;
    if (nnbSameHeroName(mc.name, name)) return true;
    const isGroup = (storyNames().chars || []).length > 1;
    return !isGroup && (matchesCharacterName(mc.name, name) || nnbLatinTokensMatch(mc.name, name));
}
// «Бруно Буччеллати» ↔ «Bruno»: все слова короткого имени совпадают со словами длинного (по латинице, целиком — без префиксов,
// чтобы «Брунгильда» не стала «Bruno»)
function nnbLatinTokensMatch(a, b) {
    const toks = x => stripParenRole(x).split(/[\s-]+/).filter(t => t.length >= 2)
        .map(t => new Set(/[а-я]/.test(t) ? [nnbLatinName(t), ...transliterateRuNameVariants(t)] : [t]));
    const A = toks(a), B = toks(b);
    if (!A.length || !B.length) return false;
    const [sh, lg] = A.length <= B.length ? [A, B] : [B, A];
    return sh.every(set => lg.some(set2 => [...set].some(v => v.length >= 3 && set2.has(v))));
}

const NNB_MC_DEFAULT_CARD_RE = /^Основной персонаж (?:карточки чата|истории \([^)]*\))\.$/;
const NNB_MC_KEEP_KEYS = new Set(['appearanceEn', 'avatar', 'bodyStyle']); // то, что пользователь задаёт руками в «Карточке чата» (канон Danbooru, аватар)
// то, что тег [SPARK…] в каждом ответе пишет прямо в «Карточку чата» — там оно свежее, чем в двойнике
const NNB_MC_LIVE_KEYS = new Set(['status', 'spark', 'dailyMood']);

// Переносит всё из NPC-двойника в «Карточку чата». Двойник был «живой» копией: размышление писало в него
// (findHeroOrNpc отдаёт NPC раньше карточки чата), поэтому его шкалы, статус, профиль и дневник новее.
// Внешность/аватар — из карточки чата, если там заполнено (туда ставят канон-тег через «Найти канон Danbooru»).
function nnbMergeNpcIntoMainCard(st, mc, dup) {
    const backup = JSON.parse(JSON.stringify(dup));
    const mcCard = String(mc.card || '').trim();
    const dCard = String(dup.card || '').trim();
    if (!mcCard || NNB_MC_DEFAULT_CARD_RE.test(mcCard)) mc.card = dCard || mcCard;
    else if (dCard && !mcCard.toLowerCase().includes(dCard.toLowerCase().slice(0, 60))) mc.card = `${mcCard}\n${dCard}`;
    const empty = v => v === undefined || v === null || (typeof v === 'string' && !v.trim()) || (Array.isArray(v) && !v.length);
    for (const [k, v] of Object.entries(dup)) {
        if (['id', 'name', 'isMainChar', 'card', 'at'].includes(k) || k.startsWith('_')) continue;
        if (empty(v)) continue;
        if (k === 'favorite' || k === 'locked') { mc[k] = !!(mc[k] || v); continue; }
        if (NNB_MC_LIVE_KEYS.has(k)) {
            const mcHas = k === 'spark' ? Number(mc.spark) > 0 : k === 'dailyMood' ? (mc.dailyMood && mc.dailyMood !== 'off') : !empty(mc[k]);
            if (!mcHas) mc[k] = v;
            continue;
        }
        if (NNB_MC_KEEP_KEYS.has(k)) {
            const keepMc = !empty(mc[k]) && !(k === 'appearanceEn' && !parseCanonFromAppearance(mc[k]) && parseCanonFromAppearance(v));
            if (!keepMc) mc[k] = v;
            continue;
        }
        if (Array.isArray(v)) {
            const base = Array.isArray(mc[k]) ? mc[k] : [];
            const seen = new Set(base.map(x => JSON.stringify(x)));
            mc[k] = base.concat(v.filter(x => !seen.has(JSON.stringify(x))));
            continue;
        }
        mc[k] = v;
    }
    st.npcs = st.npcs.filter(x => x !== dup);
    // имя двойника отличалось («Бруно» при карточке «Bruno») — переводим на имя карточки его связи и память одежды
    if (normName(dup.name) !== normName(mc.name)) {
        for (const r of (st.relationships || [])) {
            if (normName(r.a) === normName(dup.name)) r.a = mc.name;
            if (normName(r.b) === normName(dup.name)) r.b = mc.name;
        }
        const ko = x => String(x || '').toLowerCase().replace(/ё/g, 'е');
        if (st.heroOutfits && st.heroOutfits[ko(dup.name)] && !st.heroOutfits[ko(mc.name)]) {
            st.heroOutfits[ko(mc.name)] = st.heroOutfits[ko(dup.name)];
            delete st.heroOutfits[ko(dup.name)];
        }
    }
    if (!Array.isArray(st.mergedDuplicates)) st.mergedDuplicates = [];
    st.mergedDuplicates.push({ at: Date.now(), into: mc.name, npc: backup });
    st.mergedDuplicates = st.mergedDuplicates.slice(-5);
    console.log(`[npc_notebook] merged duplicate NPC «${dup.name}» into the chat card`);
}

function nnbMergeMainCharDuplicates(st, mc) {
    if (!st || !mc || !Array.isArray(st.npcs) || !st.npcs.length) return 0;
    // строго: «Кайлар (молодой)» — возможно другой человек, такое только кнопкой «Это основной персонаж»
    const paren = x => (normName(x).match(/\([^)]*\)|\[[^\]]*\]/g) || []).join(' ');
    const dups = st.npcs.filter(x => x && !x.isMainChar && paren(x.name) === paren(mc.name) && nnbSameHeroName(x.name, mc.name));
    if (!dups.length) return 0;
    dups.forEach(d => nnbMergeNpcIntoMainCard(st, mc, d));
    try {
        const c = ctx();
        if (typeof c.saveMetadataDebounced === 'function') c.saveMetadataDebounced();
        else c.saveMetadata?.();
    } catch (e) { /* ignore */ }
    try { toastr.info(`Двойник «${mc.name}» объединён с «Карточкой чата»: всё перенесено, лишняя карточка убрана.`, 'Блокнот рассказчика'); } catch (e) { /* ignore */ }
    return dups.length;
}

// Для рассказчика — без цифр: голое «дружба 45/100» модели переписывают прямо в пост. Цифры нужны только размышлению блокнота.
function nnbTierWords(label) { return String(label || '').replace(/^[^\p{L}]+/u, '').trim().toLowerCase(); }
function formatNpcScaleSummary(n, forThink = false) {
    ensureNpcScales(n);
    if (!forThink) {
        const rel = isRomanticTarget(n)
            ? `${nnbTierWords(friendshipTierLabel(n.friendship))}; romantically — ${nnbTierWords(romanceTierLabel(n.romance))}`
            : nnbTierWords(friendshipTierLabel(n.friendship));
        const moodObj = isRomanticTarget(n) && n.dailyMood && n.dailyMood !== 'off' ? DAILY_MOOD_OPTIONS[n.dailyMood] : null;
        return `(internal, never put into the text) with {{user}}: ${rel}.${moodObj?.label ? ` Mood: ${nnbTierWords(moodObj.label)}.` : ''}`;
    }
    if (!isRomanticTarget(n)) {
        return `Отношение к {{user}}: ${n.friendship}/100 (${friendshipTierLabel(n.friendship)}).`;
    }
    const parts = [`Отношение к {{user}}: дружба ${n.friendship}/100 (${friendshipTierLabel(n.friendship)}), романтика ${n.romance}/100 (${romanceTierLabel(n.romance)}).`];
    const moodObj = (n.dailyMood && n.dailyMood !== 'off') ? DAILY_MOOD_OPTIONS[n.dailyMood] : null;
    if (moodObj && moodObj.label) parts.push(`Тонус: ${moodObj.label}.`);
    return parts.join(' ');
}

function formatNpcs(list, forThink = false, st = store(), mode = 'all') {
    const all = [];
    if (st) {
        const mc = ensureMainCharCard(st);
        if (mc && (!st.worldProfile?.freeWorld || mc.locked || mc.romance > 0 || mc.friendship !== 10 || mc.status || mc.turnOns || mc.dream || mc.fear || mc.likes)) {
            all.push(mc);
        }
    }
    const sorted = [...(list || [])].sort((a, b) => (!!b.favorite - !!a.favorite) || a.id - b.id);
    all.push(...sorted);
    if (!all.length) return (mode === 'active' || mode === 'sleeping') ? '' : '(none yet)';
    const useSmartFocus = !forThink && settings().tokenSaverMode !== false && all.length > 3;
    const activeSet = useSmartFocus ? getActiveSceneHeroSet(st) : null;
    const fullLines = [];
    const sleepingLines = [];

    for (const n of all) {
        ensureNpcScales(n, st);
        const isActive = !useSmartFocus || n.isMainChar || n.favorite || isHeroActiveInCurrentScene(n.name, activeSet, st);
        if (isActive) {
            const favTag = n.favorite ? ' (the player\'s main favourite)' : '';
            const formattedCard = String(n.card || '').trim().replace(/\n+/g, '\n   ');
            let line = `— ${n.name}${favTag}: ${formattedCard}`;
            if (forThink) line += ' (do NOT shorten or rewrite the existing description — if important new facts about this character came out in the chat, add them via NPCFACT)';
            if (n.status) line += `\n   ${forThink ? 'Сейчас' : 'Now'}: ${n.status}`;
            line += `\n   ${formatNpcScaleSummary(n, forThink)}`;
            fullLines.push(line);
        } else {
            // Если карточка короткая (до 420 символов) — не режем её вообще! Сжимаем только огромные многоабзацные досье отсутствующих за кадром НПС,
            // оставляя первые ~420 символов (кто это + внешность + характер), статус, шкалу дружбы и мечту/вкусы, чтобы при внезапном входе в сцену модель знала их внешность и манеру речи!
            const rawCard = String(n.card || '').replace(/\s*\/\/\s*/g, ' ').replace(/\s+/g, ' ').trim();
            let shortBio = rawCard;
            if (rawCard.length > 420) {
                const cut = rawCard.slice(0, 420);
                const lastDot = Math.max(cut.lastIndexOf('.'), cut.lastIndexOf('!'), cut.lastIndexOf(';'));
                shortBio = (lastDot > 180 ? cut.slice(0, lastDot + 1) : cut + '…');
            }
            const extraTraits = [
                n.status ? `${forThink ? 'Сейчас' : 'Now'}: ${n.status}` : '',
                forThink ? `Дружба: ${n.friendship}/100 (${friendshipTierLabel(n.friendship)})` : `with {{user}}: ${nnbTierWords(friendshipTierLabel(n.friendship))}`,
                n.dream ? `${forThink ? 'Мечта' : 'Dream'}: ${n.dream}` : '',
                n.likes ? `${forThink ? 'Любит' : 'Likes'}: ${n.likes}` : '',
            ].filter(Boolean).join(' | ');
            sleepingLines.push(`— ${n.name}: ${shortBio}${extraTraits ? ` [${extraTraits}]` : ''}`);
        }
    }

    if (mode === 'active') {
        return fullLines.join('\n');
    }
    if (mode === 'sleeping') {
        return sleepingLines.length
            ? `[Secondary acquaintances off-screen (not in the scene now — reference only; don't mix up their looks with the characters in the current scene):\n${sleepingLines.join('\n')}]`
            : '';
    }
    if (sleepingLines.length) {
        fullLines.push(`\n[Secondary acquaintances off-screen (not in the scene now — short reference):\n${sleepingLines.join('\n')}]`);
    }
    return fullLines.join('\n');
}

function buildNpcSection(st) {
    if (!st?.direction?.npcs) return '';
    const charName = storyNames().char;
    const relsOn = st.direction.rels !== false; // модуль «🔗 Связи между героями» выключен — не просим и не показываем связи
    return `Characters, their current state in the scene${relsOn ? ', and their ties' : ''}. Write all command content in Russian.

Current cards and state:
${formatNpcs(st.npcs, true, st)}
${relsOn ? `
Ties and relationships between characters:
${formatRelationships(st, true)}
` : ''}
Commands for them (one per line, together with the rest):
NPC [Name]: a full, detailed description for NEW characters not yet in the list above — including ones only mentioned so far (a relative, an ex, a colleague) as soon as the messages give their name or details (put ALL important details of looks, biography, personality, profession and facts the player gave into one line, no limit on sentences).
NPCFACT [Name]: a new important fact for an EXISTING character (1–4 sentences on one line). Use it ONLY when the latest messages revealed a significant detail of biography, looks, past, personality or an important turn in relationships that is not in the card yet. This also covers what came out about them personally: what really hooks them or, on the contrary, cools them and pushes them away, what they fear, dream of, love and can't stand (write it as a living fact about the character, not as a list). The old description is NOT erased — the new fact is appended to its end (don't record petty everyday trivia from a single scene!).
NPCSTATE [Name]: what the character is doing RIGHT NOW in the last 1–2 chat messages (always update it for ${charName} and the NPCs present in the scene! If the previous scene — intimacy, an argument, a trip — ended several posts ago, replace the old status with what the character is doing now).
SCALE [Name]: дружба=number_or_shift | романтика=number_or_shift — update the scales if the relationship noticeably changed (for ordinary NPCs — only «дружба=...»).${relsOn ? `
REL [Name1 ↔ Name2]: type | how they feel about each other (or REL [Name1 → Name2]).
DROP #R1 — if the tie fell apart.` : ''}`;
}
function formatArcs(st, forThink = false, includeEvolved = true) {
    const need = Math.max(1, Number(settings().minStimuli) || 2);
    const lines = st.arcs.map(a => {
        const stg = ARC_STAGES[a.stage];
        let line = forThink
            ? `A${a.id} ${a.who}: ${a.text}. Stage ${a.stage}/${ARC_MAX} (${stg.name}).`
            : `${a.who} — ${a.text} [${a.stage}/${ARC_MAX} «${stg.name}»].`;
        if (a.current) line += ` Now: ${a.current}`;
        if (forThink) {
            line += `\n   Stimuli since the last shift: ${a.sinceShift} of ${need} needed.`;
            if (a.stimuli.length) line += '\n   Stimuli: ' + a.stimuli.map(x => x.text).join('; ');
        }
        return line;
    });
    if (includeEvolved && st.evolved.length) {
        lines.push('Settled changes:\n' + st.evolved.map(e => `— ${e.who}: ${e.text}`).join('\n'));
    }
    return lines.length ? lines.join('\n') : '(none yet)';
}

// Если все арки касаются только главного персонажа — подталкиваем модель к NPC
function npcArcNudge(st) {
    const charName = ctx().name2 || '';
    const norm = x => String(x || '').toLowerCase().replace(/ё/g, 'е');
    const arcsAboutNpc = st.arcs.filter(a => norm(a.who) !== norm(charName)).length;
    if (arcsAboutNpc || !st.npcs.length) return '';
    return `\nThere are no arcs for the NPCs or their relationships yet. Look at the NPC cards (${st.npcs.slice(0, 6).map(n => n.name).join(', ')}) and the lines between them — start an arc for at least one if the story gives it ground.\n`;
}

function buildArcSection(st) {
    if (!st?.direction?.arcs) return '';
    const need = Math.max(1, Number(settings().minStimuli) || 2);
    const stages = ARC_STAGES.slice(1).map((x, i) => `${i + 1}. ${x.name} — ${x.hint}`).join('\n');
    return `Character development arcs (stages 1–${ARC_MAX}, a shift after ${need} stimuli; the core personality stays):
${formatArcs(st, true)}
${npcArcNudge(st)}Commands (content in Russian): ARC [Name or Name + Name]: was → where it is heading | STIMULUS #A1: a real push from the chat | SHIFT #A1: move to the next stage | REGRESS #A1: roll back | DROP #A1 — close.`;
}

function buildIntrigueSection(st) {
    if (!st?.direction?.intrigues) return '';
    const max = Math.max(1, Number(settings().maxIntrigues) || 5);
    return `Secrets and intrigues (max ${max}):
${formatIntrigues(st.intrigues)}
Commands (content in Russian): INTRIGUE [тайна|загадка|слух|интрига]: the truth behind it | CLUE #T1: what was actually revealed in the chat | SOLVED #T1 | DROP #T1.`;
}

function fillTemplate(template, notes, direction = '', intrigues = '', npcs = '', arcs = '', time = '', wardrobe = '') {
    const c = ctx();
    const MARK = '\u0001NNB_NOTES\u0001';
    const DMARK = '\u0001NNB_DIR\u0001';
    const IMARK = '\u0001NNB_INT\u0001';
    const NMARK = '\u0001NNB_NPC\u0001';
    const AMARK = '\u0001NNB_ARC\u0001';
    const TMARK = '\u0001NNB_TIME\u0001';
    const WMARK = '\u0001NNB_WARD\u0001';
    const withMark = c.substituteParams(template
        .replaceAll('{{notes}}', MARK)
        .replaceAll('{{direction}}', DMARK)
        .replaceAll('{{intrigues}}', IMARK)
        .replaceAll('{{npcs}}', NMARK)
        .replaceAll('{{arcs}}', AMARK)
        .replaceAll('{{time}}', TMARK)
        .replaceAll('{{wardrobe}}', WMARK));
    return withMark
        .replaceAll(MARK, formatNotes(notes))
        .replaceAll(DMARK, direction)
        .replaceAll(IMARK, intrigues)
        .replaceAll(NMARK, c.substituteParams(npcs))
        .replaceAll(AMARK, c.substituteParams(arcs))
        .replaceAll(TMARK, c.substituteParams(time))
        .replaceAll(WMARK, c.substituteParams(wardrobe))
        .replace(/\n{3,}/g, '\n\n');
}


function livingWorldOn(st) {
    return st?.direction?.livingWorld !== false;
}

function buildWorldProfileInjection(st) {
    if (!st || st.direction?.worldInject === false) return '';
    const wp = st.worldProfile;
    const user = storyNames().user;
    const parts = [];
    if (wp) {
        if (wp.home) parts.push(`— ${user}'s home: ${wp.home}.`);
        if (wp.startVibe) parts.push(`— Starting point: ${wp.startVibe}.`);
        if (wp.job) parts.push(`— ${user}'s job / occupation: ${wp.job}.`);
        if (Array.isArray(wp.hobbies) && wp.hobbies.length) parts.push(`— ${user}'s hobbies: ${wp.hobbies.join(', ')}.`);
        if (wp.wealth) parts.push(`— Means: ${wp.wealth}.`);
        if (wp.pet && wp.pet !== 'Без питомца') parts.push(`— Pet: ${wp.pet}.`);
        if (wp.freeWorld) {
            const favs = (st.npcs || []).filter(n => n.favorite).map(n => n.name);
            if (favs.length) {
                parts.push(`— Open-world play: ${user}'s main focus and romantic/plot interest is now the favourite from the notebook (${favs.join(', ')}). The world stays alive and open to explore.`);
            } else {
                parts.push(`— Open-world play (no single starting favourite): don't handcuff ${user} to one character in every scene. Let ${user} explore the world freely, live her own life, talk to different people and meet potential love interests along the way.`);
            }
        } else if (wp.charRel && wp.charRel !== 'По первому сообщению чата') {
            parts.push(`— Starting tie with the main character: ${wp.charRel}.`);
        }
    }
    if (st.dynasty?.userFamily) parts.push(`— ${user}'s family: ${st.dynasty.userFamily}.`);
    if (st.dynasty?.charFamily) parts.push(`— ${storyNames().char}'s family and close circle: ${st.dynasty.charFamily}.`);
    if (st.dynasty?.socialCircle) parts.push(`— Social circle (neighbours, colleagues, acquaintances): ${st.dynasty.socialCircle}.`);
    if (Array.isArray(st.home?.placed) && st.home.placed.length) {
        const placedStr = st.home.placed.map(p => {
            const it = (st.wardrobe?.box || []).find(x => x.id === p.itemId);
            return it ? `«${it.title}» (${p.spot})` : '';
        }).filter(Boolean).join(', ');
        if (placedStr) parts.push(`— Keepsakes placed in ${user}'s room at home: ${placedStr}.`);
    }
    if (Array.isArray(st.trends) && st.trends.length) {
        const trStr = st.trends.map(t => `«${t.title}» [${t.category}] (${t.desc})`).join('; ');
        parts.push(`— 🔥 In fashion and trending in the city now: ${trStr}. IMPORTANT — NO POSITIVE BIAS FROM RELATIONSHIPS: any character's attitude to a trend depends ONLY on their personality, taste, scepticism, pragmatism or hidden weaknesses, NOT on whether they are friend or foe! A close friend or the favourite may well laugh at the hype and call it a silly waste of money, while a gloomy sceptic, a rival or a strict character may turn out to be a secret fan.`);
    }
    if (!parts.length) return '';
    return `[Profile of the world, surroundings and the character (${user}) — story canon:\n` + parts.join('\n') + ']';
}

function buildEphemeralWorldEventsInjection(st) {
    if (!st || st.direction?.worldEvents === false) return '';
    const parts = [];
    const recentStory = (st.neighborStories || []).slice(-1)[0];
    if (recentStory && (ctx().chat?.length ?? 0) - (recentStory.at || 0) <= 4) {
        parts.push(`[🏘 Recent news among the NPCs: ${recentStory.text}.]`);
    }
    const activeDreams = (st.dreams || []).filter(d => d.active && (ctx().chat?.length ?? 0) - (d.at || 0) <= 3);
    if (activeDreams.length) {
        parts.push(`[🌙 A recent dream/nightmare (may surface once): ${activeDreams.map(d => `${d.who} (${d.kind === 'nightmare' ? 'nightmare' : 'dream'}): ${d.text}`).join('; ')}.]`);
    }
    return parts.join('\n');
}

function buildLivingWorldInjection(st, includeWorldProfile = true) {
    const profBlock = includeWorldProfile ? buildWorldProfileInjection(st) : '';
    if (!st || !livingWorldOn(st)) return profBlock;
    const len = ctx().chat?.length ?? 0;
    const names = storyNames();
    const curPlace = mapOn(st) && st.map?.current ? st.map.places.find(p => p.id === st.map.current) : null;
    const justEntered = curPlace && (st.map.enteredAt === undefined || len - st.map.enteredAt <= 1);
    const compRule = '';
    let lwBlock = '';
    if (curPlace && justEntered) {
        const locLine = `Current location (the characters have just arrived): «${curPlace.title}»${curPlace.desc ? ` (${curPlace.desc})` : ''}${curPlace.hooks ? `. Hooks of this place for the first impression: ${curPlace.hooks}` : ''}.\n`;
        lwBlock = `[Living world — first impression of the location:
${locLine}On entering, weave 1–2 lively details or points of interest from the place's hooks into the scene so the location feels alive. After the first mention do NOT repeat the same hooks in the following replies unless the player draws attention to them.${compRule}]`;
    } else if (curPlace) {
        lwBlock = `[Current location: «${curPlace.title}». Don't repeat the location's background details and hooks from post to post.]`;
    } else {
        lwBlock = '';
    }
    return [profBlock, lwBlock].filter(Boolean).join('\n\n');
}

function buildActionPromptsInjection() {
    const user = storyNames().user;
    const st = store();
    const poiLine = (st && livingWorldOn(st))
        ? `\n— If the scene has points of interest, unusual details of the surroundings, background vignettes or location hooks, at least one option must invite ${user} to explore, examine or play off that hook of the world.`
        : '';
    return `[Action hints: at the very end of your reply add one hidden service line with three options for the player's (${user}) next move — what ${user} HERSELF could do or say in response to what is happening. Write the options in the language of the roleplay:
<!--ACTIONS: option 1 | option 2 | option 3-->
Requirements:
— All 3 options are actions and lines of ${user} HERSELF (what ${user} will do or say), NOT other characters' actions towards her! No "hand ${user} something", "ask ${user}", "stroke ${user}" — only ${user} acts.
— The three options must differ substantially in meaning and tone (not rephrasings of one thought).
— Each option takes the scene in a different direction: mix forms (direct speech by ${user}, a physical action or gesture, a pause/silence, a change of topic, an unexpected reaction).${poiLine}
— Keep them short (1–2 phrases) so ${user} can send an option as her move. The line is invisible to the player; never mention it in the main text of the reply.]`;
}

// ===== 💧 Задумки «экономно»: в каждом ответе рассказчику одна активная задумка одной строкой =====
// Задумка держится NNB_DRIP_SPAN ответов подряд (чтобы модель успела подвести к ней естественно), потом сменяется следующей
const NNB_DRIP_SPAN = 3;
function nnbDripState(st) {
    if (!st.notesDrip || typeof st.notesDrip !== 'object') st.notesDrip = {};
    if (st.notesDrip.activeId === undefined) st.notesDrip.activeId = null;
    if (!Number.isFinite(st.notesDrip.shown)) st.notesDrip.shown = 0;
    return st.notesDrip;
}
function nnbDripPickNote(st, exceptId = null) {
    const pool = (st.notes || []).filter(n => !n.ff && n.id !== exceptId && (Number(n.dripCount) || 0) < 3 && nnbDirectorAfterMet(st, n) && nnbDirectorDateOk(st, n));
    if (!pool.length) return null;
    // реже всего подсказанная, при равенстве — самая старая
    return pool.slice().sort((a, b) => (Number(a.dripCount) || 0) - (Number(b.dripCount) || 0) || (Number(a.at) || 0) - (Number(b.at) || 0))[0];
}
function nnbDripInjection(st) {
    const mode = st?.direction?.notes;
    if (mode === 'director') { try { nnbPlansTick(st); } catch (e) { /* ignore */ } }
    if (mode === 'director' && !(st.notes || []).length) return nnbDirectorContinuityLine(st);
    if ((mode !== 'drip' && mode !== 'director') || !(st.notes || []).length) return '';
    const d = nnbDripState(st);
    let note = d.activeId != null ? st.notes.find(n => n.id === d.activeId && !n.ff) : null;
    if (!note) {
        note = mode === 'director' ? nnbDirectorPick(st) : nnbDripPickNote(st);
        if (!note) return mode === 'director' ? nnbDirectorContinuityLine(st) : '';
        d.activeId = note.id;
        d.shown = 0;
        d.tech = null; d.needCheck = null; d.waitReplies = 0;
    }
    if (mode === 'director') {
        const cont = nnbDirectorContinuityLine(st);
        // предпосылки: странно начинать «подружка невесты», когда едва знакомы — сначала мостик
        let ready = nnbDirectorReadiness(st, note);
        if (ready === 'bridge') {
            const br = note.bridge ? nnbDirectorMakeBridge(st, note, note.bridge) : null;
            if (br) { d.activeId = br.id; d.shown = 0; d.tech = null; d.needCheck = null; d.waitReplies = 0; note = br; ready = 'ready'; }
            else ready = 'check';
        }
        if (ready === 'check') {
            if (d.needCheck !== note.id) { d.needCheck = note.id; d.waitReplies = 0; }
            d.sinceThink = true;
            if ((Number(d.waitReplies) || 0) < 6) return cont; // ждём, пока размышление решит: READY или BRIDGE
        }
        if (!d.tech || d.tech.noteId !== note.id) {
            const t = nnbDirectorPickTechnique(st, note);
            d.tech = { ...t, noteId: note.id };
            const dx = nnbDirectorExtra(st);
            dx.techHistory.push(t.id);
            if (dx.techHistory.length > 20) dx.techHistory.splice(0, dx.techHistory.length - 20);
        }
        const line = nnbDirectorLineOf(st, note.line);
        const meta = [line ? `line «${line.name}»` : '', note.genre ? `genre ${note.genre}` : '', note.intensity ? `intensity ${note.intensity}/5` : '', (note.chars || []).length ? `characters: ${note.chars.join(', ')}` : ''].filter(Boolean).join('; ');
        void meta;
        return `${nnbDirectorSceneBrief(st, note, d.tech)}${cont ? `\n${cont}` : ''}`;
    }
    return `[Author's idea for the next few replies: ${note.text}. Lead up to it in this or the following replies when it fits naturally, without cutting the current episode off; never mention the notebook.]`;
}
// ===== 🎬 Режиссёр: задумки разложены по сюжетным линиям с целевой долей; следующей берётся задумка из самой «отстающей» линии =====
const NNB_DIR_GENRES = ['plot', 'drama', 'comedy', 'fluff', 'angst', 'chaos', 'slice'];
function nnbDirector(st) {
    if (!st.director || typeof st.director !== 'object') st.director = {};
    const d = st.director;
    if (!Array.isArray(d.lines) || !d.lines.length) d.lines = [
        { id: 'main_plot', name: 'Основной сюжет', color: '#ef4444', target: 35 },
        { id: 'relations', name: 'Отношения и коллектив', color: '#3b82f6', target: 35 },
        { id: 'romance', name: 'Романтика', color: '#ec4899', target: 30 },
    ];
    if (!Array.isArray(d.history)) d.history = [];
    if (typeof d.summary !== 'string') d.summary = '';
    return d;
}
function nnbDirectorBalance(st) {
    const d = nnbDirector(st);
    const total = d.history.length || 0;
    return d.lines.map(l => {
        const count = d.history.filter(h => h.line === l.id).length;
        const pct = total ? Math.round(count / total * 100) : 0;
        return { ...l, count, pct, deficit: (Number(l.target) || 0) - pct };
    });
}
function nnbDirectorLineOf(st, tag) {
    const d = nnbDirector(st);
    const t = String(tag || '').trim().toLowerCase();
    if (!t) return null;
    return d.lines.find(l => l.id.toLowerCase() === t || l.name.toLowerCase() === t || l.name.toLowerCase().includes(t) || t.includes(l.id.toLowerCase())) || null;
}
// Выбор следующей задумки: линия с наибольшим отставанием от цели; внутри — темп (после тяжёлой сцены — полегче) и реже подсказанные
function nnbDirectorPick(st, exceptId = null, excludeIds = null) {
    const allNotes = st.notes || [];
    const pool = allNotes.filter(n => !n.ff && n.id !== exceptId && !(excludeIds && excludeIds.has(n.id)) && (Number(n.dripCount) || 0) < 3
        && !allNotes.some(b => b.bridgeFor === n.id && !b.ff) // у задумки есть мостик — сначала он
        && nnbDirectorAfterMet(st, n) // подводки и предыдущие сцены цепочки ещё не сыграны
        && nnbDirectorDateOk(st, n)); // событие из календаря — только в свой день; подготовка — только до него
    if (!pool.length) return null;
    const bal = nnbDirectorBalance(st);
    const deficitOf = id => (bal.find(b => b.id === id)?.deficit ?? -999);
    const lastShown = st.notesDrip?.lastShown || null;
    const lastInt = Number(lastShown?.intensity) || Number(nnbDirector(st).history.slice(-1)[0]?.intensity) || 0;
    const today = st.time?.date || '';
    // задумка привязана к дате («(5 апреля)», «05.04») — раньше этой даты не подсовываем
    const notYet = n => {
        if (!today) return false;
        const m = String(`${n.title || ''} ${n.text || ''}`).match(/\b(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)(?![а-яё])|\b(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?\b/i);
        if (!m) return false;
        const iso = parseDateText(m[0], today);
        return !!(iso && iso > today);
    };
    const score = n => {
        let sc = n.line ? deficitOf(n.line) : -50;
        if (notYet(n)) sc -= 1000;
        if (lastShown?.line && n.line === lastShown.line) sc -= 6; // чередуем линии
        const it = Number(n.intensity) || 3;
        if (lastInt >= 4 && it >= 4) sc -= 15; // два тяжёлых эпизода подряд — нет
        if (lastInt && lastInt <= 2 && it >= 3) sc += 5; // после лёгкого можно поднять накал
        sc -= (Number(n.dripCount) || 0) * 10;
        if (n.bridgeFor != null) sc += 4;
        // календарь: в день события — оно; чем ближе дата, тем раньше подготовка к нему
        if (n.planRole === 'event' && n.onDate && today && n.onDate <= today) sc += 500;
        if (n.planRole === 'prep' && n.deadline && today) sc += Math.max(0, 60 - 8 * daysBetween(today, n.deadline));
        // пожелания игрока: выбранная линия и жанр идут первыми (пусто — режиссёр решает сам по балансу)
        const pr = st.director?.prefs;
        if (pr?.line && n.line === pr.line) sc += 100;
        if (pr?.genre && n.genre === pr.genre) sc += 30;
        return sc;
    };
    const best = pool.slice().sort((a, b) => score(b) - score(a) || (Number(a.at) || 0) - (Number(b.at) || 0))[0];
    return best && notYet(best) ? null : best;
}
// Сыгранная задумка → история режиссёра (для баланса линий)
function nnbDirectorRecord(st, n) {
    if (!n || !n.line) return;
    const d = nnbDirector(st);
    d.history.push({ id: 'h' + (d.history.length + 1), title: n.title || String(n.text || '').slice(0, 80), line: n.line, genre: n.genre || '', intensity: Number(n.intensity) || 3, characters: n.chars || [], date: st.time?.date || '' });
    if (d.history.length > 200) d.history.splice(0, d.history.length - 200);
}
// Импорт из «ИИ-Режиссёр v4» (JSON: lines / ideas / history / contextSummary)
// Поля расписанной сцены из импортируемого объекта (если они там есть)
function nnbSceneFieldsFrom(it) {
    const o = {};
    for (const k of ['place', 'mood', 'pace', 'link', 'avoid']) if (it?.[k] && String(it[k]).trim()) o[k] = String(it[k]).trim();
    if (Array.isArray(it?.beats) && it.beats.length) o.beats = it.beats.map(String).filter(Boolean);
    if (Number(it?.dynamics) > 0) o.dynamics = Math.min(5, Number(it.dynamics));
    if (['main', 'bridge', 'after'].includes(it?.kind)) o.kind = it.kind;
    for (const k of ['onDate', 'deadline']) if (/^\d{4}-\d{2}-\d{2}$/.test(String(it?.[k] || ''))) o[k] = it[k];
    return o;
}
function nnbDirectorImport(st, json) {
    const data = typeof json === 'string' ? JSON.parse(json) : json;
    if (!data || !Array.isArray(data.ideas)) throw new Error('В JSON нет списка ideas');
    const d = nnbDirector(st);
    if (Array.isArray(data.lines) && data.lines.length) d.lines = data.lines.map(l => ({ id: String(l.id), name: String(l.name || l.id), color: l.color || '#6366f1', target: Number(l.target) || 0 }));
    if (Array.isArray(data.history)) d.history = data.history.map(h => ({ ...h, intensity: Number(h.intensity) || 3 }));
    if (typeof data.contextSummary === 'string') d.summary = data.contextSummary;
    let added = 0;
    for (const it of data.ideas) {
        const title = String(it.title || '').trim();
        if (!title || st.notes.some(n => (n.title || '') === title)) continue;
        st.notes.push({ id: st.nextId++, tag: 'режиссёр', title, text: it.text ? `${title}. ${String(it.text).trim()}` : title, line: it.line || '', genre: it.genre || '', intensity: Number(it.intensity) || 3, chars: Array.isArray(it.characters) ? it.characters : [], needs: String(it.needs || ''), anchor: String(it.anchor || ''), bridge: String(it.bridge || ''), ...nnbSceneFieldsFrom(it), manual: true, at: ctx().chat?.length ?? 0 });
        added++;
    }
    return added;
}

// ===== 🎬 Режиссёр 2: генерация идей без клише, предпосылки и «мостики», приёмы сценаристов, слежка за логикой =====
// Клише, которые модели выдают первыми. Используются и в запросе (запрет), и при отборе (фильтр).
const NNB_DIR_CLICHES = [
    ['a sudden attack, ambush or robbery by strangers', /нападени|засад|ограблен|напали/i],
    ['a mysterious stranger appears with a warning or a secret', /загадочн\S* (?:незнаком|странник|гость)|таинственн\S* незнаком/i],
    ['amnesia or lost memory', /амнези|потер\S* памят/i],
    ['someone accidentally overhears a conversation and misunderstands', /подслуш|случайно услыш/i],
    ['a jealous ex suddenly shows up', /бывш\S* (?:появля|возвраща|объявля)|ревнив\S* бывш/i],
    ['a storm, blackout or broken car traps them together', /гроз[аеуы]|шторм|отключ\S* (?:свет|электрич)|застрял\S* вместе|сломал\S* машин/i],
    ['only one bed / forced to share a room', /одн[аой] кроват|делить (?:комнат|номер|постел)/i],
    ['a convenient injury or illness so one nurses the other', /ухаживает за (?:ним|ней|больн)|заболел\S* и|травм\S* и (?:он|она) ухаж/i],
    ['a kidnapping', /похищ|похитил/i],
    ['a letter, diary or photo found by chance reveals a secret', /(?:находит|нашл\S*|наход\S*) (?:старое |чужое |тайное )?(?:письм|дневник|фотограф)/i],
    ['a party where someone gets drunk and confesses', /напива\S* и признаёт|пьян\S* признан/i],
    ['fake dating / pretending to be a couple', /притвор\S* пар|фиктивн\S* (?:отнош|свидан|брак)/i],
];
// Приёмы сценаристов и писателей: режиссёр подбирает один под момент и подсказывает рассказчику одной строкой
const NNB_DIR_TECHNIQUES = {
    goal: { name: 'Цель и препятствие', hint: 'Give a character in the scene a concrete want right now and put a specific obstacle in the way; the scene turns on whether they get it.' },
    yesbut: { name: '«Да, но…» / «нет, и ещё…»', hint: "No clean wins: an attempt succeeds at a cost ('yes, but') or fails and makes things worse ('no, and')." },
    setup: { name: 'Ружьё Чехова — подвесить', hint: 'Casually plant one concrete detail (an object, a habit, a remark) that can matter later; do not draw attention to it.' },
    payoff: { name: 'Ружьё Чехова — выстрелить', hint: 'Pay off a detail planted earlier, so it suddenly matters: {x}.' },
    callback: { name: 'Отзыв', hint: 'Echo an earlier moment of the story in a new light (a phrase, an object, a place): {x}.' },
    irony: { name: 'Драматическая ирония', hint: 'Let the reader notice something a character does not know (through a detail or another character), and let the character walk right past it.' },
    clock: { name: 'Тикающие часы', hint: 'Add a time limit or a deadline that raises the stakes of what the characters want now.' },
    subtext: { name: 'Подтекст', hint: 'Feelings come through actions, objects and what is left unsaid, not stated outright.' },
    offscreen: { name: 'Мир живёт сам', hint: 'Show the result of something a side character did off-screen in pursuit of their own goal.' },
    reversal: { name: 'Перелом', hint: 'Turn the scene: a new fact or choice flips its direction (hope to worry or the reverse), plausibly following from what is already established.' },
    breather: { name: 'Передышка', hint: 'After the tension, give a quiet, warm or funny beat; let the characters breathe and react to what happened.' },
};
const NNB_DIR_TECH_BY_GENRE = {
    comedy: ['yesbut', 'subtext', 'setup', 'callback', 'offscreen', 'irony'],
    fluff: ['subtext', 'callback', 'setup', 'yesbut', 'offscreen'],
    slice: ['subtext', 'offscreen', 'setup', 'callback', 'yesbut', 'goal'],
    drama: ['goal', 'subtext', 'irony', 'reversal', 'yesbut', 'callback'],
    angst: ['subtext', 'irony', 'reversal', 'goal', 'callback'],
    plot: ['goal', 'clock', 'reversal', 'irony', 'yesbut', 'offscreen'],
    chaos: ['yesbut', 'clock', 'reversal', 'offscreen', 'goal'],
};

function nnbDirectorContinuityLine(st) {
    const c = (st?.director?.continuity || []).filter(Boolean);
    const out = c.length ? [`[Continuity — the next replies must not contradict: ${c.join('; ')}]`] : [];
    if (!st?.direction?.time) { // при модуле времени календарь уже идёт в блоке времени
        const planned = nnbPlansForPrompt(st, 14).map(x => x.replace(/^#P\d+\s*/, ''));
        if (planned.length) out.push(`[Planned in the story (characters know and remember these): ${planned.slice(0, 4).join('; ')}]`);
    }
    return out.join('\n');
}
function nnbDirectorExtra(st) {
    const d = nnbDirector(st);
    if (!Array.isArray(d.setups)) d.setups = [];
    if (!Array.isArray(d.continuity)) d.continuity = [];
    if (!Array.isArray(d.techHistory)) d.techHistory = [];
    return d;
}

// Линия, которой нужны новые идеи: самая отстающая, и в запасе под неё ничего нет
function nnbDirectorNeedIdeas(st) {
    const pool = (st.notes || []).filter(n => !n.ff && (Number(n.dripCount) || 0) < 3 && !n.bridgeFor);
    const bal = nnbDirectorBalance(st).sort((a, b) => b.deficit - a.deficit);
    if (!bal.length) return null;
    const prefLine = st.director?.prefs?.line && bal.find(b => b.id === st.director.prefs.line);
    const top = prefLine || bal[0];
    if (!pool.length) return top.id;
    const prefGenre = st.director?.prefs?.genre;
    if (prefGenre && !pool.some(n => n.line === top.id && n.genre === prefGenre)) return top.id; // под выбранный жанр запаса нет
    return pool.some(n => n.line === top.id) ? null : top.id;
}

// Условия задумки «Name: дружба ≥ N» / «романтика ≥ N» — проверяем сами по шкалам блокнота, без модели.
// Возвращает: 'ready' | 'bridge' (условия не выполнены) | 'check' (условия словами — пусть оценит размышление)
function nnbDirectorReadiness(st, note) {
    if (!note) return 'ready';
    if (note.bridgeFor != null || note.kind === 'after') return 'ready';
    if ((Number(note.bridges) || 0) >= 3) return 'ready'; // три мостика уже было — хватит подводить
    const needs = String(note.needs || '').trim();
    if (!needs || /^[—–-]$/.test(needs)) return note.ready === true || (Number(note.intensity) || 3) <= 2 ? 'ready' : 'check';
    const re = /([^:;,()\n]{2,40}?)\s*[:—–-]\s*(дружба|романтика|friendship|romance)\s*(?:≥|>=|>|=>)\s*(-?\d{1,3})/gi;
    let m, parsed = 0, unmet = 0;
    while ((m = re.exec(needs))) {
        const hero = findHeroOrNpc(st, m[1].trim());
        if (!hero) continue;
        parsed++;
        const key = /^(?:романтика|romance)$/i.test(m[2]) ? 'romance' : 'friendship';
        if ((Number(hero[key]) || 0) < Number(m[3])) unmet++;
    }
    if (unmet) return 'bridge'; // шкалы проверяем всегда — даже после сыгранных подводок
    const rest = needs.replace(re, '').replace(/[;,.\s—–-]+/g, '');
    return (parsed && !rest) || note.ready === true ? 'ready' : 'check';
}

// Мостик: небольшое событие, которое подводит к задумке (сблизит, познакомит, даст узнать нужное)
function nnbDirectorMakeBridge(st, note, text) {
    const t = String(text || '').trim();
    if (!note || !t) return null;
    const existing = (st.notes || []).find(n => n.bridgeFor === note.id);
    if (existing) return existing;
    note.bridges = (Number(note.bridges) || 0) + 1;
    const len = ctx().chat?.length ?? 0;
    const br = {
        id: st.nextId++, tag: 'режиссёр', title: `Подводка к «${String(note.title || note.text || '').slice(0, 50)}»`, text: t,
        line: note.line || '', genre: ['angst', 'drama'].includes(note.genre) ? 'slice' : (note.genre || 'slice'),
        intensity: Math.max(1, Math.min(3, (Number(note.intensity) || 3) - 1)), chars: note.chars || [],
        bridgeFor: note.id, ready: true, manual: true, at: len,
    };
    st.notes.push(br);
    return br;
}

function nnbDirectorPickTechnique(st, note) {
    const d = nnbDirectorExtra(st);
    const recent = d.techHistory.slice(-3);
    const len = ctx().chat?.length ?? 0;
    const lastInt = Number(st.notesDrip?.lastShown?.intensity) || 0;
    const it = Number(note?.intensity) || 3;
    const order = [];
    if (lastInt >= 4 && it <= 2) order.push('breather');
    const ripe = d.setups.filter(x => !x.used && len - (Number(x.at) || 0) >= 6);
    if (ripe.length) order.push('payoff');
    order.push(...(NNB_DIR_TECH_BY_GENRE[note?.genre] || ['goal', 'yesbut', 'subtext', 'reversal', 'setup', 'offscreen']));
    if (it >= 3 && !order.includes('clock')) order.push('clock');
    if (d.history.length >= 4 && !order.includes('callback')) order.push('callback');
    const cbScene = d.history[Math.floor(d.history.length / 2)];
    const fill = { payoff: ripe[0]?.text || '', callback: cbScene ? `«${cbScene.title}»` : '' };
    const usable = order.filter(x => !(x in fill) || fill[x]);
    const id = usable.find(x => !recent.includes(x)) || usable[0] || 'goal';
    const x = fill[id] || '';
    return { id, setupText: id === 'payoff' ? x : '', hint: NNB_DIR_TECHNIQUES[id].hint.replace('{x}', x) };
}

// Отдельный запрос «придумай идеи» — только когда под отстающую линию в запасе пусто.
// Приёмы против шаблонности: опора на материал истории, «первое очевидное — в корзину», «неожиданно, но неизбежно», чёрный список, отбор лучших.
async function nnbDirectorGenerateIdeas(st, lineId) {
    const d = nnbDirectorExtra(st);
    const line = d.lines.find(l => l.id === lineId) || d.lines[0];
    if (!line) return 0;
    const names = storyNames();
    const cut = (t, n) => String(t || '').trim().slice(0, n);
    const npcBrief = [st.mainCharCard, ...(st.npcs || [])].filter(Boolean).slice(0, 14)
        .map(n => `• ${n.name}: ${cut(n.card, 260).replace(/\s+/g, ' ')}${n.status ? ` | now: ${cut(n.status, 120)}` : ''} | дружба ${Number(n.friendship) || 0}${Number(n.romance) ? `, романтика ${Number(n.romance)}` : ''}${n.fear ? ` | fear: ${cut(n.fear, 80)}` : ''}${n.dream ? ` | dream: ${cut(n.dream, 80)}` : ''}`).join('\n');
    const secrets = (st.intrigues || []).slice(0, 6).map(it => `• ${cut(it.text, 160)}`).join('\n');
    const arcs = (st.arcs || []).slice(0, 6).map(a => `• ${a.who}: ${cut(a.text, 140)}`).join('\n');
    const chron = (st.time?.timeline || []).slice(-8).map(e => `• ${cut(e.text, 200)}`).join('\n');
    const played = d.history.slice(-15).map(h => `• ${h.title}${h.genre ? ` (${h.genre})` : ''}`).join('\n');
    const queued = (st.notes || []).filter(n => !n.ff).slice(0, 12).map(n => `• ${cut(n.title || n.text, 100)}`).join('\n');
    const setups = d.setups.filter(x => !x.used).map(x => `• ${x.text}`).join('\n');
    const recent = (ctx().chat || []).filter(m => !m.is_system).slice(-3).map(m => `${m.name}: ${cut(stripRoleplayHeaderBracketsAndWeirdSpaces(m.mes), 1200)}`).join('\n\n');
    const otherLines = d.lines.map(l => `${l.id} «${l.name}»`).join(', ');
    const prompt = `${SELF_CONTAINED_PROMPT_MARKER}[OOC: You are the director of an ongoing roleplay story between ${names.user} (the player) and ${names.char}. Invent the next scene ideas for the story line «${line.name}» (id ${line.id}; all lines: ${otherLines}).

${nnbDirectorPrefsText(st) ? `${nnbDirectorPrefsText(st)}\n\n` : ''}STORY MATERIAL — every idea must grow out of something here:
${cut(st.storySummary || d.summary, 1500) ? `Summary: ${cut(st.storySummary || d.summary, 1500)}\n` : ''}Characters:
${npcBrief || '(none)'}
${secrets ? `Unresolved secrets:\n${secrets}\n` : ''}${arcs ? `Character arcs:\n${arcs}\n` : ''}${setups ? `Details planted earlier, waiting to matter:\n${setups}\n` : ''}${chron ? `Recent chronicle:\n${chron}\n` : ''}${played ? `Scenes already played (do not repeat them):\n${played}\n` : ''}${queued ? `Ideas already queued (do not duplicate):\n${queued}\n` : ''}Latest messages:
${recent || '(none)'}

HOW TO WORK (screenwriters' rules):
1. First write 4 lines «OBVIOUS: …» — the first, most predictable moves this genre suggests. They are now BANNED; do not use them or their variations.
2. Also banned (overused clichés): ${NNB_DIR_CLICHES.map(c => c[0]).join('; ')}.
3. Then write 6 main scene ideas. Each must be anchored in a concrete element of the material above (a secret, a fear or dream, a planted detail, a side character's own goal, a tension in a relationship, an unfinished promise) — name it in ANCHOR. Aim for «unexpected, yet inevitable»: surprising, but following from what is established. Give the scene a want and an obstacle; prefer small, specific, personal events over big external catastrophes. Side characters may act on their own goals.
4. Respect where relationships stand now: if a scene needs closeness, trust or knowledge the characters don't have yet, add a small lead-up scene for it (bridge for m).
5. Finally write «BEST: n, n, n» — the three strongest main scenes by: anchored, fresh, fits the current moment, gives the player something to do.

FORMAT — field names in English, all content in Russian, one block per scene (LINE is always ${line.id}); add a line «ANCHOR: …» to every main scene:
${NNB_SCENE_FORMAT}
Reply only with the OBVIOUS lines, SCENE blocks and the BEST line.]`;
    const raw = String(await nnbDirectorGenerate(prompt, 8192) || '');
    const obvious = [...raw.matchAll(/^\s*OBVIOUS\s*[:：]\s*(.+)$/gim)].map(m => m[1].toLowerCase());
    const scenes = nnbDirectorParseScenes(raw).map(sc => ({ ...sc, line: sc.line || line.id }));
    const mains = scenes.filter(sc => sc.kind === 'main');
    const bestNums = (raw.match(/^\s*BEST\s*[:：]\s*(.+)$/im)?.[1] || '').match(/\d+/g)?.map(Number) || [];
    const words = t => new Set(String(t).toLowerCase().match(/[а-яёa-z]{5,}/g) || []);
    const tooClose = (a, b) => { const A = words(a), B = words(b); if (!A.size || !B.size) return false; let k = 0; A.forEach(w => { if (B.has(w)) k++; }); return k / Math.min(A.size, B.size) >= 0.5; };
    const existing = [...(st.notes || []), ...d.history].map(n => n.title || n.text || '');
    const body = sc => `${sc.title || ''} ${(sc.beats || []).join(' ')} ${sc.text || ''}`;
    const good = mains.filter(sc => body(sc).trim() && String(sc.anchor || '').replace(/[—–-]/g, '').trim()
        && !NNB_DIR_CLICHES.some(c => c[1].test(body(sc)))
        && !obvious.some(o => tooClose(o, body(sc)))
        && !existing.some(e => tooClose(e, `${sc.title || ''} ${(sc.beats || [])[0] || ''}`)));
    const ranked = good.sort((a, b) => (bestNums.includes(b.n) ? 1 : 0) - (bestNums.includes(a.n) ? 1 : 0));
    const keepN = new Set(ranked.slice(0, 3).map(sc => sc.n));
    const keep = scenes.filter(sc => keepN.has(sc.n) || (sc.kind !== 'main' && keepN.has(sc.forN)));
    const added = nnbDirectorAddScenes(st, keep, { line: line.id, auto: true });
    const ideas = mains;
    const take = added.filter(n => n.kind === 'main');
    d.lastGen = { at: Date.now(), line: line.id, got: ideas.length, kept: take.length, ids: added.map(n => n.id) };
    console.log('[npc_notebook] director ideas:', ideas.length, 'generated,', take.length, 'kept');
    return take.length;
}

// ===== 🎬 Подключение режиссёра: тяжёлая работа (придумать сцены, разложить задумки) идёт через своё подключение =====
function nnbDirectorSourceLabel(src = settings().directorSource) {
    if (!src || src === 'main') return 'основное подключение чата';
    if (src === 'notebook') return 'как у блокнота';
    if (src === 'custom-api') return 'свой API блокнота';
    const p = connectionProfiles().find(x => x.id === src);
    return p ? `профиль «${p.name}»` : 'профиль (удалён)';
}
async function nnbDirectorGenerate(prompt, maxTokens = 8192) {
    const src = String(settings().directorSource || 'main');
    if (src === 'notebook') return quietGenerate(prompt, maxTokens);
    if (src === 'main') {
        nnbForceMainChat = true;
        try { return await quietGenerate(prompt, maxTokens); } finally { nnbForceMainChat = false; }
    }
    try {
        const res = await generateViaStandaloneTextSource(prompt, maxTokens, src);
        if (String(res || '').trim()) return res;
    } catch (e) {
        if (nnbIsStopError(e)) throw e;
        console.warn('[npc_notebook] director source failed, falling back to the main chat:', e);
        toastr.warning(`Подключение режиссёра не ответило (${escapeHtml(e?.message || e)}) — использую основное подключение чата`, '🎬 Режиссёр');
    }
    nnbForceMainChat = true;
    try { return await quietGenerate(prompt, maxTokens); } finally { nnbForceMainChat = false; }
}
// Пожелания игрока режиссёру (на этот чат): шёпот, жанр, линия. Пусто — режиссёр решает сам.
function nnbDirectorPrefs(st) {
    const d = nnbDirector(st);
    if (!d.prefs || typeof d.prefs !== 'object') d.prefs = { whisper: '', genre: '', line: '' };
    return d.prefs;
}
// Для какой линии придумывать: выбранная игроком → где кончились идеи → самая отстающая (одно правило для всех кнопок)
function nnbDirectorTargetLine(st) {
    return nnbDirectorPrefs(st).line || nnbDirectorNeedIdeas(st) || nnbDirectorBalance(st).sort((a, b) => b.deficit - a.deficit)[0]?.id;
}
function nnbDirectorPrefsText(st) {
    const p = nnbDirectorPrefs(st);
    const ln = p.line ? nnbDirectorLineOf(st, p.line) : null;
    const out = [];
    if (String(p.whisper || '').trim()) out.push(`The player's wish (follow it): ${String(p.whisper).trim()}`);
    if (p.genre) out.push(`Preferred genre now: ${p.genre}`);
    if (ln) out.push(`Preferred story line now: ${ln.id} «${ln.name}»`);
    return out.join('\n');
}

// ===== 🎬 Сцены режиссёра: единый формат для «разложить сырые задумки», генерации идей и подачи рассказчику =====
// Формат ответа модели (один и тот же для разбора и генерации):
// SCENE n: main | bridge for m | after for m      (+ необязательно «; after k, l» — что должно быть сыграно раньше)
// TITLE / LINE / GENRE / MOOD / STAKES / DYNAMICS / WHEN / WHO / PACE / LINK / BEAT (несколько) / AVOID / NEEDS / ANCHOR
const NNB_SCENE_FORMAT = `SCENE n: main | bridge for m | after for m   (bridge = a lead-up scene that must be played before main scene m; after = a consequence scene played after scene m; you may add «; after k» if this scene must follow scene k)
TITLE: short title
LINE: story line id
GENRE: one of ${NNB_DIR_GENRES.join(', ')}
MOOD: genre and atmosphere in one phrase
STAKES: drama/stakes 1-5
DYNAMICS: pace/sharpness 1-5
WHEN: place and time
WHO: participants, comma-separated
PACE: how to pace it (e.g. don't close the scene in one post)
LINK: how it connects to what happened before (the bridge into it)
BEAT: one required beat or accent (3–5 BEAT lines, in order)
AVOID: what to avoid
NEEDS: «Name: дружба ≥ N» / «Name: романтика ≥ N», a short condition in words, or —
END`;

function nnbDirectorParseScenes(raw) {
    const out = [];
    let cur = null;
    for (const lineRaw of String(raw || '').split(/\r?\n/)) {
        const line = lineRaw.trim().replace(/^[-*•>\s]+/, '').replace(/\*\*/g, '');
        if (!line) continue;
        const h = line.match(/^SCENE\s*(\d+)\s*[:：.]?\s*(.*)$/i);
        if (h) {
            cur = { n: Number(h[1]), kind: 'main', forN: null, afterN: [], beats: [] };
            const meta = h[2].toLowerCase();
            const km = meta.match(/\b(bridge|after|consequence|main)\b(?:\s*for\s*#?(\d+))?/);
            if (km) { cur.kind = km[1] === 'consequence' ? 'after' : km[1]; if (km[2]) cur.forN = Number(km[2]); }
            const am = meta.match(/;\s*after\s*#?([\d,\s#]+)/);
            if (am) cur.afterN = (am[1].match(/\d+/g) || []).map(Number);
            out.push(cur);
            continue;
        }
        if (!cur) continue;
        if (/^END\b/i.test(line)) { cur = null; continue; }
        const f = line.match(/^([A-Z]+)\s*[:：]\s*(.*)$/);
        if (!f) { if (cur.beats.length) cur.beats[cur.beats.length - 1] += ` ${line}`; continue; }
        const key = f[1].toUpperCase();
        const val = f[2].trim();
        const map = { TITLE: 'title', LINE: 'line', GENRE: 'genre', MOOD: 'mood', WHEN: 'place', WHO: 'who', PACE: 'pace', LINK: 'link', AVOID: 'avoid', NEEDS: 'needs', ANCHOR: 'anchor', TEXT: 'text', SCENE: 'text' };
        if (key === 'BEAT') cur.beats.push(val);
        else if (key === 'STAKES') cur.stakes = Number(val.match(/\d/)?.[0]) || 0;
        else if (key === 'DYNAMICS') cur.dynamics = Number(val.match(/\d/)?.[0]) || 0;
        else if (map[key]) cur[map[key]] = val;
    }
    return out.filter(sc => sc.title || sc.beats.length || sc.text);
}

// Сцены → задумки блокнота со связями: подводка до главной, последствие после
function nnbDirectorAddScenes(st, scenes, extra = {}) {
    const d = nnbDirectorExtra(st);
    const len = ctx().chat?.length ?? 0;
    const byN = new Map();
    const dash = v => /^[—–-]?$/.test(String(v || '').trim()) ? '' : String(v).trim();
    for (const sc of scenes) {
        const ln = nnbDirectorLineOf(st, sc.line) || (extra.line ? d.lines.find(l => l.id === extra.line) : null);
        const genre = String(sc.genre || '').toLowerCase().match(/[a-z]+/)?.[0] || '';
        const note = {
            id: st.nextId++, tag: 'режиссёр', title: sc.title || String(sc.beats[0] || sc.text || '').slice(0, 70),
            text: sc.text || [sc.title, ...(sc.beats || [])].filter(Boolean).join('. ').slice(0, 600),
            line: ln ? ln.id : '', genre: NNB_DIR_GENRES.includes(genre) ? genre : '', mood: dash(sc.mood),
            intensity: Math.max(1, Math.min(5, Number(sc.stakes) || 3)), dynamics: Math.max(0, Math.min(5, Number(sc.dynamics) || 0)),
            place: dash(sc.place), chars: dash(sc.who) ? sc.who.split(/[,;]/).map(x => x.trim()).filter(Boolean) : [],
            pace: dash(sc.pace), link: dash(sc.link), beats: (sc.beats || []).map(b => b.trim()).filter(Boolean), avoid: dash(sc.avoid),
            needs: dash(sc.needs), anchor: dash(sc.anchor), kind: sc.kind || 'main', manual: true, at: len, ...(extra.auto ? { auto: true } : {}),
        };
        if (note.kind !== 'main') note.ready = true;
        st.notes.push(note);
        byN.set(sc.n, { sc, note });
    }
    for (const { sc, note } of byN.values()) {
        const after = new Set();
        (sc.afterN || []).forEach(k => { const t = byN.get(k)?.note; if (t && t !== note) after.add(t.id); });
        if (sc.kind === 'after' && sc.forN != null) { const t = byN.get(sc.forN)?.note; if (t) after.add(t.id); }
        if (sc.kind === 'bridge' && sc.forN != null) {
            const main = byN.get(sc.forN)?.note;
            if (main) { note.bridgeFor = main.id; main.after = [...new Set([...(main.after || []), note.id])]; main.ready = true; main.bridges = (Number(main.bridges) || 0) + 1; }
        }
        if (after.size) note.after = [...new Set([...(note.after || []), ...after])];
    }
    return [...byN.values()].map(x => x.note);
}

// Сцена разблокирована, если всё из after уже сыграно (или удалено)
// Рекомендации «что дальше»: сначала сцены, привязанные к календарю (событие сегодня, подготовка к ближайшему), потом лучшие из очереди
function nnbDirectorRecommendations(st, limit = 6) {
    const out = [];
    const used = new Set();
    for (let i = 0; i < limit * 2 && out.length < limit; i++) {
        const n = nnbDirectorPickExcluding(st, used);
        if (!n) break;
        used.add(n.id);
        // подводка → показываем ту сцену, к которой она ведёт (выбор игрока — сама сцена)
        const target = n.bridgeFor != null ? (st.notes.find(x => x.id === n.bridgeFor) || n) : n;
        if (out.some(r => r.note.id === target.id)) continue;
        const plan = target.planId ? nnbPlans(st).find(p => p.id === target.planId) : null;
        out.push({ note: target, label: plan ? `📅 ${target.planRole === 'event' ? 'событие' : 'до'} ${nnbPlanWhen(st, plan).replace(/,.*?\(/, ' (')}` : '' });
    }
    return out;
}
function nnbDirectorPickExcluding(st, excludeIds) {
    return nnbDirectorPick(st, null, excludeIds);
}
function nnbDirectorDateOk(st, n) {
    const today = st.time?.date;
    if (!today || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return true;
    if (n.onDate && today < n.onDate) return false;
    if (n.deadline && today > n.deadline) return false;
    return true;
}
function nnbDirectorAfterMet(st, n) {
    if (!Array.isArray(n?.after) || !n.after.length) return true;
    return n.after.every(id => !(st.notes || []).some(x => x.id === id && !x.ff));
}

// Подача сцены рассказчику — развёрнутая «режиссёрская сцена»
function nnbDirectorSceneBrief(st, note, tech) {
    const line = nnbDirectorLineOf(st, note.line);
    const L = [];
    L.push("[DIRECTOR'S SCENE — lead the story into it naturally over this and the next few replies; don't cut the current episode off abruptly; never mention the director]");
    if (note.place) L.push(`Place and time: ${note.place}`);
    if ((note.chars || []).length) L.push(`Participants: ${note.chars.join(', ')}`);
    if (line) L.push(`Story line: ${line.name}`);
    const mood = note.mood || note.genre;
    if (mood) L.push(`Genre and mood: ${mood}`);
    L.push(`Stakes/drama: ${Number(note.intensity) || 3}/5${note.dynamics ? ` | Dynamics/sharpness: ${note.dynamics}/5` : ''}`);
    L.push(`Pace: ${note.pace || "don't close the scene in one post — let it unfold over several replies, leaving room for the player's reactions"}`);
    if (note.link) L.push(`Bridge: ${note.link}`);
    if ((note.beats || []).length) {
        L.push('Scene beats and required accents:');
        note.beats.forEach((b, i) => L.push(`${i + 1}. ${b}`));
    } else L.push(`Scene: ${note.text}`);
    if (note.avoid) L.push(`Avoid: ${note.avoid}`);
    if (tech?.hint) L.push(`Technique: ${tech.hint}`);
    return L.join('\n');
}

// Сырые задумки (полотно текста или JSON) → режиссёр раскладывает по линиям и достраивает подводки и последствия
async function nnbDirectorIntake(st, rawText, onProgress = null) {
    const d = nnbDirectorExtra(st);
    const names = storyNames();
    let text = String(rawText || '').trim();
    if (!text) return [];
    try { const j = JSON.parse(text); text = nnbDirectorJsonToText(j) || text; } catch (e) { /* не JSON — это сырой текст */ }
    // большое полотно — частями по абзацам (~3500 знаков), чтобы ответ модели не обрезался
    const parts = [];
    let buf = '';
    for (const para of text.split(/\n\s*\n|\n(?=\s*(?:\d+[.)]|[-•*])\s)/)) {
        if (buf && (buf.length + para.length) > 3500) { parts.push(buf); buf = ''; }
        buf += (buf ? '\n\n' : '') + para.trim();
    }
    if (buf) parts.push(buf);
    const cut = (t, n) => String(t || '').trim().slice(0, n);
    const heroes = [st.mainCharCard, ...(st.npcs || [])].filter(Boolean).slice(0, 16)
        .map(n => `• ${n.name}: дружба ${Number(n.friendship) || 0}${Number(n.romance) ? `, романтика ${Number(n.romance)}` : ''}${n.status ? ` | now: ${cut(n.status, 100)}` : ''}`).join('\n');
    const lines = d.lines.map(l => `${l.id} «${l.name}»`).join(', ');
    const played = d.history.slice(-12).map(h => `• ${h.title}`).join('\n');
    const queued = (st.notes || []).filter(n => !n.ff).slice(0, 15).map(n => `• ${cut(n.title || n.text, 90)}`).join('\n');
    const all = [];
    for (let i = 0; i < parts.length; i++) {
        if (onProgress) onProgress(i + 1, parts.length);
        const prompt = `${SELF_CONTAINED_PROMPT_MARKER}[OOC: You are the director of an ongoing roleplay between ${names.user} (the player) and ${names.char}. The player has dumped raw scene ideas below (possibly several in one text, messy, unordered). Lay them out carefully:
1. Split them into separate scenes; keep everything the player wrote (names, details, jokes, «avoid» notes) — do not water it down.
2. Give each scene a story line (${lines}), genre, stakes and dynamics, place/time, participants, pace, 3–5 concrete beats and what to avoid.
3. Check where relationships stand now (below). If a scene needs closeness, trust, an acquaintance or knowledge the characters don't have yet, ADD lead-up scenes (bridge for m) that make it feel earned. If a scene clearly leaves consequences (a fallout, a reaction, a change in a relationship), ADD a consequence scene (after for m). Keep added scenes small and specific, anchored in the material; no stock twists (${NNB_DIR_CLICHES.slice(0, 6).map(c => c[0]).join('; ')}).
4. If one idea must happen before another, mark it with «; after k».

Current state:
${heroes || '(no characters yet)'}
${st.time?.date ? `Story date: ${st.time.date}\n` : ''}${played ? `Already played:\n${played}\n` : ''}${queued ? `Already queued:\n${queued}\n` : ''}
${nnbDirectorPrefsText(st) ? `${nnbDirectorPrefsText(st)}\n` : ''}RAW IDEAS (part ${i + 1}/${parts.length}):
${parts[i]}

FORMAT — field names in English, all content in Russian, one block per scene:
${NNB_SCENE_FORMAT}
Reply only with SCENE blocks.]`;
        const raw = String(await nnbDirectorGenerate(prompt, 8192) || '');
        const scenes = nnbDirectorParseScenes(raw);
        all.push(...nnbDirectorAddScenes(st, scenes));
    }
    return all;
}

// JSON задумок любого вида → текст для разбора (или null, если это не задумки)
function nnbDirectorJsonToText(j) {
    const arr = Array.isArray(j) ? j : (Array.isArray(j?.ideas) ? j.ideas : Array.isArray(j?.notes) ? j.notes : Array.isArray(j?.scenes) ? j.scenes : null);
    if (!arr) return null;
    return arr.map((it, i) => {
        if (typeof it === 'string') return `${i + 1}. ${it}`;
        const t = it.title || it.name || it.заголовок || '';
        const body = it.text || it.description || it.desc || it.scene || it.summary || it.текст || '';
        const extra = ['line', 'genre', 'intensity', 'characters', 'participants', 'needs', 'avoid', 'location', 'time']
            .filter(k => it[k] != null && String(it[k]).trim()).map(k => `${k}: ${Array.isArray(it[k]) ? it[k].join(', ') : it[k]}`).join('; ');
        return `${i + 1}. ${t}${t && body ? ' — ' : ''}${body}${extra ? ` (${extra})` : ''}`;
    }).join('\n\n');
}

// Импорт «как есть» без модели: формат ИИ-Режиссёра v4, массив идей или просто строки
function nnbDirectorImportAny(st, txt) {
    const s = String(txt || '').trim();
    let j = null;
    try { j = JSON.parse(s); } catch (e) { j = null; }
    if (j && !Array.isArray(j) && Array.isArray(j.ideas)) return nnbDirectorImport(st, j);
    const arr = Array.isArray(j) ? j : (Array.isArray(j?.notes) ? j.notes : Array.isArray(j?.scenes) ? j.scenes : null);
    if (arr) return nnbDirectorImport(st, { ideas: arr.map(it => typeof it === 'string' ? { title: it.slice(0, 80), text: it.length > 80 ? it : '' } : {
        title: it.title || it.name || it.заголовок || String(it.text || it.description || '').slice(0, 80),
        text: it.text || it.description || it.desc || it.scene || it.summary || it.текст || '',
        line: it.line || '', genre: it.genre || '', intensity: it.intensity || it.stakes || 3,
        characters: it.characters || it.participants || it.chars || [], needs: it.needs || '', anchor: it.anchor || '', bridge: it.bridge || '',
        ...nnbSceneFieldsFrom(it),
    }) });
    if (j) throw new Error('В JSON не нашлось списка задумок (ideas / notes / scenes или массив)');
    // не JSON: одна строка/абзац — одна задумка
    const items = s.split(/\n\s*\n|\n(?=\s*(?:\d+[.)]|[-•*])\s)/).map(x => x.replace(/^\s*(?:\d+[.)]|[-•*])\s*/, '').trim()).filter(Boolean);
    return nnbDirectorImport(st, { ideas: items.map(t => { const title = t.split(/[.!?\n]/)[0].slice(0, 80); return { title, text: t.slice(title.length).replace(/^[.!?\s]+/, '') }; }) });
}

// ===== 📅 Календарь событий сюжета: «в пятницу у Яна и Этель помолвка» → режиссёр знает, что должно успеть случиться =====
function nnbPlanCmdText(st) {
    const cur = nnbPlansForPrompt(st, 60);
    return `PLAN DD.MM: an event the characters scheduled or announced for a specific day (an engagement on Friday, an exam on the 12th, a trip next week) — the date counted from the current story date, the content in Russian; only new ones. PLAN_MOVE #P1 DD.MM — if it was moved; PLAN_CANCEL #P1 — if it was called off.${cur.length ? `\nAlready in the calendar:\n${cur.join('\n')}` : ''}`;
}
function nnbPlans(st) {
    if (!Array.isArray(st.plans)) st.plans = [];
    if (!Number.isFinite(st.nextPlanId)) st.nextPlanId = 1;
    return st.plans;
}
function nnbPlanDaysLeft(st, plan) {
    const today = st.time?.date;
    if (!plan?.date || !today || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return null;
    return daysBetween(today, plan.date);
}
function nnbPlanWhen(st, plan) {
    if (!plan.date) return plan.when || 'скоро';
    const left = nnbPlanDaysLeft(st, plan);
    const base = `${weekday(plan.date)}, ${formatDate(plan.date, false)}`;
    if (left == null) return base;
    return `${base} (${left === 0 ? 'сегодня' : left === 1 ? 'завтра' : left > 0 ? `через ${left} дн.` : `${-left} дн. назад`})`;
}
function nnbPlanWhenEn(st, plan) {
    if (!plan.date) return plan.when || 'soon';
    const left = nnbPlanDaysLeft(st, plan);
    return `${plan.date}${left == null ? '' : left === 0 ? ' (today)' : left === 1 ? ' (tomorrow)' : left > 0 ? ` (in ${left} days)` : ` (${-left} days ago)`}`;
}
function nnbAddPlan(st, whenText, text) {
    const plans = nnbPlans(st);
    const t = String(text || '').trim();
    if (!t) return null;
    const w = String(whenText || '').trim();
    const today = st.time?.date || '';
    let date = '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(w)) date = w;
    else if (w) { try { date = parseDateText(w, today) || ''; } catch (e) { date = ''; } }
    const words = x => new Set(String(x).toLowerCase().match(/[а-яёa-z]{4,}/g) || []);
    const A = words(t);
    const dup = plans.find(p => p.status === 'planned' && (!date || !p.date || p.date === date) && (() => { const B = words(p.text); let k = 0; A.forEach(x => { if (B.has(x)) k++; }); return A.size && B.size && k / Math.min(A.size, B.size) >= 0.5; })());
    if (dup) { if (date && !dup.date) dup.date = date; return dup; }
    const plan = { id: st.nextPlanId++, date, when: date ? '' : w, text: t, status: 'planned', at: ctx().chat?.length ?? 0, prepDone: false };
    plans.push(plan);
    return plan;
}
// Прошедшие события: подготовка к ним больше не нужна; само событие, не сыгранное за 2 дня, — пропущено
function nnbPlansTick(st) {
    const today = st.time?.date;
    if (!today || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return;
    for (const p of nnbPlans(st)) {
        if (p.status !== 'planned' || !p.date) continue;
        const left = daysBetween(today, p.date);
        if (left < 0) {
            for (const n of [...(st.notes || [])]) {
                if (n.planId !== p.id) continue;
                const eventMissed = left < -2 && !(st.archive || []).some(a => a.planId === p.id && a.planRole === 'event' && a.status === 'done');
                const stale = (n.planRole === 'prep' && left < 0) || (n.planRole === 'event' && left < -2) || (n.planRole === 'after' && eventMissed);
                if (stale) { st.notes = st.notes.filter(x => x !== n); n.status = 'missed'; n.closedAt = ctx().chat?.length ?? 0; (st.archive || (st.archive = [])).push(n); }
            }
            if (left < -2) p.status = 'past';
        }
    }
}
function nnbPlansForPrompt(st, days = 45) {
    return nnbPlans(st).filter(p => p.status === 'planned' && (nnbPlanDaysLeft(st, p) == null || (nnbPlanDaysLeft(st, p) >= -1 && nnbPlanDaysLeft(st, p) <= days)))
        .map(p => `#P${p.id} ${nnbPlanWhenEn(st, p)}: ${p.text}`);
}

// Режиссёр расписывает событие из календаря: сама сцена события (в её день) + что логично успеть отыграть до неё
async function nnbDirectorPlanPrep(st, plan) {
    const d = nnbDirectorExtra(st);
    const names = storyNames();
    const cut = (t, n) => String(t || '').trim().slice(0, n);
    const left = nnbPlanDaysLeft(st, plan);
    const heroes = [st.mainCharCard, ...(st.npcs || [])].filter(Boolean).slice(0, 16)
        .map(n => `• ${n.name}: ${cut(n.card, 160).replace(/\s+/g, ' ')} | дружба ${Number(n.friendship) || 0}${Number(n.romance) ? `, романтика ${Number(n.romance)}` : ''}`).join('\n');
    const queued = (st.notes || []).filter(n => !n.ff).slice(0, 15).map(n => `• ${cut(n.title || n.text, 90)}`).join('\n');
    const lines = d.lines.map(l => `${l.id} «${l.name}»`).join(', ');
    const prompt = `${SELF_CONTAINED_PROMPT_MARKER}[OOC: You are the director of an ongoing roleplay between ${names.user} (the player) and ${names.char}. A dated event is coming up in the story:
EVENT: ${plan.text}
WHEN: ${nnbPlanWhenEn(st, plan)}${st.time?.date ? `; today in the story: ${st.time.date}` : ''}

Plan what should be played around it:
SCENE 1 is the event itself (main), set on its day (WHEN must name that day).
Then 3–5 scenes that logically should happen BEFORE it (preparations, errands, choices, reactions, small conflicts or tender moments it causes — e.g. choosing a gift, picking an outfit, a talk about it). They must fit into the time left${left != null ? ` (${left} days)` : ''}; mark each «bridge for 1». Make them specific to these characters, not generic.
Optionally one consequence scene after the event («after for 1»).
${nnbDirectorPrefsText(st) ? `${nnbDirectorPrefsText(st)}\n` : ''}Story lines: ${lines}.
Characters now:
${heroes || '(none)'}
${queued ? `Already queued (do not duplicate):\n${queued}\n` : ''}
FORMAT — field names in English, all content in Russian:
${NNB_SCENE_FORMAT}
Reply only with SCENE blocks.]`;
    const raw = String(await nnbDirectorGenerate(prompt, 8192) || '');
    const scenes = nnbDirectorParseScenes(raw);
    if (!scenes.length) return [];
    // главная сцена события (SCENE 1 или первая main) не должна ждать все подготовки — подготовки лишь «до даты»
    const eventN = (scenes.find(sc => sc.n === 1 && sc.kind === 'main') || scenes.find(sc => sc.kind === 'main'))?.n;
    const seen = new Set();
    const mapped = scenes.filter(sc => !seen.has(sc.n) && seen.add(sc.n))
        .map(sc => sc.kind === 'bridge' && sc.forN === eventN ? { ...sc, kind: 'main', forN: null, _prep: true } : sc);
    const added = nnbDirectorAddScenes(st, mapped);
    mapped.forEach((sc, i) => {
        const n = added[i];
        if (!n) return;
        n.planId = plan.id;
        if (sc.n === eventN) { n.planRole = 'event'; n.onDate = plan.date || ''; n.ready = true; }
        else if (sc._prep || (sc.kind === 'main' && sc.n !== eventN)) { n.planRole = 'prep'; n.deadline = plan.date || ''; n.ready = true; }
        else if (sc.kind === 'after') n.planRole = 'after';
    });
    plan.prepDone = true;
    return added;
}

// пришёл ответ рассказчика: задумка была показана ещё раз; после NNB_DRIP_SPAN ответов — следующая
function nnbDripAfterReply(st) {
    if (st?.direction?.notes !== 'drip' && st?.direction?.notes !== 'director') return;
    const d = nnbDripState(st);
    if (d.activeId == null) return;
    if (st.direction.notes === 'director' && d.needCheck === d.activeId && (Number(d.waitReplies) || 0) < 6) { d.waitReplies = (Number(d.waitReplies) || 0) + 1; return; } // задумка ещё не показана — ждёт проверки
    d.shown += 1;
    if (d.shown < NNB_DRIP_SPAN) return;
    const note = (st.notes || []).find(n => n.id === d.activeId);
    if (note) { note.dripCount = (Number(note.dripCount) || 0) + 1; note.dripAt = ctx().chat?.length ?? 0; }
    if (note) d.lastShown = { line: note.line || '', intensity: Number(note.intensity) || 0 };
    const next = st.direction.notes === 'director' ? nnbDirectorPick(st, d.activeId) : nnbDripPickNote(st, d.activeId);
    d.activeId = next ? next.id : null;
    d.shown = 0;
    d.tech = null; d.needCheck = null; d.waitReplies = 0;
    d.sinceThink = true; // размышление проверит, сбылась ли задумка (DONE)
}

function updateInjection() {
    try { const stW = store(); if (stW && settings().enabled) nnbAutoRetireStaleOutfit(stW); } catch (e) { /* ignore */ }
    const c = ctx();
    const s = settings();
    const st = store();
    const showNotes = st?.direction?.notes === true && st.notes.length;
    let dripLine = '';
    try { dripLine = st ? nnbDripInjection(st) : ''; } catch (e) { dripLine = ''; }
    const showIntrigues = st?.direction?.intrigues && st.intrigues.length;
    const showNpcs = st?.direction?.npcs && (st.npcs.length || st.mainCharCard);
    const showRels = st?.direction?.npcs && st.direction.rels !== false && (st.relationships || []).length;
    const showArcs = st?.direction?.arcs && (st.arcs.length || st.evolved.length);
    const linesBlock = st?.direction?.lines?.trim() ? `[Story lines the player wants to see: ${st.direction.lines.trim()}. From time to time let them surface: these characters appear, their relationships develop, people talk about them. Naturally, not in every scene.]` : '';
    // Память ведёт Memory Books (или другое расширение) — летопись и хронику блокнота в ролевую не шлём, чтобы не дублировать
    const summaryBlock = !s.externalMemory && st?.storySummary?.trim()
        ? `[📜 Summary of the previous chapters (roleplay canon — treat these events, relationships and context as having already happened):
${st.storySummary.trim()}]`
        : '';
    const autoActionsEveryTurn = !!(s.actionPrompts && st && !s.actionPromptsOnClickOnly);
    const actionBlock = autoActionsEveryTurn ? buildActionPromptsInjection() : '';
    const hasTime = !!(st && st.direction.time && (st.time?.date || placeLine(st)));
    const hasWardOrGacha = !!(st && (st.direction.wardrobe || st.gacha?.pending || (st.gacha?.choices || []).some(x => x.pinned)));
    const hasWorldOrLiving = !!(st && (st.worldProfile || st.direction.livingWorld || (st.neighborStories || []).length || (st.dreams || []).length));
    if (!s.enabled || !st || (!showNotes && !showIntrigues && !showNpcs && !showRels && !showArcs && !hasTime && !hasWorldOrLiving && !linesBlock && !hasWardOrGacha && !actionBlock && !summaryBlock && !dripLine)) {
        c.setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
        c.setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
        c.setExtensionPrompt(ACTION_INJECT_KEY, '', POS_IN_CHAT, 0);
        return;
    }

    if (s.tokenSaverMode !== false) {
        // 💎 РЕЖИМ ЭКОНОМИИ ТОКЕНОВ БЕЗ ПОТЕРИ ВНИМАНИЯ МОДЕЛИ:
        // 1) Стабильная база (Саммари прошлых глав, связи между персонажами и «спящие» НПС за кадром) ставится в начало чата (depth = 999),
        //    где она попадает в prompt cache и не смешивается с активными героями в текущей комнате!
        // 2) Активный фокус сцены (Время, Локация, Наряд, Герои в сцене, Арки, Задумки, Интриги) остаётся на рабочей глубине s.depth у конца чата.
        const staticBlocks = [];
        if (summaryBlock) staticBlocks.push(summaryBlock);
        const worldProfStatic = buildWorldProfileInjection(st);
        if (worldProfStatic) staticBlocks.push(worldProfStatic);
        const timeStatic = st.direction.time ? buildTimeInjection(st, 'static') : '';
        if (timeStatic) staticBlocks.push(timeStatic);
        if (linesBlock) staticBlocks.push(linesBlock);
        const staticWard = [wardrobeInjection(st, 'static'), gachaInjection(st, 'static')].filter(Boolean).join('\n\n');
        if (staticWard) staticBlocks.push(staticWard);
        if (showNpcs) {
            const sleepingBlock = formatNpcs(st.npcs, false, st, 'sleeping');
            if (sleepingBlock) staticBlocks.push(sleepingBlock);
        }
        if (showRels) staticBlocks.push(REL_INJECT_HEADER + '\n' + formatRelationships(st));
        if (showArcs) staticBlocks.push(ARC_INJECT_HEADER + '\n' + formatArcs(st, false, true));
        if (showIntrigues) staticBlocks.push(INTRIGUE_INJECT_HEADER + '\n' + formatIntrigues(st.intrigues));

        c.setExtensionPrompt(
            INJECT_STATIC_KEY,
            staticBlocks.join('\n\n'),
            POS_IN_CHAT,
            999,
            false,
            Number(s.role) || 0,
        );

        const dynamicLiving = [buildLivingWorldInjection(st, false), buildEphemeralWorldEventsInjection(st)].filter(Boolean).join('\n\n');
        const dynamicWard = [wardrobeInjection(st, 'dynamic'), gachaInjection(st, 'dynamic')].filter(Boolean).join('\n\n');
        const dynamicTime = st.direction.time ? [buildTimeInjection(st, 'dynamic'), s.events ? buildHolidayInjection(st) : ''].filter(Boolean).join('\n\n') : '';
        const dynamicBlocks = [];
        if (dynamicTime) dynamicBlocks.push(dynamicTime);
        if (dynamicLiving) dynamicBlocks.push(dynamicLiving);
        if (dynamicWard) dynamicBlocks.push(dynamicWard);
        if (showNpcs) {
            const activeNpcsStr = formatNpcs(st.npcs, false, st, 'active');
            if (activeNpcsStr) dynamicBlocks.push(NPC_INJECT_HEADER + '\n' + activeNpcsStr);
        }
        if (showNotes) dynamicBlocks.push(fillTemplate(s.injectPrompt, st.notes));
        if (dripLine) dynamicBlocks.push(dripLine);

        c.setExtensionPrompt(
            INJECT_KEY,
            dynamicBlocks.join('\n\n'),
            POS_IN_CHAT,
            Number(s.depth) || 0,
            false,
            Number(s.role) || 0,
        );
    } else {
        c.setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
        const timeBlock = st && st.direction.time ? [buildTimeInjection(st), s.events ? buildHolidayInjection(st) : ''].filter(Boolean).join('\n\n') : '';
        const livingBlock = st ? buildLivingWorldInjection(st) : '';
        const wardBlock = st ? [wardrobeInjection(st), gachaInjection(st)].filter(Boolean).join('\n\n') : '';
        const blocks = [];
        if (summaryBlock) blocks.push(summaryBlock);
        if (timeBlock) blocks.push(timeBlock);
        const ephemNonSaver = buildEphemeralWorldEventsInjection(st);
        if (livingBlock) blocks.push(livingBlock);
        if (ephemNonSaver) blocks.push(ephemNonSaver);
        if (wardBlock) blocks.push(wardBlock);
        if (linesBlock) blocks.push(linesBlock);
        if (showNpcs) blocks.push(NPC_INJECT_HEADER + '\n' + formatNpcs(st.npcs, false, st));
        if (showRels) blocks.push(REL_INJECT_HEADER + '\n' + formatRelationships(st));
        if (showArcs) blocks.push(ARC_INJECT_HEADER + '\n' + formatArcs(st));
        if (showNotes) blocks.push(fillTemplate(s.injectPrompt, st.notes));
        if (dripLine) blocks.push(dripLine);
        if (showIntrigues) blocks.push(INTRIGUE_INJECT_HEADER + '\n' + formatIntrigues(st.intrigues));
        c.setExtensionPrompt(
            INJECT_KEY,
            blocks.join('\n\n'),
            POS_IN_CHAT,
            Number(s.depth) || 0,
            false,
            Number(s.role) || 0,
        );
    }

    if (!s.enabled || !autoActionsEveryTurn) {
        c.setExtensionPrompt(ACTION_INJECT_KEY, '', POS_IN_CHAT, 0);
    } else {
        c.setExtensionPrompt(
            ACTION_INJECT_KEY,
            buildActionPromptsInjection(),
            POS_IN_CHAT,
            0,
            false,
            Number(s.role) || 0,
        );
    }
}

// Совместимость со старой и новой сигнатурой generateQuietPrompt
let ownRequest = false;
let ownPrompt = '';
let ffPending = false;
let ffActiveText = '';
let ffAnsweredOnce = false;
let ffTargetMesId = null;

function setSceneAdvancePrompt(text) {
    ffActiveText = String(text || '');
    ffPending = !!ffActiveText;
    ffAnsweredOnce = false;
    ffTargetMesId = null;
    ctx().setExtensionPrompt(INJECT_FF_KEY, ffActiveText, POS_IN_CHAT, 0, false, 0);
}

function stripActionTags(text) {
    return String(text ?? '')
        .replace(/<(think|thinking|reasoning)>[\s\S]*?<\/(think|thinking|reasoning)>/gi, '')
        .replace(/<!--\s*ACTIONS\s*[:：][\s\S]*?-->/gi, '')
        .replace(/<!--\s*(?:SPARK|STATE)\s*[:：][\s\S]*?-->/gi, '')
        .replace(/\[\s*(?:ACTIONS|Варианты действий|Варианты хода)\s*[:：][\s\S]*?\]/gi, '')
        .replace(/(?:^|\n)\s*(?:<!--\s*)?(?:ACTIONS|Варианты действий|Варианты хода)\s*[:：][\s\S]*$/gi, '')
        .trim();
}

function extractTextFromApiResult(raw) {
    if (!raw) return '';
    if (typeof raw === 'string') return raw;
    if (typeof raw?.content === 'string') return raw.content;
    if (Array.isArray(raw?.content)) {
        return raw.content.map(p => (typeof p === 'string' ? p : (p?.text || p?.content || ''))).join('');
    }
    if (typeof raw?.text === 'string') return raw.text;
    if (typeof raw?.response === 'string') return raw.response;
    if (typeof raw?.result === 'string') return raw.result;
    if (typeof raw?.message?.content === 'string') return raw.message.content;
    if (Array.isArray(raw?.choices) && raw.choices[0]) {
        const msg = raw.choices[0].message || raw.choices[0].delta || raw.choices[0];
        if (typeof msg?.content === 'string' && msg.content.trim()) return msg.content;
        if (Array.isArray(msg?.content)) return msg.content.map(p => (typeof p === 'string' ? p : (p?.text || ''))).join('');
        if (typeof raw.choices[0]?.text === 'string' && raw.choices[0].text.trim()) return raw.choices[0].text;
        // reasoning_content (мысли модели) НЕ используем как ответ — иначе рассуждения попадают в промпт картинки
    }
    if (Array.isArray(raw?.results) && raw.results[0]) {
        if (typeof raw.results[0]?.text === 'string') return raw.results[0].text;
        if (typeof raw.results[0]?.content === 'string') return raw.results[0].content;
    }
    if (Array.isArray(raw?.candidates) && raw.candidates[0]?.content?.parts) {
        return raw.candidates[0].content.parts.map(p => p?.text || '').join('');
    }
    if (raw?.data && typeof raw.data === 'object') {
        const inner = extractTextFromApiResult(raw.data);
        if (inner) return inner;
    }
    return '';
}

async function sendViaTavernProfile(profileId, fullPrompt, maxTokens = 2048, label = 'профиль Таверны', systemNote = '', skipPreset = false) {
    const svc = ctx().ConnectionManagerRequestService;
    if (!svc?.sendRequest) {
        throw new Error('В этой версии Таверны нет менеджера профилей подключения');
    }
    const prof = connectionProfiles().find(p => p.id === profileId || p.name === profileId);
    const pid = prof ? prof.id : profileId;
    const isTc = prof?.mode === 'tc';
    const chatMsgs = [];
    if (systemNote && String(systemNote).trim()) {
        chatMsgs.push({ role: 'system', content: String(systemNote).trim() });
    }
    chatMsgs.push({ role: 'user', content: fullPrompt });
    const singleUserMsgs = [{ role: 'user', content: fullPrompt }];

    // Если skipPreset = true (для генератора промптов картинок GLM), ставим includePreset: false ПЕРВЫМ, чтобы GLM НЕ видел общий пресет ролевой (гротескную комедию и т.д.)!
    const firstPresetFlag = !skipPreset;
    const secondPresetFlag = !!skipPreset;

    const attempts = isTc
        ? [
            // текстовый режим: без includeInstruct Таверна шлёт голый текст без шаблона модели — ответы уходят в продолжение промпта
            (signal) => svc.sendRequest(pid, fullPrompt, maxTokens, { stream: false, extractData: true, includePreset: firstPresetFlag, includeInstruct: true, signal }),
            (signal) => svc.sendRequest(pid, fullPrompt, maxTokens, { stream: false, extractData: true, includePreset: secondPresetFlag, includeInstruct: true, signal }),
            (signal) => svc.sendRequest(pid, fullPrompt, maxTokens, { stream: false, extractData: true, includePreset: false, includeInstruct: false, signal }),
        ]
        : [
            (signal) => svc.sendRequest(pid, chatMsgs, maxTokens, { stream: false, extractData: true, includePreset: firstPresetFlag, signal }),
            (signal) => svc.sendRequest(pid, singleUserMsgs, maxTokens, { stream: false, extractData: true, includePreset: secondPresetFlag, signal }),
            (signal) => svc.sendRequest(pid, singleUserMsgs, maxTokens, { stream: false, extractData: true, signal }),
        ];

    const attemptTimeoutMs = maxTokens >= 4096 || String(fullPrompt || '').length > 20000 ? 110000 : 75000;
    let lastErr = null;
    for (let ai = 0; ai < attempts.length; ai++) {
        // каждая попытка со своим сигналом: по таймауту прошлый запрос ОТМЕНЯЕТСЯ, а не висит параллельно
        // (раньше брошенные попытки продолжали идти к провайдеру и съедали лимит — отсюда 429 и «ошибки» на отдельном профиле)
        const ab = nnbNewAbort();
        try {
            const raw = await withTimeout(attempts[ai](ab.signal), attemptTimeoutMs, label);
            const txt = extractTextFromApiResult(raw);
            if (txt && String(txt).trim()) {
                return String(txt).trim();
            }
            if (typeof logImageDiag === 'function' && /промпт/i.test(label)) {
                logImageDiag(`⚠️ ${label}: попытка ${ai + 1}/${attempts.length} вернула пустой ответ — пробую следующий вариант`);
            }
        } catch (err) {
            lastErr = err;
            try { ab.ctrl.abort(); } catch (e) { /* ignore */ }
            if (nnbIsStopError(err)) throw nnbStopError();
            console.warn(`[npc_notebook] sendViaTavernProfile attempt failed (${label}):`, err?.message || err);
            // ключ/доступ/модель неверны — другие варианты запроса не помогут, сразу понятная ошибка
            if (/\b(401|403)\b|unauthori[sz]ed|invalid api key|incorrect api key|model.{0,40}not.{0,10}(found|exist)/i.test(String(err?.message || err))) {
                throw new Error(`Профиль «${prof?.name || pid}»: ${String(err?.message || err).slice(0, 200)} — проверь ключ и модель в этом профиле подключения`);
            }
            if (typeof logImageDiag === 'function' && /промпт/i.test(label)) {
                logImageDiag(`⚠️ ${label}: попытка ${ai + 1}/${attempts.length} не удалась`, err?.message || String(err));
            }
        } finally {
            ab.done();
        }
    }
    throw lastErr || new Error(`Профиль «${prof?.name || pid}» вернул пустой ответ`);
}

const SELF_CONTAINED_PROMPT_MARKER = '<!--SELF_CONTAINED_CONTEXT-->';
function buildStandaloneContextPrompt(taskPrompt) {
    const c = ctx();
    const rawStr = String(taskPrompt || '');
    if (rawStr.includes(SELF_CONTAINED_PROMPT_MARKER)) {
        return c.substituteParams(rawStr.replace(SELF_CONTAINED_PROMPT_MARKER, '').trim());
    }
    const s = settings();
    const names = storyNames();
    const parts = [];

    // 1. Краткая справка о персонажах чата и Саммари предыдущих глав (чтобы отдельная быстрая модель Блокнота помнила весь канон!)
    const st = store();
    if (st?.storySummary?.trim()) {
        parts.push(`[📜 Summary of the previous chapters:\n${String(st.storySummary).trim().slice(0, 3500)}]`);
    }
    const ch = (c.characterId !== undefined && c.characters?.[c.characterId]) ? c.characters[c.characterId] : null;
    if (ch) {
        const desc = [ch.description, ch.personality, ch.scenario].filter(Boolean).join('\n').slice(0, 2600);
        if (desc) parts.push(`[Character description of ${names.char}:\n${c.substituteParams(desc)}]`);
    }
    const personaDesc = c.powerUserSettings?.persona_description || c.extensionSettings?.persona?.description || '';
    if (personaDesc) {
        parts.push(`[Player description of ${names.user}:\n${c.substituteParams(String(personaDesc).slice(0, 1600))}]`);
    }

    // 2. Последние сообщения чата (для последних 6 постов сохраняем до 3600 символов и обязательно концовку поста, чтобы модель Блокнота видела финал сцены!)
    const maxMsgs = Math.max(5, Math.min(80, Number(s.textContextMsgs) || 25));
    const chat = Array.isArray(c.chat) ? c.chat : [];
    const recent = chat.filter(m => m && !m.is_system && m.mes).slice(-maxMsgs);
    if (recent.length) {
        const lines = recent.map((m, idx) => {
            const speaker = m.is_user ? names.user : (m.name || names.char);
            const rawClean = stripTags(stripActionTags(String(m.mes || ''))).replace(/<[^>]+>/g, '').trim();
            const isVeryRecent = idx >= recent.length - 6;
            const limit = isVeryRecent ? 3600 : 1800;
            const clean = rawClean.length <= limit
                ? rawClean
                : `${rawClean.slice(0, Math.floor(limit * 0.45))} … ${rawClean.slice(-Math.floor(limit * 0.55))}`;
            return `${speaker}: ${clean}`;
        });
        parts.push(`[Latest roleplay messages (chat context):\n${lines.join('\n\n')}]`);
    }

    // 3. Само задание блокнота
    parts.push(c.substituteParams(String(taskPrompt || '')));
    return parts.join('\n\n');
}

async function generateViaStandaloneTextSource(taskPrompt, maxTokens = 4096, srcOverride = null) {
    const s = settings();
    const src = String(srcOverride ?? s.textSource ?? '').trim();
    if (!src) return null;

    const isSelfContained = String(taskPrompt || '').includes(SELF_CONTAINED_PROMPT_MARKER);
    const fullPrompt = buildStandaloneContextPrompt(taskPrompt);

    if (src === 'custom-api') {
        let base = String(s.textApiBase || 'https://generativelanguage.googleapis.com/v1beta/openai').trim().replace(/\/+$/, '');
        const key = String(s.textApiKey || '').trim();
        const model = String(s.textApiModel || 'gemini-2.5-flash').trim();
        if (!base || !key || !model) {
            throw new Error('Для своего подключения блокнота заполни адрес API, ключ и название модели (например gemini-2.5-flash)');
        }
        if (base.includes('generativelanguage.googleapis.com') && !base.includes('/openai')) {
            base = 'https://generativelanguage.googleapis.com/v1beta/openai';
        }
        const endpoint = base.endsWith('/chat/completions') ? base : `${base}/chat/completions`;
        const abT = nnbNewAbort();
        const res = await withTimeout(imagesFetch(endpoint, {
            signal: abT.signal,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${key}`,
            },
            body: JSON.stringify({
                model,
                messages: [{ role: 'user', content: fullPrompt }],
                max_tokens: maxTokens,
                temperature: 0.7,
            }),
        }), (maxTokens > 4096 ? 240000 : (isSelfContained || fullPrompt.length > 20000 ? 110000 : 75000)), `быстрое подключение блокнота (${model})`)
            .catch(e => { try { abT.ctrl.abort(); } catch (x) { /* ignore */ } throw e; })
            .finally(() => abT.done());
        const text = await res.text();
        let json = null;
        try { json = JSON.parse(text); } catch (e) { /* ignore */ }
        if (!res.ok) {
            throw new Error(`API блокнота (${res.status}): ${String(json?.error?.message || text).slice(0, 200)}`);
        }
        return extractTextFromApiResult(json) || text;
    }

    // Профиль подключения Таверны (ConnectionManagerRequestService)
    // Для самодостаточных задач (саммари переезда, дневники и т.д.) отключаем пресет чата, чтобы не раздувать промпт и не ловить таймауты
    return await sendViaTavernProfile(src, fullPrompt, maxTokens, 'профиль подключения блокнота', '', isSelfContained);
}

let ownPromptIsSelfContained = false;
let nnbForceMainChat = false; // режиссёр на «основном подключении»: мимо отдельной быстрой модели блокнота
async function quietGenerateOnce(prompt, maxTokens = 0) {
    const c = ctx();
    const s = settings();
    const fn = c.generateQuietPrompt;
    const rawPromptStr = String(prompt || '');
    ownPromptIsSelfContained = rawPromptStr.includes(SELF_CONTAINED_PROMPT_MARKER);
    const cleanPromptForChat = c.substituteParams(rawPromptStr.replace(SELF_CONTAINED_PROMPT_MARKER, '').trim());
    ownRequest = true;
    ownPrompt = cleanPromptForChat;
    // Временно отключаем инъекцию вариантов хода и перемотки/тренда, чтобы они не попадали в фоновые запросы блокнота
    c.setExtensionPrompt(ACTION_INJECT_KEY, '', POS_IN_CHAT, 0);
    if (ffPending) c.setExtensionPrompt(INJECT_FF_KEY, '', POS_IN_CHAT, 0);
    try {
        if (s.textSource && !nnbForceMainChat) {
            try {
                const standaloneRes = await generateViaStandaloneTextSource(prompt, maxTokens || 4096);
                if (standaloneRes && String(standaloneRes).trim()) {
                    return standaloneRes;
                }
            } catch (standaloneErr) {
                if (nnbIsStopError(standaloneErr)) throw nnbStopError();
                console.warn('[npc_notebook] standalone text source failed, falling back to main chat:', standaloneErr);
                toastr.warning(`Отдельное подключение блокнота не ответило (${escapeHtml(standaloneErr?.message || standaloneErr)}) — использую основное подключение чата.`, '⚡ Подключение блокнота', { escapeHtml: false, timeOut: 7000 });
            }
        }
        const mainChatTimeoutMs = maxTokens > 4096 ? 300000 : (cleanPromptForChat.length > 20000 ? 150000 : 120000);
        if (fn.length === 0) {
            // responseLength — собственный лимит длины для этого запроса (иначе берётся «Длина ответа» из пресета, обычно 300–1000 токенов)
            return await withTimeout(fn(maxTokens ? { quietPrompt: cleanPromptForChat, responseLength: maxTokens } : { quietPrompt: cleanPromptForChat }), mainChatTimeoutMs, 'основное подключение чата');
        }
        return await withTimeout(fn(cleanPromptForChat, false, false), mainChatTimeoutMs, 'основное подключение чата');
    } finally {
        ownRequest = false;
        ownPrompt = '';
        ownPromptIsSelfContained = false;
        const st = store();
        if (s.enabled && s.actionPrompts && !s.actionPromptsOnClickOnly && st && !busy) {
            c.setExtensionPrompt(ACTION_INJECT_KEY, buildActionPromptsInjection(), POS_IN_CHAT, 0, false, Number(s.role) || 0);
        }
        if (ffPending && ffActiveText) {
            c.setExtensionPrompt(INJECT_FF_KEY, ffActiveText, POS_IN_CHAT, 0, false, 0);
        }
    }
}

// Таверна добавляет скрытый промпт в конец как системное сообщение. Gemini через
// OpenAI-совместимый прокси без постобработки промпта на этом падает (Bad Request),
// поэтому в наших запросах делаем его сообщением пользователя.
const OWN_MARKER = '[OOC: Пауза в ролевой игре';
function msgContentText(content) {
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) return content.map(part => (typeof part === 'string' ? part : part?.text || '')).join('');
    return '';
}
function stripBloatHtmlForPrompt(text) {
    if (typeof text !== 'string' || text.length < 40) return text;
    if (!/[<]|<!--/.test(text)) return text;
    return text
        .replace(/<!--[\s\S]*?-->/g, '')
        .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
        .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, '')
        .replace(/<([a-z][a-z0-9]*)\b[^>]*>/gi, (m, tag) => {
            const t = tag.toLowerCase();
            if (t === 'br' || t === 'hr') return '\n';
            if (t === 'img') return '';
            if (t === 'td' || t === 'th') return ' ';
            if (/^(?:div|p|section|article|header|footer|tr|li|blockquote|h[1-6])$/.test(t)) return '\n';
            if (/^(?:span|font|b|strong|i|em|u|small|table|tbody|thead|ul|ol|details|summary)$/.test(t)) return '';
            return m;
        })
        .replace(/<\/(?:td|th)>/gi, ' | ')
        .replace(/<\/(?:div|p|section|article|header|footer|tr|li|blockquote|h[1-6]|span|font|b|strong|i|em|u|small|table|tbody|thead|ul|ol|details|summary)>/gi, '')
        .replace(/[ \t]*\|[ \t]*(?=\n|$)/g, '')
        .replace(/[ \t]{2,}/g, ' ')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

function fixOwnPromptRole(data) {
    if (!data || data.dryRun || !Array.isArray(data.chat)) return;
    // 🧹 Экономия токенов без потери смысла: для старых постов ролевой (старше последних 5 реплик)
    // очищаем HTML/CSS-обёртки (Двач/Телеграм/style-атрибуты) и скрытые <!--...--> метки только в исходящем запросе к ИИ (в чате на экране всё остаётся красивым!)
    if (!ownRequest && settings().enabled && settings().tokenSaverMode !== false) {
        const msgsAll = data.chat;
        const chatIndices = [];
        for (let idx = 0; idx < msgsAll.length; idx++) {
            const r = msgsAll[idx]?.role;
            if ((r === 'user' || r === 'assistant') && typeof msgsAll[idx]?.content === 'string') {
                chatIndices.push(idx);
            }
        }
        const cutoff = Math.floor(Math.max(0, chatIndices.length - 5) / 5) * 5;
        for (let k = 0; k < cutoff; k++) {
            const m = msgsAll[chatIndices[k]];
            if (m && typeof m.content === 'string') {
                const cleaned = stripBloatHtmlForPrompt(m.content);
                if (cleaned && cleaned.length < m.content.length) {
                    m.content = cleaned;
                }
            }
        }
    }
    if (!ownRequest && ffPending && ffAnsweredOnce && Number.isInteger(ffTargetMesId)) {
        const curLen = ctx().chat?.length ?? 0;
        const lastMsg = ctx().chat?.[curLen - 1];
        // Если после сгенерированного ответа сцены игрок уже отправил новое сообщение (или начался следующий ход), снимаем промпт сцены
        if (curLen - 1 > ffTargetMesId || (lastMsg?.is_user && curLen > ffTargetMesId)) {
            clearFastForward();
        }
    }
    // свой запрос узнаём по началу его текста (не все наши промпты начинаются с OOC-пометки)
    const marker = ownRequest ? (ownPrompt.slice(0, 60) || OWN_MARKER) : ffPending ? FF_MARKER : null;
    if (!marker) return;
    const msgs = data.chat;
    for (let i = msgs.length - 1; i >= 0; i--) {
        const m = msgs[i];
        const contentStr = msgContentText(m?.content);
        if (!contentStr || !contentStr.includes(marker)) continue;
        if (ownRequest && ownPromptIsSelfContained) {
            // Для самодостаточных запросов (Саммари всей истории, Дневник НПС, Досье героя) оставляем в запросе ТОЛЬКО сам собранный промпт,
            // чтобы 50 сырых сообщений чата и пресет персонажа не переполняли контекст и не сбивали модель!
            const selfContent = typeof m.content === 'string' ? m.content : contentStr;
            msgs.splice(0, msgs.length, { role: 'user', content: selfContent });
            return;
        }
        if (m.role !== 'system') return;
        const prev = msgs[i - 1];
        if (prev && prev.role === 'user' && typeof prev.content === 'string' && typeof m.content === 'string') {
            prev.content += '\n\n' + m.content;
            msgs.splice(i, 1);
        } else {
            m.role = 'user';
            delete m.name;
        }
        return;
    }
}

// Модели иногда ставят вместо пробелов невидимые символы (⠀, неразрывный пробел и т.п.) —
// приводим их к обычным пробелам, иначе команды не распознаются
const ODD_SPACES = /[   -​  ⠀　ㅤ﻿]/g;
function normalizeSpaces(t) {
    return String(t ?? '').replace(ODD_SPACES, ' ');
}

async function quietGenerate(prompt, maxTokens = 0) {
    return stripActionTags(normalizeSpaces(await quietGenerateRetry(prompt, maxTokens)));
}

function adaptWriterNoteForTask(rawWriterNote, isComicStripTask) {
    let note = String(rawWriterNote || '').trim();
    if (!note) return '';
    if (isComicStripTask) {
        // Если в пользовательском промпте для GLM написано «Выдай ТОЛЬКО строки CAST и SCENE», заменяем это требование на формат кадров комикса, чтобы GLM не игнорировал PANEL1..4!
        note = note.replace(/выдай\s+только\s+строки\s+CAST\s+и\s+SCENE[^\n.]*/gi, 'IN COMIC MODE output ONLY the lines CAST, PANEL1..PANEL3 (or PANEL4) and QUOTE1..QUOTE3 (or QUOTE4), WITHOUT a general SCENE line!');
        note += '\n\n[IMPORTANT RULE FOR THE MANHWA / COMIC STORYBOARD (PANEL1..PANEL3/4):\n1) Output the lines CAST:, PANEL1:, PANEL2:, PANEL3: (and PANEL4: if 4 frames are requested) + QUOTE1:, QUOTE2:, QUOTE3: (no SCENE line!).\n2) In EVERY QUOTE line write a FULL, COMPLETE sentence up to the final full stop, exclamation or question mark, verbatim in the original language of the post (NO shortening and NO «...» in the middle!): for speech write `SPEECH | Name | text`, for inner thoughts — `THOUGHT | Name | text`, for narration — `NARRATION | a full narration sentence WITHOUT a name` (don\'t take stubs of speech verbs like «сказала она» into NARRATION — take full action sentences!). Put each QUOTE line under the number of the PANEL frame it belongs to (under a frame without people put NARRATION about that detail, under a frame with a person — their SPEECH or THOUGHT)!\n3) 🔍 EXCEPTION FOR DETAIL CLOSE-UPS (ANIMALS, OBJECTS, HANDS): the rules above about mandatory 1boy/1girl tags, full-height calibration (tall lean adult man, long male legs, wider male shoulders) and describing faces/hairstyles apply ONLY to frames with people at full/medium height! If the passage has an animal/pet (a snake, cat, dog), an important object or a tactile hand gesture — be sure to make one frame (PANEL2 or PANEL3) a CLOSE-UP OF THAT DETAIL with NO faces and NO height tags (for an animal/object: no humans, animal focus / object focus, close-up, macro shot, ...; for hands: close-up, hand focus, head out of frame, cropped). ⚠️ 18+ erotica is NOT a detail: it is a close shot with people (nsfw, explicit, 1boy, 1girl, hetero, close-up, from side, action tags + CHAR slots of both characters), both bodies connected in the frame; no head out of frame / cropped / focus on.\n4) In the other frames don\'t cram a crowd (4–7 people): draw 1–2 participants of the current moment, and for an emotional portrait use a solo shoulders/chest shot (1boy, solo, close-up, portrait, upper body or 1girl, solo, close-up, portrait, upper body).\n5) Don\'t translate metaphors literally: instead of "lion mane" on a person write "thick wild hair", instead of "greenish-pale" write "pale skin, unwell, sweatdrop".]';
    }
    return note;
}

async function generateViaImagePromptSource(taskPrompt) {
    const s = settings();
    const src = String(s.imgPromptSource || '').trim();
    if (!src) return null;

    const rawWriterNote = String(s.imgPromptWriterNote || '').trim();
    const isComicStripTask = /\bPANEL1\s*:/i.test(String(taskPrompt || ''));
    const writerNote = adaptWriterNoteForTask(rawWriterNote, isComicStripTask);
    const writerBlock = writerNote
        ? `[The author's instruction to the image prompt writer (follow it strictly!):
${writerNote}]

`
        : '';
    // НЕ вызываем buildStandaloneContextPrompt (чтобы в GLM не попадали ch.personality, ch.scenario и 25 постов гротескной комедии)!
    // Внутри taskPrompt уже есть чистые блоки внешности, OLDBlock и текущая сцена.
    const userOnlyPrompt = ctx().substituteParams(String(taskPrompt || ''));
    const fullPrompt = writerBlock + userOnlyPrompt;

    if (src === 'custom-api') {
        let base = String(s.imgPromptApiBase || 'https://open.bigmodel.cn/api/paas/v4').trim().replace(/\/+$/, '');
        const key = String(s.imgPromptApiKey || '').trim();
        const model = String(s.imgPromptApiModel || 'glm-4-plus').trim();
        if (!base || !key || !model) {
            throw new Error('Для отдельной модели промптов картинок заполни адрес API, ключ и название модели (например glm-4-plus или glm-4-flash)');
        }
        if (base.includes('generativelanguage.googleapis.com') && !base.includes('/openai')) {
            base = 'https://generativelanguage.googleapis.com/v1beta/openai';
        }
        const endpoint = base.endsWith('/chat/completions') ? base : `${base}/chat/completions`;
        const messages = [];
        if (writerNote) {
            messages.push({ role: 'system', content: writerNote });
        }
        messages.push({ role: 'user', content: writerNote ? userOnlyPrompt : fullPrompt });
        return await withSharedKeyRetry(async () => {
            const res = await withTimeout(imagesFetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${key}`,
                },
                body: JSON.stringify({
                    model,
                    messages,
                    max_tokens: 4096,
                    temperature: 0.55,
                }),
            }), 75000, `модель промптов картинок (${model})`);
            const text = await res.text();
            let json = null;
            try { json = JSON.parse(text); } catch (e) { /* ignore */ }
            if (!res.ok) {
                throw new Error(`API промптов картинок (${res.status}): ${String(json?.error?.message || text).slice(0, 200)}`);
            }
            const extracted = extractTextFromApiResult(json) || text;
            if (!extracted || !String(extracted).trim()) {
                throw new Error('Модель промптов вернула пустой ответ');
            }
            return extracted;
        }, `промпт раскадровки (${model})`, 5, 4000);
    }

    return await withSharedKeyRetry(
        () => sendViaTavernProfile(src, writerNote ? userOnlyPrompt : fullPrompt, 4096, 'профиль модели для промптов картинок', writerNote, true),
        'профиль промптов раскадровки',
        5,
        4000
    );
}

// maxTokens: свой лимит длины ответа. Без него основное подключение берёт «Длину ответа» из пресета (часто 300–1000),
// и модель с размышлениями (GLM и т.п.) тратит его целиком на размышление — ответ приходит пустым.
async function quietGenerateImagePrompt(prompt, maxTokens = 4096) {
    const s = settings();
    if (s.imgPromptSource) {
        try {
            const res = await generateViaImagePromptSource(prompt);
            if (res && String(res).trim()) {
                return stripActionTags(normalizeSpaces(res));
            }
        } catch (err) {
            console.warn('[npc_notebook] imgPromptSource failed, falling back to quietGenerate:', err);
            toastr.warning(`Отдельная модель промптов картинок не ответила (${escapeHtml(err?.message || err)}) — использую запасное подключение (с сохранением твоего промпта писателя).`, '🎨 Промпт картинки', { escapeHtml: false, timeOut: 7000 });
        }
    }
    const rawWriterNote = String(s.imgPromptWriterNote || '').trim();
    const isComicStripTask = /\bPANEL1\s*:/i.test(String(prompt || ''));
    const writerNote = adaptWriterNoteForTask(rawWriterNote, isComicStripTask);
    const writerPrefix = writerNote
        ? `[The author's instruction to the image prompt writer (follow it strictly!):
${writerNote}]

`
        : '';
    const res = await quietGenerate(writerPrefix + prompt, maxTokens);
    if (String(res ?? '').trim() || nnbStopActive() || String(prompt || '').includes(SELF_CONTAINED_PROMPT_MARKER)) return res;
    // Пусто: Таверна при ошибке API (например 400 «check the request parameters») отдаёт расширению пустую строку.
    // Задание для картинки самодостаточное (внешность, пост, прошлые кадры уже внутри) — повторяем его одно,
    // без истории чата и пресета: так же, как работает отдельная модель промптов.
    logImageDiag('⚠️ Основное подключение вернуло пустой ответ или ошибку — повторяю запрос только с заданием, без истории чата и пресета');
    return quietGenerate(SELF_CONTAINED_PROMPT_MARKER + writerPrefix + prompt, Math.max(maxTokens, 8192));
}

// При ошибке лимита (429) ждём и пробуем ещё раз
async function quietGenerateRetry(prompt, maxTokens = 0) {
    try {
        const res = await quietGenerateOnce(prompt, maxTokens);
        // Пустой ответ при живом подключении — почти всегда модель с размышлениями (GLM, DeepSeek R1 и т.п.)
        // потратила весь лимит длины на размышление. Повторяем один раз с большим лимитом.
        if (!String(res ?? '').trim() && maxTokens < 8192 && !nnbStopActive()) {
            console.warn('[npc_notebook] empty answer, retrying with bigger responseLength');
            setStatus('Модель вернула пустой ответ — повторяю с бо́льшим лимитом длины…');
            return await quietGenerateOnce(prompt, 8192);
        }
        return res;
    } catch (err) {
        const msg = String(err?.message || err);
        if (nnbIsStopError(err) || !/429|too many|rate|exhausted|quota/i.test(msg)) throw err;
        setStatus('Лимит запросов — жду 30 секунд и пробую ещё раз…');
        toastr.info('Лимит запросов у провайдера. Повторю через 30 секунд.', 'Блокнот рассказчика');
        await new Promise(r => setTimeout(r, 30000));
        return await quietGenerateOnce(prompt, maxTokens);
    }
}

// Модели иногда пишут тег без скобок: «ADD план: …», «INTRIGUE слух — …». Приводим к «ADD [план]: …».
function bracketTag(line) {
    return line.replace(/^(ADD|INTRIGUE|ITEM)\s+([^\s\[\]:：—–-]{1,20})\s*([:：—–-])/i, '$1 [$2]$3');
}

function parseAndApply(raw) {
    const st = store();
    const s = settings();
    const len = ctx().chat.length;
    const res = { added: [], done: [], dropped: [], intrigues: [], clues: 0, solved: 0 };
    const intriguesOn = !!st.direction?.intrigues;
    const npcsOn = !!st.direction?.npcs;
    res.npcNew = 0;
    res.npcUpd = 0;
    res.relNew = 0;
    res.relUpd = 0;
    const arcsOn = !!st.direction?.arcs;
    const need = Math.max(1, Number(s.minStimuli) || 2);
    Object.assign(res, { arcNew: 0, stimuli: 0, shifts: 0, evolved: 0, regress: 0 });
    const findArc = n => st.arcs.find(a => a.id === Number(n));

    const text = String(raw || '')
        .replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, '')
        .replace(/\*\*/g, '')
        .trim();

    if (!text || /^NONE[.!]?$/i.test(text)) return res;

    const CMD_START_RE = /^(?:TIME|DATE|PLACE|EVENT|LOCAL|HOLIDAY|BDAY|TASK(?:_?DONE)?|RESULT|MEDAL|TRACE|STORY|SECRET|DIARY|OUTCOME|DROP_?ITEM|ITEM|MAP|HERE|OUTFIT_?DONE|OUTFIT|ADD|ARC|STIMULUS|SHIFT|REGRESS|DROP|NPCFACT|NPCSTATE|NPC|KEYS|PROFILE|SCALE|RELSCALE|REL|DONE_?TOPIC|TOPIC|NEIGHBOR|DREAM|INTRIGUE|CLUE|SOLVED|DONE|SEASON|FLAVOR|CLOSET|PERF_?ITEM|ACC_?ITEM|TREND|COUNTER|FAMILY_?USER|FAMILY_?CHAR|SOCIAL_?CIRCLE|HOME_?ROOM|APPEARANCE|LOOK|EN|EFFECT|ACCENT|CAST|SCENE|CHAR\d+|CONTINUITY|SETUP|READY|BRIDGE|PLAN(?:_?CANCEL|_?MOVE)?|NONE)(?:\b|[\s\[:：—–-])/i;
    const mergedLines = [];
    for (const rawLine of text.split(/\r?\n/)) {
        const cleaned = bracketTag(rawLine.trim().replace(/^[-*•>\s]+/, '').replace(/^`+|`+$/g, '')).trim();
        if (!cleaned || /^\[OOC:/i.test(cleaned) || /^\]$/.test(cleaned) || /^#+$/.test(cleaned)) continue;
        if (CMD_START_RE.test(cleaned) || !mergedLines.length) {
            mergedLines.push(cleaned);
        } else {
            const prev = mergedLines[mergedLines.length - 1];
            if (/[:：—–-]\s*$/.test(prev)) {
                mergedLines[mergedLines.length - 1] = `${prev} ${cleaned}`;
            } else {
                mergedLines[mergedLines.length - 1] = `${prev} // ${cleaned}`;
            }
        }
    }

    for (let line of mergedLines) {
        line = bracketTag(line.trim().replace(/^[-*•>\s]+/, '').replace(/^`+|`+$/g, ''));
        if (!line) continue;
        if (applyTimeCommand(st, line, res)) continue;
        if (st.direction.time && applyEventCommand(st, line, res)) continue;

        const mdItem = line.match(/^DROP_?ITEM\s*[:：—–-]\s*(.+)$/i);
        if (mdItem) {
            if (st.wardrobe && Array.isArray(st.wardrobe.box)) {
                const targetTitle = mdItem[1].trim().replace(/^[«"']|[»"'\]]$/g, '').toLowerCase();
                if (targetTitle) {
                    st.wardrobe.box = st.wardrobe.box.filter(x => x.onCounter || x.title.toLowerCase() !== targetTitle);
                }
            }
            continue;
        }

        const mi = line.match(/^ITEM\s*(?:\[([^\]]{1,30})\])?\s*[:：—–-]\s*(.+)$/i);
        if (mi) {
            if (st.wardrobe && Array.isArray(st.wardrobe.box) && st.direction?.autoBoxItems === true) {
                const rawBody = mi[2].trim().replace(/\]$/, '');
                let t = '', desc = '', en = '', origin = '';
                if (rawBody.includes('|')) {
                    const parts = rawBody.split('|').map(x => x.trim());
                    t = (parts[0] || '').replace(/^[«"]|[»"]$/g, '');
                    if (parts.length >= 4) {
                        desc = parts[1] || '';
                        en = parts[2] || '';
                        origin = parts.slice(3).join(' | ');
                    } else if (parts.length === 3) {
                        const p1En = /[a-zA-Z]{3,}/.test(parts[1]) && !/[а-яА-ЯёЁ]/.test(parts[1]);
                        const p2En = /[a-zA-Z]{3,}/.test(parts[2]) && !/[а-яА-ЯёЁ]/.test(parts[2]);
                        if (p1En) {
                            en = parts[1];
                            origin = parts[2];
                        } else if (p2En) {
                            desc = parts[1];
                            en = parts[2];
                        } else {
                            desc = parts[1];
                            origin = parts[2];
                        }
                    } else if (parts.length === 2) {
                        desc = parts[1] || '';
                    }
                } else {
                    const [titlePart, ...rest] = rawBody.split(/\s[—–-]\s/);
                    t = (titlePart || '').trim().replace(/^[«"]|[»"]$/g, '');
                    origin = rest.join(' — ').trim();
                }
                const fullCheckStr = `${t} ${desc} ${origin}`.toLowerCase();
                const isKeeperItem = /духи|парфюм|аромат|флакон|кольц|серьг|кулон|брош|браслет|ожерел|колье|подвеск|часы|заколк|гребн|шарф|платок|сумоч|сумк|клатч|медальон|цепочк|книг|дневник|ключ|письм|карт|шкатулк|статуэтк|свеч|зеркал|артефакт|талисман|амулет|фоторамк|картин|ваз|пластинк|игрушк|брелок|значок/i.test(fullCheckStr);
                const isFoodOrGivenAway = (!isKeeperItem && /(шоколад|карамел|конфет|леденец|леденц|мармелад|зефир|печень|пирожн|торт|булочк|круассан|хлеб|бутерброд|сэндвич|пицц|суп|салат|мяс|рыб|яблок|груш|апельсин|мандарин|ягод|фрукт|морожен|жвачк|вафл|чипс|орех|фундук|кофе|какао|чай|сок|лимонад|вода|молоко|вино|пиво|сигарет|салфетк|одноразов|(?:^|[^а-яё])чек(?=[^а-яё]|$)|тарелк|чашк|стакан)/i.test(fullCheckStr))
                    || /(отдал[аи]?|раздал[аи]?|угостил[аи]?|съел[аи]?|выпил[аи]?|выбросил[аи]?|подарил[аи]? детям|отдали детям)/i.test(fullCheckStr);
                if (t && !isFoodOrGivenAway && !st.wardrobe.box.some(x => x.title.toLowerCase() === t.toLowerCase()) && st.wardrobe.box.length < 50) {
                    const kindStr = `${mi[1] || ''} ${t}`;
                    const resolvedKind = findKind(kindStr) !== 'find' ? findKind(kindStr) : (mi[1] ? accentKind(mi[1]) : 'find');
                    const newItem = {
                        id: st.wardrobe.nextItemId++,
                        kind: resolvedKind,
                        title: t,
                        desc: desc || '',
                        en: en || '',
                        origin: origin || 'получено по сюжету',
                        onCounter: false,
                        at: len,
                    };
                    st.wardrobe.box.push(newItem);
                    (res.items = res.items || []).push(t);
                    (res.newBoxItems = res.newBoxItems || []).push(newItem);
                }
            }
            continue;
        }
        const mp = line.match(/^MAP\s*[:：—–-]\s*(.+)$/i);
        if (mp) {
            if (st.direction.map) { const pl = addPlace(st, mp[1], 'story'); if (pl) (res.places = res.places || []).push(pl.title); }
            continue;
        }
        const mh = line.match(/^HERE\s*[:：—–-]\s*(.+)$/i);
        if (mh) {
            // место ведёт шапка поста — если она совпала с местом на карте; иначе (шапка на другом языке и т.п.) слушаем HERE
            if (st.direction.map && nnbHeaderMode(st) && st.time?.headerSeen?.location && st.map.current) continue;
            if (st.direction.map && /^(?:нигде|нет|—|-|none|не на карте)(?![а-яёa-z])/i.test(mh[1].trim())) { st.map.current = null; continue; }
            if (st.direction.map) {
                const pl = findPlace(st, mh[1].split('|')[0]);
                if (pl && st.map.current !== pl.id) {
                    st.map.current = pl.id;
                    st.map.enteredAt = len;
                }
            }
            continue;
        }
        if (/^OUTFIT\s*_?\s*DONE\b/i.test(line)) {
            res.outfitDone = true;
            continue;
        }
        const mo = line.match(/^OUTFIT\s*[:：—–-]\s*(.+)$/i);
        if (mo) {
            res.outfit = mo[1].trim().replace(/\]$/, '');
            continue;
        }

        {
            const mpc = line.match(/^PLAN_?CANCEL\s*#?\s*P?(\d+)/i);
            if (mpc) {
                const p = nnbPlans(st).find(x => x.id === Number(mpc[1]));
                if (p) {
                    p.status = 'cancelled';
                    st.notes = (st.notes || []).filter(n => !(n.planId === p.id && n.planRole));
                }
                continue;
            }
            const mpm = line.match(/^PLAN_?MOVE\s*#?\s*P?(\d+)\s*[:：—–-]?\s*(.+)$/i);
            if (mpm) {
                const p = nnbPlans(st).find(x => x.id === Number(mpm[1]));
                let nd = '';
                try { nd = parseDateText(mpm[2], st.time?.date || '') || ''; } catch (e) { nd = ''; }
                if (p && nd) {
                    p.date = nd;
                    (st.notes || []).forEach(n => { if (n.planId === p.id) { if (n.planRole === 'event') n.onDate = nd; if (n.planRole === 'prep') n.deadline = nd; } });
                }
                continue;
            }
            const mp = line.match(/^PLAN\s*\[?([^:：\]]{0,40}?)\]?\s*[:：—–]\s*(.+)$/i);
            if (mp) {
                const p = nnbAddPlan(st, mp[1], mp[2]);
                if (p) (res.plans || (res.plans = [])).push(p);
                continue;
            }
        }
        if (st.direction?.notes === 'director') {
            const dx = nnbDirectorExtra(st);
            const mc = line.match(/^CONTINUITY\s*[:：—–-]\s*(.+)$/i);
            if (mc) {
                if (!res._contReset) { dx.continuity = []; res._contReset = true; }
                if (dx.continuity.length < 3) dx.continuity.push(mc[1].trim().slice(0, 220));
                continue;
            }
            const ms = line.match(/^SETUP\s*[:：—–-]\s*(.+)$/i);
            if (ms) {
                const t = ms[1].trim().slice(0, 200);
                if (t && !dx.setups.some(x => x.text === t)) { dx.setups.push({ text: t, at: len, used: false }); if (dx.setups.length > 8) dx.setups.splice(0, dx.setups.length - 8); }
                continue;
            }
            const mr = line.match(/^READY\s*#?\s*(\d+)/i);
            if (mr) {
                const n = (st.notes || []).find(x => x.id === Number(mr[1]));
                if (n) n.ready = true;
                const dd = nnbDripState(st);
                if (dd.needCheck === Number(mr[1])) { dd.needCheck = null; dd.waitReplies = 0; }
                continue;
            }
            const mb = line.match(/^BRIDGE\s*#?\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
            if (mb) {
                const n = (st.notes || []).find(x => x.id === Number(mb[1]));
                const br = n ? nnbDirectorMakeBridge(st, n, mb[2]) : null;
                const dd = nnbDripState(st);
                if (br && dd.activeId === n.id) { dd.activeId = br.id; dd.shown = 0; dd.tech = null; }
                if (dd.needCheck === Number(mb[1])) { dd.needCheck = null; dd.waitReplies = 0; }
                continue;
            }
        }
        let m = line.match(/^ADD\s*(?:\[([^\]]{1,40})\])?\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const note = { id: st.nextId++, tag: (m[1] || '').trim(), text: m[2].trim(), at: len };
            if (st.direction?.notes === 'director') {
                // ADD [линия]: суть (жанр, накал N/5)
                const ln = nnbDirectorLineOf(st, note.tag);
                if (ln) note.line = ln.id;
                const gm = note.text.match(/\(\s*(?:genre\s*:?\s*|жанр\s*:?\s*)?([a-z]+)\s*[,;]?\s*(?:накал|intensity)?\s*:?\s*(\d)\s*\/\s*5\s*\)\s*\.?\s*$/i);
                if (gm) { if (NNB_DIR_GENRES.includes(gm[1].toLowerCase())) note.genre = gm[1].toLowerCase(); note.intensity = Number(gm[2]); note.text = note.text.slice(0, gm.index).trim(); }
            }
            st.notes.push(note);
            res.added.push(note);
            continue;
        }

        m = line.match(/^ARC(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            if (arcsOn && st.arcs.length < (Number(s.maxArcs) || 6)) {
                st.arcs.push({ id: st.nextArcId++, who: m[1].trim(), text: m[2].trim(), stage: 1, current: '', stimuli: [], sinceShift: 0, at: len });
                res.arcNew++;
            }
            continue;
        }

        m = line.match(/^STIMULUS\s*#?\s*A\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const a = arcsOn && findArc(m[1]);
            if (a) {
                a.stimuli.push({ text: m[2].trim(), at: len });
                if (a.stimuli.length > 6) a.stimuli.shift();
                a.sinceShift++;
                res.stimuli++;
            }
            continue;
        }

        m = line.match(/^(SHIFT|REGRESS)\s*#?\s*A\s*(\d+)\s*[:：—–-]?\s*(.*)$/i);
        if (m) {
            const a = arcsOn && findArc(m[2]);
            if (!a) continue;
            const desc = m[3].trim();
            if (m[1].toUpperCase() === 'REGRESS') {
                a.stage = Math.max(1, a.stage - 1);
                a.sinceShift = 0;
                if (desc) a.current = desc;
                res.regress++;
            } else if (a.sinceShift >= need) {
                a.stage++;
                a.sinceShift = 0;
                if (desc) a.current = desc;
                if (a.stage >= ARC_MAX) {
                    st.evolved.push({ who: a.who, text: `${a.text}${a.current ? ` — ${a.current}` : ''}`, at: len });
                    st.arcs = st.arcs.filter(x => x !== a);
                    res.evolved++;
                } else {
                    res.shifts++;
                }
            } else if (desc) {
                // Если для полного сдвига ещё мало стимулов, сохраняем наблюдение модели как стимул
                a.stimuli.push({ text: desc, at: len });
                if (a.stimuli.length > 6) a.stimuli.shift();
                a.sinceShift++;
                res.stimuli++;
            }
            continue;
        }

        m = line.match(/^DROP\s*#?\s*A\s*(\d+)/i);
        if (m) {
            st.arcs = st.arcs.filter(a => a.id !== Number(m[1]));
            continue;
        }

        m = line.match(/^NPCFACT\s*[:：]?\s*(?:\[([^\]]{1,60})\]|([^:：—–\n]{1,45}?))\s*(?:[:：]|\s+[—–-]\s+)\s*(.+)$/i);
        if (m) {
            if (npcsOn) {
                const name = (m[1] || m[2] || '').trim();
                const factText = (m[3] || '').trim().replace(/\]$/, '').replace(/\s*\/\/\s*/g, '\n').trim();
                if (!name || !factText || /^\(?нет\)?$/i.test(factText) || /^пусто$/i.test(factText)) continue;
                const n = findHeroOrNpc(st, name);
                if (n) {
                    const oldCard = String(n.card || '').trim();
                    const normOld = oldCard.toLowerCase().replace(/\s+/g, ' ');
                    const normFact = factText.toLowerCase().replace(/\s+/g, ' ');
                    if (!oldCard) {
                        n.card = factText;
                        res.npcUpd++;
                    } else if (!normOld.includes(normFact.slice(0, Math.min(45, normFact.length)))) {
                        n.card = `${oldCard}\n${factText}`.trim();
                        res.npcUpd++;
                    }
                }
            }
            continue;
        }

        m = line.match(/^NPC(?!STATE|FACT)\s*[:：]?\s*(?:\[([^\]]{1,60})\]|([^:：—–\n]{1,45}?))\s*(?:[:：]|\s+[—–-]\s+)\s*(.+)$/i);
        if (m) {
            if (npcsOn) {
                const name = (m[1] || m[2] || '').trim();
                const incomingCard = (m[3] || '').trim().replace(/\]$/, '').replace(/\s*\/\/\s*/g, '\n').trim();
                if (!name || !incomingCard) continue;
                // Похожее, но другое имя («Кайла» ≠ «Кайлар», «Яна» ≠ «Ян»): это новый человек, а не тот же —
                // раньше описание сестры дописывалось в чужую карточку, и своя не заводилась
                const n = nnbFindSameHero(st, name);
                if (!n) {
                    // лимита больше нет: раньше после 20 NPC новые молча не создавались
                    st.npcs.push({ id: st.nextNpcId++, name, card: incomingCard, status: '', locked: true, at: len });
                    res.npcNew++;
                } else if (n._replaceCardFull) {
                    if (incomingCard.length >= String(n.card || '').trim().length * 0.8 || String(n.card || '').trim().length < 50) {
                        n.card = incomingCard;
                        res.npcUpd++;
                    } else {
                        n.card = `${String(n.card || '').trim()}\n${incomingCard}`.trim();
                        res.npcUpd++;
                    }
                } else if (!n.locked) {
                    const oldCard = String(n.card || '').trim();
                    // Защита от потери и размывания описания: никогда не заменяем уже существующее описание более коротким куском!
                    if (!oldCard || oldCard.length < 35) {
                        if (incomingCard.length > oldCard.length) {
                            n.card = incomingCard;
                            res.npcUpd++;
                        }
                    } else if (incomingCard.length > oldCard.length * 1.15 && !oldCard.toLowerCase().includes(incomingCard.slice(0, 40).toLowerCase())) {
                        n.card = `${oldCard}\n${incomingCard}`.trim();
                        res.npcUpd++;
                    }
                }
            }
            continue;
        }

        m = line.match(/^NPCSTATE(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            const targetName = m[1].trim();
            const n = npcsOn && findHeroOrNpc(st, targetName);
            if (n) {
                n.status = m[2].trim();
                res.npcUpd++;
            }
            continue;
        }

        m = line.match(/^KEYS(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            if (npcsOn) {
                const targetName = m[1].trim();
                const n = findHeroOrNpc(st, targetName);
                if (n) {
                    ensureNpcScales(n, st);
                    const parts = m[2].split('|').map(x => x.trim());
                    parts.forEach(p => {
                        const km = p.match(/^(цепляет|ключи|нравится|turnons?)\s*[=:]\s*(.+)$/i);
                        if (km && (!n.turnOns || n._allowOverwriteKeys)) { n.turnOns = km[2].trim().replace(/\]$/, ''); return; }
                        const om = p.match(/^(охлаждает|отталкивает|стоп|turnoffs?)\s*[=:]\s*(.+)$/i);
                        if (om && (!n.turnOffs || n._allowOverwriteKeys)) { n.turnOffs = om[2].trim().replace(/\]$/, ''); return; }
                        const pm = p.match(/^(заноза|упрямство|пунктик|раздражает|быт|petpeeves?)\s*[=:]\s*(.+)$/i);
                        if (pm && (!n.petPeeves || n._allowOverwriteKeys)) { n.petPeeves = pm[2].trim().replace(/\]$/, ''); return; }
                        const jm = p.match(/^(ревность|собственничество|ревнует|jealousy)\s*[=:]\s*(.+)$/i);
                        if (jm && (!n.jealousyTriggers || n._allowOverwriteKeys)) { n.jealousyTriggers = jm[2].trim().replace(/\]$/, ''); return; }
                        const mm = p.match(/^(тонус|настроение|нога|mood)\s*[=:]\s*(.+)$/i);
                        if (mm) {
                            if (n.dailyMood !== 'off') {
                                const parsedMood = parseDailyMoodValue(mm[2]);
                                if (parsedMood) n.dailyMood = parsedMood;
                            }
                            return;
                        }
                        const gm = p.match(/^(?:зелёный_?свет|зеленый_?свет|свет)\s*[=:]\s*(.+)$/i);
                        if (gm) {
                            const gv = gm[1].toLowerCase();
                            if (/искр|быстр|сразу|mutual/.test(gv)) n.greenLight = 'mutual_spark';
                            else if (/инициатив|героин|шаг|user/.test(gv)) n.greenLight = 'user_initiative';
                            else if (/слоу|долг|медл|deep/.test(gv)) n.greenLight = 'deep_romance';
                            else n.greenLight = 'emotional_trust';
                            return;
                        }
                        const bm = p.match(/^(?:стиль_?тела|тело|отклик)\s*[=:]\s*(.+)$/i);
                        if (bm) {
                            const bv = bm[1].toLowerCase();
                            if (/контрол|сдерж|subtle/.test(bv)) n.bodyStyle = 'composed_subtle';
                            else if (/импульс|остр|действ|active/.test(bv)) n.bodyStyle = 'intense_active';
                            else if (/искр|игрив|тактил|playful/.test(bv)) n.bodyStyle = 'playful_tactile';
                            else n.bodyStyle = 'soft_warm';
                        }
                    });
                    res.npcUpd++;
                }
            }
            continue;
        }

        m = line.match(/^PROFILE(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            if (npcsOn) {
                const targetName = m[1].trim();
                const n = findHeroOrNpc(st, targetName);
                if (n) {
                    ensureNpcScales(n, st);
                    const parts = m[2].split('|').map(x => x.trim());
                    parts.forEach(p => {
                        const aem = p.match(/^(?:внешность_?en|теги_?внешности|appearance_?en|tags)\s*[=:]\s*(.+)$/i);
                        if (aem) { if (settings().autoAppearance !== false && !String(n.appearanceEn || '').trim()) n.appearanceEn = aem[1].trim().replace(/\]$/, ''); return; } // не затираем уже заданные теги внешности (канон Danbooru) — менять их только вручную или кнопкой «Найти канон»
                        const dm = p.match(/^(?:мечта|цель|стремление)\s*[=:]\s*(.+)$/i);
                        if (dm && (!n.dream || n._allowOverwriteProfile)) { n.dream = dm[1].trim().replace(/\]$/, ''); return; }
                        const fm = p.match(/^(?:страх|боится)\s*[=:]\s*(.+)$/i);
                        if (fm && (!n.fear || n._allowOverwriteProfile)) { n.fear = fm[1].trim().replace(/\]$/, ''); return; }
                        const lm = p.match(/^(?:любит|вкусы|предпочтения|нравится)\s*[=:]\s*(.+)$/i);
                        if (lm && (!n.likes || n._allowOverwriteProfile)) { n.likes = lm[1].trim().replace(/\]$/, ''); return; }
                        const dlm = p.match(/^(?:не_?любит|не_?переносит)\s*[=:]\s*(.+)$/i);
                        if (dlm && (!n.dislikes || n._allowOverwriteProfile)) { n.dislikes = dlm[1].trim().replace(/\]$/, ''); }
                    });
                    res.npcUpd++;
                }
            }
            continue;
        }

        m = line.match(/^(?:SCALE|RELSCALE)(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            if (npcsOn) {
                const targetName = m[1].trim();
                const n = findHeroOrNpc(st, targetName);
                if (n) {
                    ensureNpcScales(n, st);
                    const rawSc = m[2].trim();
                    const parseFlexible = (regex, curVal, minV, maxV) => {
                        const sm = rawSc.match(regex);
                        if (!sm) return curVal;
                        const sign = sm[1];
                        const num = Number(sm[2]);
                        if (Number.isNaN(num)) return curVal;
                        if (sign === '+' || sign === '-') {
                            return Math.max(minV, Math.min(maxV, curVal + (sign === '-' ? -num : num)));
                        }
                        return Math.max(minV, Math.min(maxV, num));
                    };
                    n.friendship = parseFlexible(/дружб[аы]\s*[=:]?\s*([+-]?)\s*(\d+)/i, n.friendship, -100, 100);
                    if (isRomanticTarget(n)) {
                        n.romance = parseFlexible(/романтик[аи]\s*[=:]?\s*([+-]?)\s*(\d+)/i, n.romance, 0, 100);
                        n.spark = parseFlexible(/(?:тел[оа]|возбуждени[ея]|искр[аы]|притяжени[ея]|волнени[ея])\s*[=:]?\s*([+-]?)\s*(\d+)/i, n.spark, 0, 100);
                    } else {
                        n.romance = 0;
                        n.spark = 0;
                    }
                    res.npcUpd++;
                }
            }
            continue;
        }

        m = line.match(/^REL(?=[\s\[:：])\s*[:：]?\s*\[?([^\[:：—–\n]+?)\s*(↔|<->|->|→|—|–|\+)\s*([^\]:：—–\n]+?)\]?\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            if (npcsOn && st.direction.rels !== false) {
                const a = m[1].trim();
                const arrow = (m[2] === '->' || m[2] === '→') ? '→' : '↔';
                const b = m[3].trim();
                const rest = m[4].trim().replace(/\]$/, '');
                let type = '', desc = rest;
                if (rest.includes('|')) {
                    const parts = rest.split('|');
                    type = parts[0].trim();
                    desc = parts.slice(1).join('|').trim();
                } else {
                    const tm = rest.match(/^\[([^\]]{1,30})\]\s*(.+)$/);
                    if (tm) { type = tm[1].trim(); desc = tm[2].trim(); }
                }
                if (!st.relationships) st.relationships = [];
                let rel = findRel(st, a, b);
                if (rel) {
                    if (!rel.locked) {
                        if (type) rel.type = type;
                        rel.desc = desc;
                        rel.arrow = arrow;
                        res.relUpd++;
                    }
                } else if (st.relationships.length < 30) {
                    st.relationships.push({ id: st.nextRelId++, a, b, arrow, type: type || 'связь', desc, locked: false, at: len });
                    res.relNew++;
                }
            }
            continue;
        }

        m = line.match(/^DROP\s*#?\s*R\s*(\d+)/i);
        if (m) {
            if (st.relationships && st.direction.rels !== false) {
                const id = Number(m[1]);
                st.relationships = st.relationships.filter(r => r.id !== id);
            }
            continue;
        }

        m = line.match(/^DONE_?TOPIC\s*#?\s*(?:TP)?\s*(\d+)/i);
        if (m) {
            const tid = Number(m[1]);
            st.topics = (st.topics || []).filter(t => t.id !== tid);
            continue;
        }

        m = line.match(/^TOPIC\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            const title = (parts[0] || '').replace(/^[«"]|[»"]$/g, '');
            const promptText = (parts.slice(1).join(' | ') || title).replace(/\]$/, '').trim();
            if (title && !(st.topics || []).some(t => t.title.toLowerCase() === title.toLowerCase())) {
                if (!Array.isArray(st.topics)) st.topics = [];
                if (!res.topicsNew) {
                    // При обновлении во время размышления убираем старые темы с прошлых шагов, чтобы список всегда обновлялся свежими
                    st.topics = st.topics.filter(t => len - (t.at || 0) < 4);
                }
                if (!st.nextTopicId) st.nextTopicId = 1;
                st.topics.push({ id: st.nextTopicId++, title, prompt: promptText, at: len });
                if (st.topics.length > 6) st.topics.shift();
                res.topicsNew = (res.topicsNew || 0) + 1;
            }
            continue;
        }

        m = line.match(/^NEIGHBOR\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const txt = m[1].trim().replace(/\]$/, '');
            if (txt) {
                if (!Array.isArray(st.neighborStories)) st.neighborStories = [];
                st.neighborStories.push({ id: Date.now() + Math.floor(Math.random() * 1000), text: txt, date: st.time?.date || '', at: len });
                if (st.neighborStories.length > 20) st.neighborStories.shift();
                res.neighborNew = (res.neighborNew || 0) + 1;
            }
            continue;
        }

        m = line.match(/^DREAM(?=[\s\[:：])\s*[:：]?\s*\[?([^\]:：—–\n]{1,60}?)\]?\s*(?:[:：]|\s[—–-]\s)\s*(.+)$/i);
        if (m) {
            const who = m[1].trim();
            const parts = m[2].split('|').map(x => x.trim());
            const kind = /кошмар|nightmare|страш/i.test(parts[0] || '') ? 'nightmare' : 'dream';
            const txt = (parts.length > 1 ? parts.slice(1).join(' | ') : parts[0]).replace(/\]$/, '').trim();
            if (txt) {
                if (!Array.isArray(st.dreams)) st.dreams = [];
                st.dreams.push({ id: Date.now() + Math.floor(Math.random() * 1000), who, kind, text: txt, date: st.time?.date || '', active: true, at: len });
                if (st.dreams.length > 15) st.dreams.shift();
                res.dreamNew = (res.dreamNew || 0) + 1;
            }
            continue;
        }

        m = line.match(/^INTRIGUE\s*(?:\[([^\]]{1,40})\])?\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            if (intriguesOn) {
                const it = { id: st.nextIntrigueId++, tag: (m[1] || '').trim(), text: m[2].trim(), clues: [], at: len };
                st.intrigues.push(it);
                res.intrigues.push(it);
            }
            continue;
        }

        m = line.match(/^CLUE\s*#?\s*T?\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const it = st.intrigues.find(x => x.id === Number(m[1]));
            if (it) {
                it.clues.push({ text: m[2].trim(), at: len });
                if (it.clues.length > 8) it.clues.shift();
                res.clues++;
            }
            continue;
        }

        m = line.match(/^(SOLVED|DROP)\s*:?\s*#?\s*T\s*(\d+)/i);
        if (m) {
            const i = st.intrigues.findIndex(x => x.id === Number(m[2]));
            if (i >= 0) {
                const [it] = st.intrigues.splice(i, 1);
                it.kind = 'intrigue';
                it.status = m[1].toUpperCase() === 'SOLVED' ? 'done' : 'dropped';
                it.closedAt = len;
                st.archive.push(it);
                if (it.status === 'done') res.solved++;
            }
            continue;
        }

        m = line.match(/^(DONE|DROP)\s*:?\s*#?\s*(\d+)/i);
        if (m) {
            const id = Number(m[2]);
            const i = st.notes.findIndex(n => n.id === id);
            if (i >= 0) {
                const [n] = st.notes.splice(i, 1);
                n.status = m[1].toUpperCase() === 'DONE' ? 'done' : 'dropped';
                n.closedAt = len;
                if (n.status === 'done') nnbDirectorRecord(st, n);
                if (st.director) {
                    if (n.bridgeFor != null) { const orig = st.notes.find(x => x.id === n.bridgeFor); if (orig) orig.ready = false; }
                    if (n.planRole === 'event' && n.status === 'done') { const pl = (st.plans || []).find(x => x.id === n.planId); if (pl) pl.status = 'done'; }
                    const dd = st.notesDrip;
                    if (n.status === 'done' && dd?.tech?.noteId === n.id && dd.tech.setupText) {
                        const su = (st.director.setups || []).find(x => x.text === dd.tech.setupText);
                        if (su) su.used = true;
                    }
                }
                st.archive.push(n);
                (n.status === 'done' ? res.done : res.dropped).push(n);
            }
        }
    }

    const max = Math.max(1, Number(s.maxActive) || 12);
    // лимит — только для задумок, придуманных моделью; свои и импортированные из режиссёра не выкидываем
    while (st.notes.filter(x => !x.manual).length > max) {
        const autoIdx = st.notes.findIndex(x => !x.manual);
        const n = st.notes.splice(autoIdx, 1)[0];
        n.status = 'dropped';
        n.closedAt = len;
        st.archive.push(n);
    }
    const maxI = Math.max(1, Number(s.maxIntrigues) || 5);
    while (st.intrigues.length > maxI) {
        const it = st.intrigues.shift();
        Object.assign(it, { kind: 'intrigue', status: 'dropped', closedAt: len });
        st.archive.push(it);
    }
    if (st.archive.length > 50) st.archive.splice(0, st.archive.length - 50);
    return res;
}

function report(res, manual, raw) {
    const s = settings();
    const clean = String(raw || '').replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, '').trim();
    if (!clean) {
        toastr.warning('Модель вернула пустой ответ. Обычно это значит, что «думающей» модели не хватило лимита длины ответа, или ответ заблокировал фильтр провайдера.', 'Блокнот рассказчика', { timeOut: 10000 });
        return;
    }
    const parts = [];
    if (res.added.length) parts.push(`новых записей: ${res.added.length}`);
    if (res.done.length) parts.push(`выполнено: ${res.done.length}`);
    if (res.dropped.length) parts.push(`вычеркнуто: ${res.dropped.length}`);
    if (res.intrigues.length) parts.push(`новых тайн: ${res.intrigues.length}`);
    if (res.clues) parts.push(`открылось улик: ${res.clues}`);
    if (res.solved) parts.push(`раскрыто тайн: ${res.solved}`);
    if (res.npcNew) parts.push(`новых NPC: ${res.npcNew}`);
    if (res.npcUpd) parts.push(`обновлено NPC: ${res.npcUpd}`);
    if (res.relNew) parts.push(`новых связей: ${res.relNew}`);
    if (res.relUpd) parts.push(`обновлено связей: ${res.relUpd}`);
    if (res.arcNew) parts.push(`новых арок: ${res.arcNew}`);
    if (res.stimuli) parts.push(`стимулов: ${res.stimuli}`);
    if (res.shifts) parts.push(`🌱 сдвигов характера: ${res.shifts}`);
    if (res.evolved) parts.push(`🌳 закреплено изменений: ${res.evolved}`);
    if (res.regress) parts.push(`откатов: ${res.regress}`);
    if (res.timeMoved) parts.push(`📅 ${res.timeMoved > 0 ? 'прошло' : 'назад на'} ${daysWord(Math.abs(res.timeMoved))} → ${formatDate(store().time.date)}`);
    else if (res.dateSet) parts.push(`📅 дата истории: ${formatDate(res.dateSet)}`);
    if (res.placeSet) parts.push(`📍 место: ${placeLine(store())}`);
    if (res.events) parts.push(`📖 в дневник: ${res.events.length}`);
    if (res.bdays) parts.push(`🎂 дни рождения: ${res.bdays.join(', ')}`);
    if (res.outfit && store().direction.wardrobe) parts.push('👗 пора выбрать наряд');
    if (res.items) parts.push(`🎁 в шкатулку: ${res.items.join(', ')}`);
    if (res.places) parts.push(`🗺 на карте: ${res.places.join(', ')}`);
    if (res.outfitDone && store().direction.wardrobe) parts.push('🎭 образ отыгран');
    holidaySummary(res).forEach(x => parts.push(escapeHtml(x)));
    if (!parts.length) {
        if (/^NONE[.!]?$/i.test(clean.replace(/\*\*/g, ''))) {
            if (manual) toastr.info('Модель решила ничего не записывать', 'Блокнот рассказчика');
        } else {
            toastr.warning('Модель ответила не по формату — загляни в «Последний ответ модели»', 'Блокнот рассказчика', { timeOut: 8000 });
        }
        return;
    }
    if (!s.showToasts && !manual) return;
    let body = parts.join(', ');
    if (!s.hideSpoilers && res.added.length) {
        body += '<br>' + res.added.map(n => `• ${escapeHtml(n.text)}`).join('<br>');
    }
    if (!s.hideSpoilers && res.intrigues.length) {
        body += '<br>' + res.intrigues.map(n => `🔒 ${escapeHtml(n.text)}`).join('<br>');
    }
    toastr.success(body, 'Блокнот рассказчика', { escapeHtml: false, timeOut: 8000 });
}

function escapeHtml(t) {
    return String(t).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}


async function generateActionPromptsNow(forceReroll = false) {
    const c = ctx();
    const chat = c.chat;
    if (!chat || !chat.length) return toastr.warning('Чат пуст', '💡 Подсказки');
    const lastIdx = chat.length - 1;
    const lastMsg = chat[lastIdx];
    if (!lastMsg || lastMsg.is_user) return toastr.info('Подсказки действий создаются для последнего ответа персонажа', '💡 Подсказки');

    const prevActions = Array.isArray(lastMsg.extra?.actions) ? [...lastMsg.extra.actions] : [];
    const names = storyNames();
    const user = names.user;
    const st = store();
    const recentMsgs = chat.filter(m => m && !m.is_system && m.mes).slice(-3).map((m, idx, arr) => {
        const who = m.is_user ? user : (m.name || names.char);
        const rawTxt = stripTags(stripActionTags(String(m.mes || ''))).replace(/<[^>]+>/g, '').trim();
        const lim = idx === arr.length - 1 ? 3600 : 1400;
        const txt = rawTxt.length <= lim ? rawTxt : `${rawTxt.slice(0, Math.floor(lim * 0.4))} … ${rawTxt.slice(-Math.floor(lim * 0.6))}`;
        return `${who}: ${txt}`;
    }).join('\n\n');
    const notesHint = (st?.notes || []).length ? `Active plot ideas: ${st.notes.slice(-3).map(n => n.text).join('; ')}.` : '';
    const avoidPrev = prevActions.length ? `\n— Do NOT repeat the previous options (${prevActions.join('; ')}) — come up with 3 completely different moves!` : '';
    const poiLine = (st && livingWorldOn(st))
        ? `\n— If the scene has points of interest, unusual details of the surroundings, background characters or location hooks, at least one option must invite ${user} to explore, examine or use this hook of the world.`
        : '';
    const prompt = `${SELF_CONTAINED_PROMPT_MARKER}
[OOC: Roleplay paused. You are the author of this story.
The latest messages of the current scene:

${recentMsgs}
${notesHint}

Suggest three possible options for the next move of the player (${user}) — what ${user} HERSELF could do or say right now in response to the ending of the last message. Write the options in the language of the roleplay:
<!--ACTIONS: option 1 | option 2 | option 3-->
Requirements:
— All 3 options are actions and lines of ${user} HERSELF (what ${user} will do or say), NOT other characters' actions towards her! No «hand something to ${user}», «ask ${user}», «look at ${user}» — only ${user} acts.
— The three options must differ substantially in meaning and tone (not rephrasings of one thought).
— Each option takes the scene in a different direction: mix forms (direct speech by ${user}, a physical action or gesture, a pause/silence, a change of topic, an unexpected reaction).${poiLine}${avoidPrev}
— Keep them short (1–2 phrases) so ${user} can pick an option as her next move.
Reply ONLY with a line in the format <!--ACTIONS: option 1 | option 2 | option 3-->]`;

    toastr.info('Придумываю варианты действий…', '💡 Подсказки');
    try {
        const raw = await quietGenerate(prompt);
        const m = raw && raw.match(/(?:<!--\s*ACTIONS|\[\s*ACTIONS|\bACTIONS)\s*[:：]\s*([\s\S]+?)(?:-->|\]|$)/i);
        if (m) {
            const parsed = parseActionPrompts(m[1]);
            if (parsed.length) {
                lastMsg.extra = lastMsg.extra || {};
                lastMsg.extra.actions = parsed;
                await c.saveChat();
                renderActionPrompts();
                toastr.success('Варианты действий готовы!', '💡 Подсказки');
                return;
            }
        }
        toastr.warning('Модель ответила не по формату, попробуй ещё раз', '💡 Подсказки');
    } catch (e) {
        console.error('[npc_notebook] actions generation error:', e);
        toastr.error('Не удалось сгенерировать варианты', '💡 Подсказки');
    }
}

async function think(manual = false) {
    if (busy) return;
    const s = settings();
    const st = store();
    if (!st) {
        if (manual) toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
        return;
    }
    if (!ctx().chat?.length) return;

    const chatIdAtStart = ctx().chatId;
    try { nnbSyncFromHeaders(st); } catch (e) { /* ignore */ }
    let thinkStopped = false;
    busy = true;
    let afterBusy = null;
    setStatus('Модель листает блокнот…');
    // убираем инъекцию на время размышления, чтобы блокнот не дублировался
    ctx().setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(ACTION_INJECT_KEY, '', POS_IN_CHAT, 0);

    try {
        let tpl = ensureSections(s.thinkPrompt);
        // Задумки в размышлении: «полностью» — всегда; ручное 🪶 — всегда (это и есть вызов по требованию);
        // «по капле» — только когда задумок мало (пополнить) или какую-то уже подсказали рассказчику (проверить, сбылась ли — DONE)
        const dripD = (st.direction?.notes === 'drip' || st.direction?.notes === 'director') ? nnbDripState(st) : null;
        const notesInThink = st.direction?.notes === true || manual
            || (dripD && ((st.notes || []).filter(n => !n.ff).length < 3 || dripD.sinceThink));
        if (!notesInThink) {
            tpl = tpl.replace(/(?:Задумки на будущее|Ideas for the future)[\s\S]*?(?=Ответь ТОЛЬКО командами|Reply ONLY with commands)/, '');
        } else if (dripD) dripD.sinceThink = false;
        if (notesInThink && st.direction?.notes === 'director') {
            const bal = nnbDirectorBalance(st).map(b => `${b.id} «${b.name}»: played ${b.pct}%, target ${b.target}%`).join('; ');
            const dirSum = String(nnbDirector(st).summary || '').trim();
            const dirCmd = `${dirSum ? `Director's note on where the story stands: ${dirSum.slice(0, 900)}\n` : ''}Director: story lines — ${bal}. New ideas are invented separately; here ADD only an idea that grew directly out of the latest messages (anchored in a concrete detail, secret or character goal — no stock twists like sudden attacks, mysterious strangers, overheard conversations, storms that trap them together). Format: ADD [line id]: the gist of the scene (genre, intensity N/5); genres: ${NNB_DIR_GENRES.join('/')}. A played idea — DONE #number.`;
            tpl = /(?:Команды|Commands): ADD \[план\|вопрос\|идея\]: (?:текст|text)[^\n]*/.test(tpl)
                ? tpl.replace(/(?:Команды|Commands): ADD \[план\|вопрос\|идея\]: (?:текст|text)[^\n]*/, `${dirCmd}\nCommands: ADD [line id]: text | DONE #number | DROP #number`)
                : tpl.replace('{{notes}}', `{{notes}}\n${dirCmd}`);
        }
        if (st.direction?.notes === 'director') {
            const dx = nnbDirectorExtra(st);
            // идей под отстающую линию нет — режиссёр придумывает отдельным запросом (не чаще раза в 6 сообщений)
            const needLine = nnbDirectorNeedIdeas(st);
            const chatLen = ctx().chat?.length ?? 0;
            if (needLine && (!(Number(dx.lastGenLen) >= 0) || chatLen - Number(dx.lastGenLen) >= 6 || manual)) {
                dx.lastGenLen = chatLen;
                setStatus('🎬 Режиссёр придумывает сцены…');
                try { await nnbDirectorGenerateIdeas(st, needLine); } catch (e) { if (nnbIsStopError(e)) throw e; console.warn('[npc_notebook] director ideas failed', e); }
                if (ctx().chatId !== chatIdAtStart) return;
                setStatus('Модель листает блокнот…');
            }
            const chk = dripD?.needCheck != null ? (st.notes || []).find(n => n.id === dripD.needCheck) : null;
            const dirWatch = `Director's continuity watch (always):
CONTINUITY: one fact the next replies must not contradict — an injury, who is where, what someone holds, who knows or does NOT yet know a secret, a promise or threat still pending. Up to 3 such lines, only real and current ones, in Russian; skip if there are none.
SETUP: a concrete detail planted in the latest messages that could pay off later (an object, a habit, a remark), in Russian — only if there is one.
${nnbPlanCmdText(st)}${chk ? `
Next planned scene #${chk.id}: «${chk.text}»${chk.needs ? ` (needs: ${chk.needs})` : ''}. Would it feel earned right now, given how close the characters are and what they know? If yes — READY #${chk.id}. If not — BRIDGE #${chk.id}: a smaller event (1–2 sentences, in Russian) that naturally builds toward it first.` : ''}`;
            const replyRe = /(?=(?:Ответь ТОЛЬКО командами|Reply ONLY with commands))/;
            tpl = replyRe.test(tpl) ? tpl.replace(replyRe, `${dirWatch}\n\n`) : `${tpl}\n\n${dirWatch}`;
        }
        const raw = await quietGenerate(fillTemplate(tpl, notesInThink ? st.notes : [], buildDirection(st), buildIntrigueSection(st), buildNpcSection(st), buildArcSection(st), buildTimeSectionFull(st), [buildWardrobeSection(st), buildMapSection(st)].filter(Boolean).join('\n')));
        if (ctx().chatId !== chatIdAtStart) return; // чат сменили, пока модель думала
        st.lastRaw = String(raw ?? '');
        const res = parseAndApply(raw);
        try { nnbPlansTick(st); } catch (e) { /* ignore */ }
        if (res.plans?.length && settings().showToasts !== false) toastr.info(res.plans.map(p => `${nnbPlanWhen(st, p)} — ${p.text}`).join('<br>'), '📅 В календарь событий', { escapeHtml: false });
        if (st.direction?.notes === 'director') {
            // новое событие в календаре — режиссёр сразу расписывает его и подготовку к нему (по одному за раз)
            const needPrep = nnbPlans(st).find(p => p.status === 'planned' && !p.prepDone && (nnbPlanDaysLeft(st, p) == null || (nnbPlanDaysLeft(st, p) >= 0 && nnbPlanDaysLeft(st, p) <= 21)));
            if (needPrep) {
                setStatus(`📅 Режиссёр планирует: ${needPrep.text.slice(0, 40)}…`);
                try { await nnbDirectorPlanPrep(st, needPrep); } catch (e) { if (nnbIsStopError(e)) throw e; console.warn('[npc_notebook] plan prep failed', e); }
                if (ctx().chatId !== chatIdAtStart) return;
            }
        }
        if (st.time?.date && Array.isArray(st.scenes)) {
            st.scenes.forEach(sc => { if (!sc.date) sc.date = st.time.date; });
        }
        report(res, manual, raw);
        if (st.direction.time) {
            await fillFlavor(st, false);
            // holidayStep отключён в фоне — запускается вручную из вкладки «События»
        }
        if (st.direction.wardrobe) {
            const w = st.wardrobe;
            if (res.outfitDone && w.active?.status === 'worn') {
                setStatus('🎭 Модель подводит итог образа…');
                if (await revealOutfit(st)) afterBusy = showRevealPopup;
            } else if (res.outfit && !w.active) {
                if (manual) {
                    setStatus('👗 Модель подбирает образы…');
                    if (await generateOutfits(st, res.outfit)) afterBusy = presentLooks;
                } else {
                    const occ = res.outfit;
                    afterBusy = () => {
                        toastr.info(
                            `По сюжету намечается повод подобрать образ («${escapeHtml(occ)}»). Нажми сюда или на 👗, если хочешь открыть примерочную!`,
                            '👗 Гардероб',
                            { timeOut: 12000, extendedTimeOut: 5000, escapeHtml: false, onclick: () => promptGenerateNewOutfits(occ) }
                        );
                    };
                }
            }
        }
    } catch (err) {
        console.error('[npc_notebook]', err);
        if (!nnbIsStopError(err)) toastr.error(String(err?.message || err), 'Блокнот рассказчика: ошибка');
        else thinkStopped = true;
    } finally {
        if (ctx().chatId === chatIdAtStart) {
            if (!thinkStopped) st.lastThinkAt = ctx().chat.length; // остановили вручную — эти сообщения обдумаем в следующий раз
            await ctx().saveMetadata();
        }
        busy = false;
        updateInjection();
        renderPanel();
        if (afterBusy && ctx().chatId === chatIdAtStart) afterBusy();
    }
}

function storyNames() {
    const c = ctx();
    let chars = [];
    try {
        if (c.groupId && Array.isArray(c.groups)) {
            const g = c.groups.find(x => x.id === c.groupId);
            chars = (g?.members || []).map(av => c.characters.find(ch => ch.avatar === av)?.name).filter(Boolean);
        }
    } catch (e) { /* ignore */ }
    if (!chars.length && c.name2) chars = [c.name2];
    return { user: c.name1 || 'игрок', char: chars.join(', ') || 'персонаж', chars };
}

function buildTimeSectionFull(st) {
    if (!st?.direction?.time) return '';
    const names = storyNames();
    return [buildTimeSection(st), bdaySection(st, names.user, names.chars, st.direction.npcs ? st.npcs.map(n => n.name) : []), settings().events ? holidayCheckSection(st) : ''].filter(Boolean).join('\n\n');
}

// Если в своём промпте нет нужных разделов, вставляем их перед финальной инструкцией
function ensureSections(tpl) {
    const missing = ['direction', 'time', 'npcs', 'arcs', 'intrigues', 'wardrobe'].filter(k => !tpl.includes(`{{${k}}}`));
    if (!missing.length) return tpl;
    const block = missing.map(k => `{{${k}}}`).join('\n\n') + '\n\n';
    let at = tpl.lastIndexOf('Ответь ТОЛЬКО');
    if (at < 0) at = tpl.lastIndexOf('Reply ONLY');
    if (at < 0) at = tpl.lastIndexOf('NONE');
    if (at < 0) return tpl + '\n\n' + block;
    const lineStart = tpl.lastIndexOf('\n', at) + 1;
    return tpl.slice(0, lineStart) + block + tpl.slice(lineStart);
}

async function rerollNote(id, kind = 'note') {
    if (busy) return;
    const st = store();
    const isIntrigue = kind === 'intrigue';
    const note = (isIntrigue ? st?.intrigues : st?.notes)?.find(n => n.id === id);
    if (!note) return;
    const chatIdAtStart = ctx().chatId;
    busy = true;
    setStatus('Модель переписывает задумку…');
    ctx().setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
    try {
        const others = isIntrigue ? st.notes : st.notes.filter(n => n.id !== id);
        const tpl = (isIntrigue ? REROLL_INTRIGUE_PROMPT : REROLL_PROMPT).replace('{{old}}', note.text);
        const prompt = fillTemplate(tpl, others, buildDirection(st));
        const raw = String(await quietGenerate(prompt) ?? '');
        if (ctx().chatId !== chatIdAtStart) return;
        st.lastRaw = raw;
        const clean = raw.replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, '').replace(/\*\*/g, '');
        let m = null;
        for (let line of clean.split('\n')) {
            line = bracketTag(line.trim().replace(/^[-*•>\s]+/, ''));
            m = line.match(isIntrigue
                ? /^INTRIGUE\s*(?:\[([^\]]{1,40})\])?\s*[:：—–-]\s*(.+)$/i
                : /^ADD\s*(?:\[([^\]]{1,40})\])?\s*[:：—–-]\s*(.+)$/i);
            if (m) break;
        }
        if (!m) {
            toastr.warning('Модель ответила не по формату — загляни в «Последний ответ модели»', 'Блокнот рассказчика');
            return;
        }
        st.rejected.push(note.text);
        if (st.rejected.length > 15) st.rejected.splice(0, st.rejected.length - 15);
        note.text = m[2].trim().replace(/\]$/, '');
        // у сцены режиссёра были расписанные акценты, место, подводка — они от старого текста, убираем
        for (const k of ['beats', 'place', 'mood', 'pace', 'link', 'avoid', 'anchor', 'title', 'dynamics']) delete note[k];
        if (m[1]) note.tag = m[1].trim();
        note.at = ctx().chat.length;
        if (isIntrigue) note.clues = [];
        if (!settings().hideSpoilers) toastr.success(escapeHtml(note.text), 'Новая задумка', { escapeHtml: false, timeOut: 8000 });
        else toastr.success('Задумка заменена', 'Блокнот рассказчика');
    } catch (err) {
        console.error('[npc_notebook]', err);
        toastr.error(String(err?.message || err), 'Блокнот рассказчика: ошибка');
    } finally {
        if (ctx().chatId === chatIdAtStart) await ctx().saveMetadata();
        busy = false;
        updateInjection();
        renderPanel();
    }
}

// Колорит — отдельным запросом (модель не пропустит его, как строку среди многих команд)
async function fillFlavor(st, manual) {
    const t = st.time;
    if (!placeLine(st) || (!manual && (t.flavor || t.flavorLocked))) return false;
    try {
        const text = cleanFlavor(await quietGenerate(flavorPrompt(st)));
        if (!text) { if (manual) toastr.warning('Модель не написала колорит — попробуй ещё раз', 'Блокнот рассказчика'); return false; }
        // модель иногда вместо справки продолжает сцену — такое не записываем
        const names = storyNames();
        const heroes = [names.user, ...names.chars, ...st.npcs.map(n => n.name)].filter(n => n && n.length > 2).map(n => n.toLowerCase().replace(/ё/g, 'е'));
        const low = text.toLowerCase().replace(/ё/g, 'е');
        if (heroes.some(n => low.includes(n)) || text.length > 1200) {
            st.lastRaw = text;
            toastr.warning('Вместо колорита модель продолжила сцену — не записала. Нажми «Сгенерировать колорит» ещё раз.', 'Блокнот рассказчика', { timeOut: 9000 });
            return false;
        }
        t.flavor = text;
        t.flavorLocked = false;
        if (manual) toastr.success('🧭 Колорит обновлён', 'Блокнот рассказчика');
        return true;
    } catch (err) {
        if (manual) toastr.error(String(err?.message || err), 'Блокнот рассказчика: ошибка');
        return false;
    }
}

// Напоминания, итог закончившегося праздника, запуск нового. Вызывать внутри busy.
async function holidayStep(st, opts) {
    const s = settings();
    await holidayProgress(st, {
        generate: p => quietGenerate(p),
        toast: x => toastr.info(escapeHtml(x).replace(/\n/g, '<br>'), 'Блокнот рассказчика', { escapeHtml: false, timeOut: 9000 }),
        names: storyNames(),
        direction: buildDirection(st),
        lead: Math.max(1, Number(s.leadDays) || 3),
        events: !!s.events,
        showToasts: !!s.showToasts,
    }, opts);
}

async function runHolidayStep(opts) {
    if (busy) return;
    const st = store();
    if (!st || !st.direction.time) return;
    const chatId = ctx().chatId;
    busy = true;
    setStatus('Проверяю праздники…');
    ctx().setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
    try {
        await holidayStep(st, opts);
    } catch (err) {
        console.error('[npc_notebook]', err);
    } finally {
        if (ctx().chatId === chatId) await ctx().saveMetadata();
        busy = false;
        updateInjection();
        renderPanel();
    }
}

async function runFlavor() {
    if (busy) return;
    const st = store();
    if (!st) return;
    busy = true;
    setStatus('Модель пишет местный колорит…');
    ctx().setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
    try {
        await fillFlavor(st, true);
        await ctx().saveMetadata();
    } finally {
        busy = false;
        updateInjection();
        renderPanel();
    }
}

// Общая обёртка для ручных действий с запросом к модели
async function withBusy(status, fn) {
    if (busy) {
        toastr.info('Модель уже занята — подожди пару секунд', 'Блокнот рассказчика');
        return undefined;
    }
    const st = store();
    if (!st) {
        toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
        return undefined;
    }
    const chatId = ctx().chatId;
    busy = true;
    setStatus(status);
    ctx().setExtensionPrompt(INJECT_KEY, '', POS_IN_CHAT, 0);
    ctx().setExtensionPrompt(INJECT_STATIC_KEY, '', POS_IN_CHAT, 0);
    try {
        return await fn(st);
    } catch (err) {
        console.error('[npc_notebook]', err);
        toastr.error(String(err?.message || err), 'Блокнот рассказчика: ошибка');
        return undefined;
    } finally {
        if (ctx().chatId === chatId) await ctx().saveMetadata();
        busy = false;
        updateInjection();
        renderPanel();
    }
}

// Чистит промпт картинки от «мыслей вслух» модели (Wait…, The scene: …?, per rules…), если они протекли в ответ
const NNB_REASONING_SEG_RE = /\?|\b(?:wait|hmm|rule|rules|earlier context|the scene|since they|avoid|per rules|let me|i'll|i will|i should|we should|should be|maybe|actually|okay|not explicit yet|counts?)\b|[=—]\s*\d|^\s*(?:so|but|now|then|also)\b/i;
const NNB_REASONING_DETECT_RE = /\bQUOTE\d\b|→|\bI (?:can|could|will|would|'ll|think)\b|\bcould depict\b|\bessentially\b|\bmoment \d\b|\.\.\.\s*no\b|^\s*no\s*[—-]|\?|\bwait\b|\bhmm\b|\btags?\s*:|\bthe scene\s*:|\bper rules\b|\blet me\b|\bthe rule\b|\bearlier context\b|\bavoid [a-z/ -]+ tags\b/i;
function stripLeakedReasoningFromTags(text) {
    let t = String(text || '');
    if (!t.trim()) return t;
    const charTailIdx = t.search(/\s*\|\|\s*CHAR\s*\d/i);
    const charTail = charTailIdx >= 0 ? t.slice(charTailIdx) : '';
    if (charTailIdx >= 0) t = t.slice(0, charTailIdx);
    // обычный чистый промпт не трогаем вообще — чистим только если в нём явно есть «мысли вслух»
    if (!NNB_REASONING_DETECT_RE.test(t)) return t + charTail;
    const tagsIdx = t.search(/\bTags?\s*:/i);
    if (tagsIdx >= 0) {
        const all = [...t.matchAll(/\bTags?\s*:\s*/gi)];
        const last = all[all.length - 1];
        t = t.slice(last.index + last[0].length);
    }
    const parts = t.split(/\s*,\s*|(?<=[.!?])\s+/).map(x => x.trim().replace(/[.:;]+$/, '').trim()).filter(Boolean);
    const seen = new Set();
    const kept = parts
        .map(x => (/::/.test(x) ? x : x.replace(/^(?!(?:artist|character|copyright|year|rating|location|source|style|fanart)\s*:)[^:]{1,40}:\s*/i, '')).trim())
        .filter(x => x && !NNB_REASONING_SEG_RE.test(x) && !/\bis fine\b|\bfine\b$/i.test(x) && x.split(/\s+/).length <= 14)
        .filter(x => { const k = x.toLowerCase(); if (seen.has(k)) return false; seen.add(k); return true; });
    const out = kept.join(', ') + charTail;
    if (out !== String(text || '').trim() && typeof logImageDiag === 'function' && parts.length !== kept.length) {
        logImageDiag(`🧹 Из промпта убраны рассуждения модели (${parts.length - kept.length} фрагм.)`);
    }
    return out;
}

function cleanAnswer(raw) {
    return normalizeSpaces(raw).replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, '').replace(/\*\*/g, '');
}

function answerLines(raw) {
    return cleanAnswer(raw).split('\n').map(l => l.trim().replace(/^[-*•>\s]+/, '').replace(/^`+|`+$/g, '').trim()).filter(Boolean);
}

// ---------- Перемотка ⏩ ----------

function fastForwardPrompt(st) {
    const parts = ['[OOC: Roleplay paused. You are NOT writing a character reply now. You are the author of this story. The player pressed «fast-forward»: the current scene has run its course, it is time to move to the next event. Reread the chat and pick the most organic continuation — the one that follows naturally from what is happening and has long been asking to enter the story.'];
    const dir = buildDirection(st);
    if (dir) parts.push(dir);
    parts.push('Ideas in the notebook:\n' + formatNotes(st.notes));
    if (st.direction.intrigues && st.intrigues.length) parts.push('Secrets (you may give a new clue or occasion):\n' + formatIntrigues(st.intrigues));
    if (st.direction.time && st.time.date) {
        const up = upcoming(st, 30).map(h => `${h.name} — ${h.ongoing ? 'ongoing now' : h.inDays === 0 ? 'today' : `in ${daysWord(h.inDays)}`}`);
        parts.push(`Now in the story: ${weekday(st.time.date)}, ${formatDate(st.time.date)}.` + (up.length ? `\nUpcoming holidays and dates: ${up.join('; ')}.` : ''));
    }
    parts.push(`Reply with exactly three lines, no explanations:
NEXT: idea number (#3), secret number (T2), HOLIDAY — a holiday or birthday from the calendar, or NEW — your own event
SKIP: how many days pass before the next scene (0 — the same day, just later)
SCENE: how the next scene begins — setting and event in 1–2 sentences in Russian, without the characters' lines and feelings]`);
    return parts.join('\n\n');
}

function parseFastForward(raw) {
    const out = { next: '', skip: 0, scene: '' };
    for (const line of answerLines(raw)) {
        let m = line.match(/^NEXT\s*[:：—–-]\s*(.+)$/i);
        if (m) { out.next = m[1].trim(); continue; }
        m = line.match(/^SKIP\s*[:：—–-]\s*(\d+)/i);
        if (m) { out.skip = Math.min(60, Number(m[1]) || 0); continue; }
        m = line.match(/^SCENE\s*[:：—–-]\s*(.+)$/i);
        if (m) out.scene = m[1].trim().replace(/\]$/, '');
    }
    return out;
}

// ---------- 🎬 За кадром: что происходит у остальных героев ----------
let _lastQuickSceneActionAt = 0;

async function offscreenCutaway() {
    const nowTs = Date.now();
    if (nowTs - _lastQuickSceneActionAt < 4000) return;
    _lastQuickSceneActionAt = nowTs;
    const s = settings();
    if (!s.enabled) return toastr.info('Блокнот выключен', 'Блокнот рассказчика');
    const c = ctx();
    const st = store();
    if (!st || !c.chat?.length) return toastr.warning('Сначала открой чат', '🎬 За кадром');

    const names = storyNames();
    const mc = ensureMainCharCard(st);
    const allHeroes = [...(mc ? [mc] : []), ...(st.npcs || [])];
    if (!allHeroes.length) {
        return toastr.info('В Блокноте пока нет записанных героев или НПС', '🎬 За кадром');
    }

    // Смотрим последние 2 сообщения чата через анти-ясновидение (с учётом падежей и физического присутствия в сцене), чтобы точно определить, кого сейчас нет рядом
    const recentMsgs = c.chat.filter(m => m && !m.is_system && m.mes).slice(-2);
    const absentHeroes = allHeroes.filter(h => {
        if (!h || !h.name) return false;
        return !recentMsgs.some(m => isHeroPhysicallyPresentInMessage(h.name, m.mes, m.name));
    });

    const targetList = absentHeroes.length ? absentHeroes : allHeroes.filter(h => !h.isMainChar);
    if (!targetList.length) {
        return toastr.info('Все известные герои сейчас находятся прямо в текущей сцене!', '🎬 За кадром');
    }

    const rosterBrief = targetList.slice(0, 8).map(h => {
        const parts = [`• ${h.name}: ${h.card || 'знакомый персонаж'}`];
        if (h.status) parts.push(`(last status: ${h.status})`);
        if (h.dream) parts.push(`(personal goal/dream: ${h.dream})`);
        return parts.join(' ');
    }).join('\n');

    const whenStr = (st.direction.time && st.time?.date)
        ? `Now in the story: ${weekday(st.time.date)}, ${formatDate(st.time.date)}${placeLine(st) ? `, ${placeLine(st)}` : ''}. `
        : '';

    const promptText = `${FF_MARKER} the player pressed the «🎬 Off-screen» button. ${whenStr}In the next reply write an atmospheric parallel vignette «Тем временем за кадром…» and briefly (one small paragraph of 2–3 lively sentences each) show what, at this very minute, the other characters who are not next to ${names.user} in the current scene are busy with:
${rosterBrief}
Show their own off-screen life: their current affairs, everyday life, work, personal aims, conversations with each other or a fleeting thought about what is happening, without teleporting them into the room with ${names.user}. At the end of the vignette smoothly return the focus to the current scene with ${names.user}. Write it as fiction, as part of the narration.]`;

    setSceneAdvancePrompt(promptText);
    toastr.info(
        `В следующем посте будет показано, что сейчас происходит за кадром у: <b>${targetList.slice(0, 8).map(h => escapeHtml(h.name)).join(', ')}</b>`,
        '🎬 За кадром',
        { escapeHtml: false, timeOut: 6500 }
    );
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof c.generate === 'function') c.generate('normal');
}

async function nextDayWithDivination() {
    const nowTs = Date.now();
    if (nowTs - _lastQuickSceneActionAt < 4000) return;
    _lastQuickSceneActionAt = nowTs;
    const s = settings();
    if (!s.enabled) return toastr.info('Блокнот выключен', 'Блокнот рассказчика');
    const c = ctx();
    const st = store();
    if (!st || !c.chat?.length) return toastr.warning('Сначала открой чат', '🔮 Новый день + гадание');

    const mc = ensureMainCharCard(st);
    const allHeroes = [...(mc ? [mc] : []), ...(st.npcs || [])].filter(h => h && h.name);
    const oracleCard = allHeroes.find(h => /этель/i.test(h.name))
        || allHeroes.find(h => /(?:гадалка|таро|прорицател)/i.test(`${h.card || ''} ${h.status || ''}`));
    const oracleName = oracleCard ? oracleCard.name : 'Этель';
    const otherHeroes = allHeroes.filter(h => h.name.toLowerCase() !== oracleName.toLowerCase());
    const rosterBrief = otherHeroes.slice(0, 10).map(h => {
        const stPart = h.status ? ` (${h.status})` : '';
        return `• ${h.name}${stPart}`;
    }).join('\n');

    let nextDayLabel = '';
    if (st.direction.time && st.time?.date) {
        st.time.date = addDays(st.time.date, 1);
        st.time.dayStartedAtMsg = c.chat.length;
        // Праздники переведены на ручной вызов
        nextDayLabel = `${weekday(st.time.date)}, ${formatDate(st.time.date)}`;
        ctx().saveMetadata();
        updateInjection();
    }

    const whenStr = nextDayLabel ? ` A new day begins: ${nextDayLabel}.` : '';
    const promptText = `${FF_MARKER} the player pressed the «🔮 New day + fortune-telling» button. Moving to the next day.${whenStr}
But before moving to the main scene of the new day, be sure to insert a fortune-telling by ${oracleName} (tarot cards / a spread):
1) One larger detailed reading — about the main event, the most interesting and intriguing thing you can come up with for the plot (presented as figurative fortune-telling with cards and hints, not a dry retelling).
2) Briefly about the other characters — 1–2 sentences each in the form of a reading${rosterBrief ? `:\n${rosterBrief}` : '.'}
After the reading smoothly move to the next day${nextDayLabel ? ` (${nextDayLabel})` : ''}. Write it as fiction, like a normal roleplay post; don't mention the button or the fast-forward.]`;

    setSceneAdvancePrompt(promptText);
    toastr.info(
        nextDayLabel
            ? `📅 Переходим к <b>${escapeHtml(nextDayLabel)}</b> с гаданием от ${escapeHtml(oracleName)}`
            : `Переходим к следующему дню с гаданием от ${escapeHtml(oracleName)}`,
        '🔮 Новый день + гадание',
        { escapeHtml: false, timeOut: 6000 }
    );
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof c.generate === 'function') c.generate('normal');
}

async function fastForward() {
    const s = settings();
    if (!s.enabled) return toastr.info('Блокнот выключен', 'Блокнот рассказчика');
    if (!ctx().chat?.length) return toastr.warning('Чат пуст — перематывать пока нечего', 'Блокнот рассказчика');
    let text = null;
    let summary = '';
    const ok = await withBusy('⏩ Модель выбирает следующее событие…', async st => {
        const raw = await quietGenerate(fastForwardPrompt(st));
        st.lastRaw = String(raw ?? '');
        const ff = parseFastForward(raw);
        const len = ctx().chat.length;
        const noteId = ff.next.match(/^#?\s*(\d+)/);
        const note = noteId && st.notes.find(n => n.id === Number(noteId[1]));
        if (note) { note.ff = true; note.ffAt = len; }
        let moved = 0;
        if (ff.skip > 0 && st.direction.time && st.time.date) {
            st.time.date = addDays(st.time.date, ff.skip);
            st.time.dayStartedAtMsg = len;
            moved = ff.skip;
            // holidayStep отключён в фоне — запускается вручную из вкладки «События»
        }
        const scene = ff.scene || 'the most organic next event: an idea from your notebook, a secret, a declared story line or an approaching date';
        const when = moved ? ` Between the scenes ${daysWord(moved)} passed — now ${weekday(st.time.date)}, ${formatDate(st.time.date)}.` : (ff.skip > 0 ? ` Between the scenes ${daysWord(ff.skip)}.` : '');
        text = `${FF_MARKER} the player asks to move to the next event. Wrap up the current scene in a phrase or two, without retelling, and start the new one right away: ${scene}${when} Write it as a normal reply; don't mention the fast-forward.]`;
        summary = moved ? `📅 прошло ${daysWord(moved)} → ${formatDate(st.time.date)}` : '';
        if (!s.hideSpoilers && ff.scene) summary = [ff.scene, summary].filter(Boolean).join('<br>');
        return true;
    });
    if (!ok || !text) return;
    setSceneAdvancePrompt(text);
    toastr.info(summary ? escapeHtml(summary).replace(/&lt;br&gt;/g, '<br>') : 'Переходим к следующему событию', '⏩ Дальше', { escapeHtml: false, timeOut: 6000 });
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof ctx().generate === 'function') ctx().generate('normal');
}

// ---------- Праздничные задачи: реролл и правка ----------

async function rerollHolidayTask(idx) {
    await withBusy('Модель придумывает другую задачу…', async st => {
        const hol = st.holiday;
        if (!hol || hol.finished || !hol.tasks[idx]) return;
        const raw = await quietGenerate(rerollTaskPrompt(hol, idx, st, storyNames(), buildDirection(st)));
        st.lastRaw = String(raw ?? '');
        if (!applyTaskReroll(hol, idx, raw)) {
            toastr.warning('Модель ответила не по формату — загляни в «Последний ответ модели»', 'Блокнот рассказчика');
            return;
        }
        const x = hol.tasks[idx];
        if (x.hidden) toastr.success('🔒 Секретная задача заменена', 'Блокнот рассказчика');
        else toastr.success(settings().hideSpoilers ? 'Задача заменена' : escapeHtml(x.text), '🎲 Новая задача', { escapeHtml: false });
    });
}

// ---------- Гардероб 👗 ----------

const ACCENT_KINDS = {
    perfume: { icon: '🌸', name: 'духи' },
    stone: { icon: '💎', name: 'камень' },
    makeup: { icon: '💄', name: 'макияж' },
    pocket: { icon: '👜', name: 'мелочь в сумочке' },
    accessory: { icon: '💍', name: 'аксессуар' },
    find: { icon: '🎴', name: 'находка' },
};
// вещь из находок: украшения и духи годятся в штрихи, остальное — просто находка
function findKind(title) {
    const w = String(title || '').toLowerCase();
    if (/дух|парфюм|аромат|perfume/.test(w)) return 'perfume';
    if (/камен|камн|талисман|амулет|кристалл/.test(w)) return 'stone';
    if (/кольц|колечк|перстен|серьг|серёж|кулон|брош|браслет|ожерел|колье|подвеск|часы|часики|заколк|гребн|шарф|платок|сумоч|сумк|клатч|рюкзак|ленточк|бусы|медальон|цепочк|обув|туфл|ботильон|сапог|сапожк|ботинк|кроссовк|босоножк|лофер|кед|балетк|шляп|берет|перчатк|очк|ремень|пояс/.test(w)) return 'accessory';
    return 'find';
}
// ===================== 💰 Кошелёк и 🏪 Прилавок лавки =====================
function detectCurrencyForPlace(countryCode, countryName = '', city = '') {
    if (countryCode === 'UK') return '£';
    if (countryCode === 'US') return '$';
    if (countryCode === 'JP') return '¥';
    if (countryCode === 'RU') return '₽';
    const t = `${countryName} ${city}`.toLowerCase();
    if (/коре|сеул/.test(t)) return '₩';
    if (/франц|париж|итал|рим|испан|барселон|герман|берлин|австр|вен|европ/.test(t)) return '€';
    if (/ чехи|праг/.test(t)) return 'крон';
    if (/авторск|фэнтез|королевств|маги|импери/.test(t)) return 'золотых';
    return '$';
}

function currencyScale(cur) {
    if (cur === '₽') return 100;
    if (cur === '¥' || cur === '₩') return 150;
    if (cur === 'золотых') return 0.35;
    if (cur === 'крон') return 25;
    return 1;
}

function roundNicePrice(val, cur) {
    const n = Math.max(1, Math.round(val));
    if (cur === '₽' || cur === '¥' || cur === '₩') {
        return Math.max(50, Math.round(n / 50) * 50);
    }
    return n;
}

function startingBalanceForWealth(wealthStr, cur) {
    const w = String(wealthStr || '').toLowerCase();
    const scale = currencyScale(cur);
    let base = 1200;
    if (/впритык|копит|бедн|скромн/.test(w)) base = 180;
    else if (/обеспечен|богат|ни в чём/.test(w)) base = 7500;
    return roundNicePrice(base * scale, cur);
}

function formatMoney(amount, st) {
    const cur = st?.wallet?.currency || '£';
    const num = Number(amount) || 0;
    const formatted = Math.round(num).toLocaleString('ru-RU');
    return `${formatted} ${cur}`;
}

function parsePriceNumber(priceStr) {
    if (typeof priceStr === 'number') return Math.max(0, priceStr);
    const s = String(priceStr || '').trim();
    if (!s || /бесплат|даром|подарок|^\D*0+(?:[.,]0+)?\D*$/i.test(s)) return 0; // «0», «0 ₸», «£0.00» — бесплатно; «100», «50» — нет
    const cleaned = s.replace(/\s+/g, '').replace(',', '.');
    const m = cleaned.match(/(\d+(?:\.\d+)?)/);
    return m ? Math.max(0, Math.round(Number(m[1]))) : 0;
}

function autoBasePrice(x, st) {
    if (x.buyPrice && x.buyPrice > 0) return x.buyPrice;
    const parsed = parsePriceNumber(x.price);
    if (parsed > 0) return parsed;
    const cur = st?.wallet?.currency || '£';
    const scale = currencyScale(cur);
    const rarBase = { common: 18, rare: 55, epic: 140, legendary: 380 }[x.rarity || 'common'] || 25;
    return roundNicePrice(rarBase * scale, cur);
}

function calcAutoSellPrice(x, st, mult = 1.5) {
    const cur = st?.wallet?.currency || '£';
    const base = autoBasePrice(x, st);
    return roundNicePrice(base * mult, cur);
}

function ensureCounterPrice(x, st) {
    if (!x.buyPrice) x.buyPrice = parsePriceNumber(x.price) || autoBasePrice(x, st);
    if (!x.marginMult) x.marginMult = 1.5;
    if (!x.sellPrice || x.sellPrice <= 0) {
        x.sellPrice = calcAutoSellPrice(x, st, x.marginMult);
    }
}

function shopModeOn(st) {
    return !!st?.direction?.shopMode;
}

function shopCounterItems(st) {
    if (!shopModeOn(st)) return [];
    return (st?.wardrobe?.box || []).filter(x => !!x.onCounter);
}

function personalBoxItems(st) {
    return (st?.wardrobe?.box || []).filter(x => !x.onCounter);
}

// в штрихи годится только личное из шкатулки (не товары на прилавке!)
function wearableBox(st) {
    return personalBoxItems(st);
}
function accentKind(word) {
    const w = String(word || '').toLowerCase();
    if (/дух|парфюм|аромат|perfume/.test(w)) return 'perfume';
    if (/макияж|косметик|помад|блеск для губ|тушь|румян|тени для|стрелк|makeup|lipstick/.test(w)) return 'makeup';
    if (/мелоч|в сумочк|в карман|pocket/.test(w)) return 'pocket';
    if (/камен|камн|талисман|амулет|кристалл|stone/.test(w)) return 'stone';
    return 'accessory';
}
function accentsOn(st) {
    return !!settings().accents && !!st?.direction?.wardrobe;
}
function boxList(st, all = false) {
    return (all ? personalBoxItems(st) : wearableBox(st)).map(x => `${ACCENT_KINDS[x.kind]?.icon || '🎁'} ${x.title}${x.origin ? ` (${x.origin})` : ''}`).join('; ');
}

function buildWardrobeSection(st) {
    if (!st?.wardrobe) return '';
    const w = st.wardrobe;
    const parts = [];
    // Возвращено: без OUTFITDONE наряд остаётся «надетым» навсегда и подсказывается модели в каждом посте
    if (st.direction?.wardrobe) {
        if (w.active?.status === 'worn') {
            const look = w.active.look;
            parts.push(`Wardrobe. {{user}}'s outfit: «${look.title}»${w.active.accent ? ` + ${w.active.accent.title}` : ''}${w.active.occasion ? ` (for: ${w.active.occasion})` : ''}.
OUTFITDONE — if the scene the outfit was chosen for is over or {{user}} has already changed clothes.`);
        } else if (!w.active) {
            const recent = w.history.slice(-3).map(h => h.occasion).filter(Boolean).join('; ');
            parts.push(`Wardrobe. If {{user}}'s outfit matters in the next scene or soon in the plot (a date, a party, a holiday, dinner with family, an important meeting, an interview) and no look has been chosen for it yet — OUTFIT: the occasion in Russian (short, e.g. «ужин у родителей на День благодарения»). Only when the outfit really matters.${recent ? ` Looks were recently chosen for: ${recent}.` : ''}`);
        }
    }
    if ((st.direction?.wardrobe || st.direction?.gacha || accentsOn(st)) && st.direction?.autoBoxItems === true) {
        parts.push(`{{user}}'s keepsake box: ${w.box.length ? boxList(st, true) : '(empty)'}.
Rules: put into ITEM ONLY lasting meaningful things that stayed with {{user}} (jewellery, perfume, accessories, books, keys, letters, artefacts). NEVER food/drinks/rubbish or things already eaten, given away or lost (for those write DROP_ITEM: exact name).
Format: ITEM [духи|аксессуар|украшение|находка]: name in Russian | 1 phrase in Russian | 5–10 words in English, no people | where the item came from (Russian).`);
    }
    return parts.join('\n');
}

function auraInjection(st) {
    const au = st?.direction?.wardrobe && st.wardrobe.aura;
    if (!au) return '';
    const len = ctx().chat?.length ?? 0;
    const alive = st.time.date && au.until ? st.time.date <= au.until : len <= (au.untilMsg || 0);
    if (!alive) return '';
    return `[Talisman: ${storyNames().user} wears ${au.title}${au.desc ? ` — ${au.desc}` : ''}. A faint aura lingers around her${au.effects ? `: ${au.effects}` : ''}. Barely perceptible, on the level of mood and coincidences; nobody speaks of magic directly.]`;
}

// ================= Наряд из гардероба снимается сам, когда он уже не к месту =================
// Где герои сейчас: шапка последнего поста [Location: …] / [Локация: …], иначе текущее место на карте
function nnbCurrentLocationText(st) {
    try {
        const chat = ctx().chat || [];
        for (let i = chat.length - 1; i >= Math.max(0, chat.length - 4); i--) {
            const m = String(chat[i]?.mes || '').match(/\[(?:Location|Локация|Место)\s*:\s*([^\]\n]+?)(?:\.\s*(?:Characters|Персонажи)\s*:[^\]]*)?\]/i);
            if (m) return m[1].trim();
        }
    } catch (e) { /* ignore */ }
    const cur = st?.map?.current;
    return String((cur && (cur.title || cur.name)) || '').trim();
}
function nnbLocationKey(txt) {
    // «Квартира Ани, прихожая» → «квартира ани»: комнату внутри того же места сменой локации не считаем
    return String(txt || '').toLowerCase().replace(/ё/g, 'е').split(/[,.;:(]/)[0].replace(/\s+/g, ' ').trim();
}
const NNB_SWIMWEAR_RE = /купальн|бикини|монокини|плавк|парео|swim|bikini|monokini|trunks|sarong/i;
const NNB_WATER_PLACE_RE = /бассейн|пляж|бан[яеиюь]|терм|саун|парилк|парн|купел|мор[еяю]|озер|рек[аеиу]|спа\b|аквапарк|душ|pool|beach|sauna|bath|onsen|spa\b|lake|sea\b/i;
function nnbOutfitStaleReason(st) {
    const a = st?.wardrobe?.active;
    if (!a || a.status !== 'worn' || !a.look) return '';
    const lookTxt = `${a.look.title || ''} ${a.look.desc || ''} ${a.look.en || ''} ${a.occasion || ''}`;
    const locNow = nnbCurrentLocationText(st);
    if (locNow && NNB_SWIMWEAR_RE.test(lookTxt) && !NNB_WATER_PLACE_RE.test(locNow)) return `купальный наряд, а сейчас «${locNow}»`;
    if (locNow && a.wornPlace && nnbLocationKey(locNow) && nnbLocationKey(a.wornPlace) && nnbLocationKey(locNow) !== nnbLocationKey(a.wornPlace)) {
        return `сменилась локация («${a.wornPlace}» → «${locNow}»)`;
    }
    if (a.date && st.time?.date && a.date !== st.time.date) return 'наступил новый день';
    return '';
}
// Тихо (без запроса к модели) снимает наряд в историю гардероба. Возвращает true, если снял
function nnbAutoRetireStaleOutfit(st) {
    const reason = nnbOutfitStaleReason(st);
    if (!reason) return false;
    const a = st.wardrobe.active;
    const entry = {
        occasion: a.occasion, title: a.look.title, desc: a.look.desc, effects: a.look.effects,
        result: `Образ снят автоматически: ${reason}.`,
        others: [], accent: a.accent ? { kind: a.accent.kind, title: a.accent.title, effects: a.accent.effects || '', origin: a.accent.origin || '' } : null,
        otherAccents: [], image: a.image || '', date: st.time?.date || '', stimuli: 0, auto: true,
    };
    if (!Array.isArray(st.wardrobe.history)) st.wardrobe.history = [];
    st.wardrobe.history.push(entry);
    if (st.wardrobe.history.length > 20) st.wardrobe.history.shift();
    st.wardrobe.active = null;
    try { logImageDiag(`👗 Наряд «${entry.title}» снят автоматически: ${reason}`); } catch (e) { /* ignore */ }
    try { toastr.info(`«${entry.title}» снят: ${reason}. Новый образ можно подобрать в гардеробе.`, '👗 Гардероб'); } catch (e) { /* ignore */ }
    try { ctx().saveMetadata(); } catch (e) { /* ignore */ }
    return true;
}

function wardrobeInjection(st, mode = 'all') {
    if (!st?.direction?.wardrobe) return '';
    const out = [];
    const a = st.wardrobe.active;
    const user = storyNames().user;
    if (a?.status === 'choosing') {
        if (mode !== 'static') {
            out.push(`[${user} is choosing what to wear right now${a.occasion ? ` (${a.occasion})` : ''}. Don't describe what ${user} is wearing — the choice will decide it.]`);
        }
    } else if (a?.status === 'worn') {
        const look = a.look;
        const wornAge = Math.max(0, (ctx().chat?.length ?? 0) - (a.at || 0));
        const acList = Array.isArray(a.selectedAccents) && a.selectedAccents.length ? a.selectedAccents : (a.accent ? [a.accent] : []);
        if (wornAge <= 2) {
            if (mode !== 'static') {
                const effects = look.effects
                    ? `Hidden consequences of this choice (show them once at the meeting, don't repeat in every post): ${look.effects}.`
                    : 'Characters may notice the new outfit at the start of the meeting.';
                let text = `[${user}'s outfit${a.occasion ? ` (${a.occasion})` : ''}: ${String(look.desc || '').replace(/[.\s]+$/, '')}. The outfit has no name — never write a name in quotes. ${effects}`;
                acList.forEach(ac => {
                    const k = ACCENT_KINDS[ac.kind] || ACCENT_KINDS.accessory;
                    text += `\nFinishing touch (${k.name}): «${ac.title}»${ac.desc ? ` — ${String(ac.desc).replace(/[.\s]+$/, '')}` : ''}${ac.origin ? ` (${ac.origin})` : ''}.`;
                    if (ac.effects) text += ` Hidden consequences: ${ac.effects}.`;
                    if (ac.kind === 'perfume') text += ' The scent can only be noticed up close.';
                });
                out.push(text + ']');
            }
        } else if (mode !== 'dynamic') {
            // Название наряда из гардероба — служебное: если его давать в постоянной подсказке, модель вставляет «Название» в каждый пост
            const acDescs = acList.map(ac => String(ac.desc || ac.title || '').replace(/[.\s]+$/, '')).filter(Boolean).join('; ');
            out.push(`[What ${user} is wearing now (reference only, everyone has already seen it): ${String(look.desc || '').replace(/[.\s]+$/, '')}${acDescs ? `; details: ${acDescs}` : ''}. Don't describe ${user}'s clothes again and don't mention them without a direct reason in the scene; the outfit has no name — no names in quotes.]`);
        }
    }
    if (mode === 'static') {
        const equipped = personalBoxItems(st).filter(x => (st.wardrobe.equipped || []).includes(x.id));
        if (equipped.length) {
            out.push(`[${user} has with her: ${equipped.map(x => `«${x.title}»`).join(', ')} — mention only when there is a direct reason.]`);
        }
        return out.join('\n');
    }
    const equipped = mode === 'dynamic' ? [] : personalBoxItems(st).filter(x => (st.wardrobe.equipped || []).includes(x.id));
    if (equipped.length) {
        out.push(`[${user} has with her: ${equipped.map(x => `«${x.title}»`).join(', ')} — mention only when there is a direct reason.]`);
    }
    const counter = shopCounterItems(st);
    if (counter.length) {
        counter.forEach(x => ensureCounterPrice(x, st));
        out.push(`[🏪 ${user}'s shop counter — goods FOR SALE to visitors (${user}'s personal items from her own box are NOT for sale!): ${counter.map(x => `«${x.title}» — price tag: ${formatMoney(x.sellPrice, st)}${x.desc ? ` (${x.desc})` : ''}${x.hook ? ` [the item's story: ${x.hook}]` : ''}`).join('; ')}. Visitors and NPCs may look at these goods, ask about them, haggle and buy them. When a visitor or NPC buys an item from the counter in your reply, add the hidden tag <!--SOLD: exact item name--> at the very end of the reply — the plugin removes the item from the counter and credits the money to ${user}'s wallet.]`);
    }
    if (st.wallet && typeof st.wallet.balance === 'number') {
        out.push(`[💰 ${user}'s wallet: ${formatMoney(st.wallet.balance, st)} now.]`);
    }
    const aura = auraInjection(st);
    if (aura) out.push(aura);
    return out.join('\n');
}

const CLOSET_CATEGORIES = ['Повседневный', 'Рабочий', 'На выход', 'Домашний', 'По погоде', 'Спортивный'];

function normalizeClosetCat(rawCat) {
    const s = String(rawCat || '').toLowerCase();
    if (/рабоч|учеб|офис|делов/.test(s)) return 'Рабочий';
    if (/выход|вечер|свидан|праздн|клуб|ресторан/.test(s)) return 'На выход';
    if (/домаш|уют|пижам|дом/.test(s)) return 'Домашний';
    if (/погод|улич|верхн|пальто|куртк|плащ|зим|осен/.test(s)) return 'По погоде';
    if (/спорт|актив|тренир|прогул|поход/.test(s)) return 'Спортивный';
    return 'Повседневный';
}

function addLookToCloset(st, look, defaultCat = 'Повседневный') {
    if (!st?.wardrobe) return null;
    if (!Array.isArray(st.wardrobe.closet)) st.wardrobe.closet = [];
    if (!st.wardrobe.nextClosetId) st.wardrobe.nextClosetId = 1;
    const title = String(look?.title || '').trim();
    if (!title) return null;
    const existing = st.wardrobe.closet.find(c => c.title.toLowerCase() === title.toLowerCase());
    if (existing) {
        if (look.desc) existing.desc = look.desc;
        if (look.effects) existing.effects = look.effects;
        if (look.en) existing.en = look.en;
        if (look.category) existing.category = normalizeClosetCat(look.category);
        if (look.image) existing.image = look.image;
        if (look.crop) existing.crop = look.crop;
        if (look.imageLayout) existing.imageLayout = look.imageLayout;
        if (look.isSingleImage !== undefined) existing.isSingleImage = !!look.isSingleImage;
        return existing;
    }
    const item = {
        id: st.wardrobe.nextClosetId++,
        category: normalizeClosetCat(look.category || defaultCat),
        title,
        desc: String(look.desc || '').trim(),
        en: String(look.en || '').trim(),
        effects: String(look.effects || '').trim(),
        image: look.image || '',
        crop: look.crop || null,
        imageLayout: look.imageLayout || null,
        isSingleImage: !!look.isSingleImage,
        season: st.time?.date ? season(st.time.date).name : '',
        at: ctx().chat?.length ?? 0,
    };
    st.wardrobe.closet.push(item);
    return item;
}

function lookThumb(item, width = '88px', height = '126px') {
    const el = $('<div class="nnb-card-img nnb-find-thumb"></div>').css({ width, height, 'flex-shrink': '0' });
    const isSingle = !!(item?.isSingleImage || (item?.imageLayout?.cols === 1 && item?.imageLayout?.rows === 1));
    const ratio = isSingle ? (832 / 1216) : (item?.imageLayout?.rows === 2 ? 2 / 3 : 1.5);
    const cropBox = isSingle ? { x: 0, y: 0, w: 1, h: 1 } : (item.crop || { x: 0, y: 0, w: 1, h: 1 });
    applyCrop(el, item.image, cropBox, ratio);
    return el;
}

function getActiveAccents(st) {
    const a = st?.wardrobe?.active;
    if (!a || a.status !== 'worn') return [];
    if (Array.isArray(a.selectedAccents) && a.selectedAccents.length) return a.selectedAccents;
    return a.accent ? [a.accent] : [];
}

async function toggleClosetAccent(st, boxItem) {
    if (!st || !boxItem) return;
    if (!st.wardrobe.active || st.wardrobe.active.status !== 'worn') {
        const first = (st.wardrobe.closet || [])[0] || {
            title: 'Повседневный образ',
            desc: 'Обычная повседневная одежда по сезону',
            category: 'Повседневный',
        };
        st.wardrobe.active = {
            occasion: first.category || 'Повседневный',
            look: { ...first },
            options: [first],
            accents: [],
            selectedAccents: [],
            status: 'worn',
            wornPlace: nnbCurrentLocationText(st),
            at: ctx().chat?.length ?? 0,
            date: st.time?.date || '',
        };
    }
    const a = st.wardrobe.active;
    if (!Array.isArray(a.selectedAccents)) {
        a.selectedAccents = a.accent ? [a.accent] : [];
    }
    const idx = a.selectedAccents.findIndex(x => x.title.toLowerCase() === boxItem.title.toLowerCase());
    if (idx >= 0) {
        a.selectedAccents.splice(idx, 1);
        a.accent = a.selectedAccents[0] || null;
        await commit();
        toastr.info(`Штрих «${escapeHtml(boxItem.title)}» снят`, 'Штрихи к образу', { escapeHtml: false });
        return;
    }
    const entry = {
        id: boxItem.id,
        kind: boxItem.kind === 'find' ? 'accessory' : boxItem.kind,
        title: boxItem.title,
        desc: boxItem.desc || '',
        origin: boxItem.origin || '',
        image: boxItem.image || '',
        crop: boxItem.crop || null,
        imageLayout: boxItem.imageLayout || null,
        isSingleImage: !!boxItem.isSingleImage,
        effects: boxItem.effects || '',
        fromBox: true,
    };
    if (entry.kind === 'perfume') {
        a.selectedAccents = a.selectedAccents.filter(x => x.kind !== 'perfume');
        a.selectedAccents.unshift(entry);
    } else {
        const nonPerfumes = a.selectedAccents.filter(x => x.kind !== 'perfume');
        if (nonPerfumes.length >= 3) {
            const oldest = nonPerfumes[0];
            a.selectedAccents = a.selectedAccents.filter(x => x !== oldest);
        }
        a.selectedAccents.push(entry);
    }
    a.accent = a.selectedAccents[0] || null;
    await commit();
    toastr.success(`Выбран штрих: «${escapeHtml(entry.title)}»`, 'Штрихи к образу', { escapeHtml: false });
}

async function generateStarterAccentsOnly() {
    const st = store();
    if (!st) return;
    const names = storyNames();
    const sName = st.time?.date ? season(st.time.date).name : 'осень';
    await withBusy('Создаём 5 духов и 5 аксессуаров…', async s2 => {
        const prompt = `[OOC: Roleplay paused. Come up with, for ${names.user} (season: ${sName}) 5 perfume options and 5 stylish accessories/jewellery for the wardrobe.
Reply with exactly 10 lines, no explanations (names and descriptions in Russian):
PERF_ITEM: perfume name | description of the scent in 1 sentence | short English description of how the bottle looks (elegant glass perfume bottle...)
(5 PERF_ITEM lines)
ACC_ITEM: accessory name | description of the jewellery, watch, scarf or handbag in 1 sentence | short English description of how the item looks (vintage silver locket...)
(5 ACC_ITEM lines)]`;
        const raw = await quietGenerate(prompt);
        applyWorldCreationResult(s2, s2.worldProfile || {}, raw);
        if (wantImages() && canDrawScene()) {
            await drawWorldStarterVisuals(s2, false);
        }
        await commit();
    });
    toastr.success('5 духов и 5 аксессуаров добавлены в гардероб!', 'Гардероб');
}

function wardrobePrompt(st, occasion, exclude = []) {
    const names = storyNames();
    const t = st.time;
    const when = [t.date ? `${formatDate(t.date)}, ${season(t.date).name}` : '', placeLine(st)].filter(Boolean).join('; ');
    const recent = st.wardrobe.history.slice(-3).map(h => `«${h.title}»`);
    const closetTitles = (st.wardrobe.closet || []).slice(-15).map(c => `«${c.title}»`);
    const avoid = [...new Set([...exclude.map(x => `«${x}»`), ...recent, ...closetTitles])];
    const favs = (st.npcs || []).filter(n => n.favorite).map(n => n.name);
    const images = wantImages();
    const accents = accentsOn(st);
    const rawPersona = ctx().powerUserSettings?.persona_description || ctx().extensionSettings?.persona?.description || '';
    const cleanPersona = rawPersona ? ctx().substituteParams(String(rawPersona)).replace(/\s+/g, ' ').trim().slice(0, 900) : '';
    const customAppEn = st?.wardrobe?.customAppearanceEn ? String(st.wardrobe.customAppearanceEn).trim() : '';
    const worldApp = st?.worldProfile?.appearance ? String(st.worldProfile.appearance).trim() : '';
    const personaContextLine = [
        cleanPersona ? `Description and looks of ${names.user} from the Persona profile: «${cleanPersona}».` : '',
        worldApp ? `Looks from the world card: «${worldApp}».` : '',
        customAppEn ? `Pinned English appearance tags of ${names.user}: «${customAppEn}».` : '',
    ].filter(Boolean).join(' ');

    const lines = [
        '[OOC: Roleplay paused. You are NOT writing a character reply now. You are the author\'s assistant picking an outfit, like in a visual novel. Write all names and descriptions in Russian (EN lines in English).',
        `${names.user} is going to: ${occasion || 'the next scene where the outfit matters (work out from the chat where exactly)'}.`,
        when ? `When and where: ${when}.` : '',
        personaContextLine ? `IMPORTANT — EXACT LOOKS OF ${names.user} (strictly keep her hair colour and length, eye colour, height and build!): ${personaContextLine}` : '',
        favs.length ? `Key favourites in the story: ${favs.join(', ')}.` : '',
        buildDirection(st),
        avoid.length ? `Don't repeat these looks: ${avoid.slice(0, 18).join(', ')}.` : '',
        `Suggest 5 different looks for ${names.user}: from calm and cosy to bold and striking. Take into account the looks and style of ${names.user}, the weather, season, occasion and who will be there.`,
        (Array.isArray(st.trends) && st.trends.length)
            ? `🔥 FASHION AND SEASON TRENDS: trending in the city now: ${st.trends.map(tr => `«${tr.title}» [${tr.category}] (${tr.desc})`).join('; ')}. Make sure that 1–2 of the suggested outfits (LOOK) and at least 1 finishing touch (ACCENT) play on or include the current season trends (mention in the description that it is a season trend, and write in EFFECT the characters' lively reaction depending on their taste and personality)!`
            : '',
        'For each look invent hidden consequences — how specific characters will react to it. The player won\'t see them until the scene is over. Consequences differ between looks: no look pleases everyone and no look pleases no one. Reactions stay in character and in the spirit of the genre.',
    ];
    if (accents) {
        lines.push(`Also suggest 4 finishing touches — perfume, make-up, an accessory (jewellery, handbag, watch, scarf, hairpin etc.) and a small thing in the handbag. ${wearableBox(st).length ? `An item from the keepsake box of ${names.user}: ${boxList(st)} may be used — especially if it fits.` : ''}
— Perfume works in the scene and through memory: the scent is noticed up close, it reminds of something, it may become tied to this evening.
— Make-up — how ${names.user} looks in the face: bold lipstick, light glitter, eyeliner, «almost no make-up». It changes how people look at her in this scene.
— An accessory is a detail that catches the eye and the conversation; a gift worn in front of the giver will surely be noticed.
— A small thing in the handbag is something to take out mid-scene: candies, an old ticket, a notebook, a plaster, a photo, a key. It is a plot hook: somewhere it comes in handy, falls out or raises a question.
The touches have hidden consequences too, different in meaning.`);
    }
    if (images) {
        if (settings().imgPromptWriterNote?.trim()) {
            lines.push(`The author's instruction for the English descriptions for the artist (APPEARANCE and EN): ${settings().imgPromptWriterNote.trim()}`);
        }
        lines.push('First, in one line, describe the heroine\'s exact looks for the artist in English (Danbooru tags for NovelAI):');
        lines.push(`APPEARANCE: the exact looks of ${names.user} from the Persona profile in English — exact hair colour and length (hair color, hair length, hairstyle), exact eye colour (eye color), height, body type and build (body type, figure, breast size, waist, hips), skin tone and notable features (do NOT invent another hair or eye colour!)`);
        lines.push('Then three lines per look, no explanations:');
        lines.push('LOOK: name of the look | what is worn, hairstyle, details — 1–2 sentences');
        lines.push('EN: the same outfit briefly in English, only clothes, shoes and hairstyle (NO facial expression tags, NO blush/shy/embarrassed)');
    } else {
        lines.push('Format — two lines per look, no explanations:');
        lines.push('LOOK: name of the look | what is worn, hairstyle, details — 1–2 sentences');
    }
    lines.push('EFFECT: Name (+): how they will react; Name (−): how they will react');
    if (accents) {
        lines.push(images ? 'Then three lines per touch:' : 'Then two lines per touch:');
        lines.push('ACCENT: духи|макияж|аксессуар|мелочь | name | description in one sentence');
        if (images) lines.push('EN: the same item briefly in English for the artist: for perfume — the bottle (perfume bottle); for make-up — the make-up on the persona\'s face in close-up (e.g.: close-up beauty portrait of face, natural nose and facial proportions, wearing soft warm eyeshadow and wine-tinted lips, glasses); for an accessory — the jewellery or object; for the small thing — a small item');
        lines.push('EFFECT: consequences — who reacts how; for the small thing — when and how it will surface in the scene');
    }
    return lines.filter(Boolean).join('\n') + ']';
}

// ---------- картинка с образами ----------
function imageCommand() {
    const cmds = ctx().SlashCommandParser?.commands;
    if (!cmds) return '';
    return cmds.imagine ? 'imagine' : cmds.sd ? 'sd' : '';
}
function wantImages() {
    const s = settings();
    if (!s.wardrobeImages) return false;
    if (s.imageSource === 'novelai') return true;
    if (s.imageSource === 'openai-images') return !!(s.imgApiBase && s.imgApiKey && s.imgApiModel);
    if (s.imageSource) return !!ctx().ConnectionManagerRequestService?.sendRequest;
    return !!imageCommand();
}
function connectionProfiles() {
    return ctx().extensionSettings?.connectionManager?.profiles || [];
}

// Ищем картинку в ответе модели: data-URL или ссылка на картинку
function extractImage(raw) {
    const text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
    let m = text.match(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/i);
    if (m) return m[0];
    m = text.match(/https?:\/\/[^\s"'()<>\]\\]+?\.(?:png|jpe?g|webp|gif)(?:\?[^\s"'()<>\]\\]*)?/i);
    return m ? m[0] : '';
}

// Декодирование картинок через createImageBitmap(blob), которое работает МГНОВЕННО даже в свёрнутой/фоновой вкладке браузера (в отличие от new Image().onload, который Chrome откладывает до возврата во вкладку!)
async function loadDrawableImageInBackground(srcOrDataUrl) {
    if (!srcOrDataUrl) return null;
    if (typeof createImageBitmap === 'function') {
        try {
            let blob = null;
            if (String(srcOrDataUrl).startsWith('data:')) {
                blob = dataUrlToBlob(srcOrDataUrl);
            } else {
                const res = await fetch(srcOrDataUrl);
                if (res.ok) blob = await res.blob();
            }
            if (blob) {
                const bmp = await createImageBitmap(blob);
                if (bmp) {
                    try {
                        if (!bmp.naturalWidth) bmp.naturalWidth = bmp.width;
                        if (!bmp.naturalHeight) bmp.naturalHeight = bmp.height;
                    } catch (e) { /* readonly in some engines, drawCover uses .naturalWidth || .width */ }
                    return bmp;
                }
            }
        } catch (e) { /* fallback to Image below */ }
    }
    if (typeof Image !== 'function') return null;
    return new Promise(resolve => {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => resolve(img);
        img.onerror = () => resolve(null);
        img.src = srcOrDataUrl;
    });
}

// Сжимаем тяжёлые несжатые PNG (2.5–6 МБ от NovelAI или склейки комиксов) в лёгкий JPEG 92% (~180–260 КБ) без видимой потери качества (работает в фоне через createImageBitmap!)
let imgUploadSeq = 0;
async function compressDataUrlIfHeavy(dataUrl, maxDim = 1536, quality = 0.92) {
    if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/')) return dataUrl;
    if (dataUrl.length < 320000 || typeof document === 'undefined') return dataUrl;
    try {
        const img = await loadDrawableImageInBackground(dataUrl);
        if (!img) return dataUrl;
        let w = img.naturalWidth || img.width || 832;
        let h = img.naturalHeight || img.height || 1216;
        if (w > maxDim || h > maxDim) {
            const scale = maxDim / Math.max(w, h);
            w = Math.max(1, Math.round(w * scale));
            h = Math.max(1, Math.round(h * scale));
        }
        const cv = document.createElement('canvas');
        cv.width = w;
        cv.height = h;
        const g = cv.getContext('2d');
        g.fillStyle = '#ffffff';
        g.fillRect(0, 0, w, h);
        g.drawImage(img, 0, 0, w, h);
        if (typeof img.close === 'function') { try { img.close(); } catch (e) {} }
        const jpgUrl = cv.toDataURL('image/jpeg', quality);
        return (jpgUrl && jpgUrl.startsWith('data:image/jpeg') && jpgUrl.length < dataUrl.length) ? jpgUrl : dataUrl;
    } catch (e) {
        return dataUrl;
    }
}

// Сохраняем картинку на сервер Таверны, чтобы не раздувать файл чата и оперативную память
async function storeImage(url) {
    if (!url || typeof url !== 'string' || !url.startsWith('data:')) return url;
    const compactUrl = await compressDataUrlIfHeavy(url);
    try {
        const [, format, data] = compactUrl.match(/^data:image\/([a-z0-9.+-]+);base64,(.+)$/i) || [];
        if (!data) return compactUrl;
        const ext = format.toLowerCase().replace('jpeg', 'jpg');
        const uniqueName = `nnb_${Date.now()}_${++imgUploadSeq}`;
        const res = await fetch('/api/images/upload', {
            method: 'POST',
            headers: ctx().getRequestHeaders(),
            body: JSON.stringify({ image: data, format: ext, ch_name: 'npc_notebook', filename: uniqueName }),
        });
        if (!res.ok) throw new Error(String(res.status));
        const json = await res.json();
        return json.path || compactUrl;
    } catch (e) {
        console.warn('[npc_notebook] upload', e);
        return compactUrl;
    }
}

// Аватар персоны как образец лица
async function fileToDataUrl(file) {
    if (!file) return '';
    if (file.startsWith('data:')) return file;
    try {
        const res = await fetch(file.startsWith('/') || file.startsWith('http') ? file : '/' + file.split('/').map(encodeURIComponent).join('/'));
        if (!res.ok) return '';
        const blob = await res.blob();
        if (!blob.type.startsWith('image/') || blob.size > 8 * 1024 * 1024) return '';
        return await new Promise(r => { const fr = new FileReader(); fr.onload = () => r(String(fr.result || '')); fr.onerror = () => r(''); fr.readAsDataURL(blob); });
    } catch (e) {
        return '';
    }
}
// Аватары персонажей чата: [{ name, file }]
function characterAvatars() {
    const c = ctx();
    let list = [];
    try {
        if (c.groupId && Array.isArray(c.groups)) {
            const g = c.groups.find(x => x.id === c.groupId);
            list = (g?.members || []).map(av => c.characters.find(ch => ch.avatar === av)).filter(Boolean);
        } else if (c.characterId !== undefined && c.characters?.[c.characterId]) {
            list = [c.characters[c.characterId]];
        }
    } catch (e) { list = []; }
    return list.filter(ch => ch.avatar && ch.avatar !== 'none').map(ch => ({ name: ch.name, file: `characters/${ch.avatar}` }));
}

function getPersonaAvatarPath() {
    try {
        const chat = ctx().chat || [];
        let file = '';
        for (let i = chat.length - 1; i >= 0 && !file; i--) if (chat[i]?.is_user && chat[i].force_avatar) file = chat[i].force_avatar;
        if (!file) {
            const id = $('#user_avatar_block .avatar-container.selected').attr('data-avatar-id') || $('#user_avatar_block .selected').attr('imgfile');
            if (id) file = `User Avatars/${id}`;
        }
        if (!file) return '';
        return (file.startsWith('/') || file.startsWith('http') || file.startsWith('data:'))
            ? file
            : '/' + file.split('/').map(encodeURIComponent).join('/');
    } catch (e) {
        return '';
    }
}

let cachedPersonaAvatarKey = '';
let cachedPersonaAvatarData = '';
async function personaAvatarDataUrl() {
    try {
        const fetchUrl = getPersonaAvatarPath();
        if (!fetchUrl) return '';
        if (fetchUrl.startsWith('data:')) return fetchUrl;
        if (cachedPersonaAvatarKey === fetchUrl && cachedPersonaAvatarData) return cachedPersonaAvatarData;
        const res = await fetch(fetchUrl);
        if (!res.ok) return '';
        const blob = await res.blob();
        if (!blob.type.startsWith('image/') || blob.size > 4 * 1024 * 1024) return '';
        const dUrl = await new Promise(r => { const fr = new FileReader(); fr.onload = () => r(String(fr.result || '')); fr.onerror = () => r(''); fr.readAsDataURL(blob); });
        if (dUrl) {
            cachedPersonaAvatarKey = fetchUrl;
            cachedPersonaAvatarData = dUrl;
        }
        return dUrl;
    } catch (e) {
        return '';
    }
}

// ===== ⏹ Полная остановка: всё, что ждёт ответа, обрывается сразу; запросы с сигналом отменяются и на сервере =====
const NNB_STOP = { rejecters: new Set(), ctrls: new Set(), until: 0, epoch: 0 };
function nnbStopError() { const e = new Error('Остановлено вручную'); e.nnbStopped = true; return e; }
function nnbIsStopError(e) { return !!(e && (e.nnbStopped || e.name === 'AbortError' || /Остановлено вручную/.test(String(e?.message || '')))); }
function nnbStopActive() { return Date.now() < NNB_STOP.until; }
// Сигнал отмены для одного запроса (fetch / профиль Таверны); после ответа вызвать done()
function nnbNewAbort() {
    const ctrl = new AbortController();
    NNB_STOP.ctrls.add(ctrl);
    return { signal: ctrl.signal, ctrl, done: () => NNB_STOP.ctrls.delete(ctrl) };
}
function nnbStopAll() {
    NNB_STOP.until = Date.now() + 2500; // повторы и следующие страницы главы в эти секунды тоже не стартуют
    NNB_STOP.epoch++;
    for (const c of NNB_STOP.ctrls) { try { c.abort(); } catch (e) { /* ignore */ } }
    NNB_STOP.ctrls.clear();
    for (const r of NNB_STOP.rejecters) { try { r(nnbStopError()); } catch (e) { /* ignore */ } }
    NNB_STOP.rejecters.clear();
    // фоновые генерации через основное подключение
    try { ctx().stopGeneration?.(); } catch (e) { /* ignore */ }
    try { if (typeof sceneDrawing !== 'undefined') sceneDrawing = false; } catch (e) { /* ignore */ }
    try { setStatus?.('⏹ Остановлено'); } catch (e) { /* ignore */ }
    try { toastr.info('Все генерации блокнота остановлены', 'Блокнот рассказчика'); } catch (e) { /* ignore */ }
}
function withTimeout(promise, ms, what) {
    if (nnbStopActive()) return Promise.reject(nnbStopError());
    let t;
    let rejStop = null;
    return Promise.race([
        promise,
        new Promise((_, rej) => { t = setTimeout(() => rej(new Error(`${what}: нет ответа ${Math.round(ms / 1000)} сек.`)), ms); }),
        new Promise((_, rej) => { rejStop = rej; NNB_STOP.rejecters.add(rej); }),
    ]).finally(() => { clearTimeout(t); if (rejStop) NNB_STOP.rejecters.delete(rejStop); });
}
function imageSourceName() {
    const id = settings().imageSource;
    if (!id) return 'генерацию картинок Таверны';
    if (id === 'novelai') return `NovelAI (${settings().naiModel || 'nai-diffusion-4-5-full'})`;
    if (id === 'openai-images') return `картинки OpenAI (${settings().imgApiModel})`;
    const p = connectionProfiles().find(x => x.id === id);
    return p ? `профиль «${p.name}»` : 'удалённый профиль';
}

function detectRefusalOrError(raw) {
    if (!raw) return '';
    const t = typeof raw === 'string' ? raw : JSON.stringify(raw);
    if (/safety|content policy|policy violation|violat|censor|inappropriate|nsfw|cannot (fulfill|generate|create)|I am unable to|refuse|sorry|filter/i.test(t)) {
        return t.slice(0, 300);
    }
    if (typeof raw === 'string' && raw.length < 500 && !raw.includes('data:image') && !raw.includes('http')) {
        return raw.trim();
    }
    return '';
}

// refs: { images: [dataUrl…], note: 'что делать с образцами' } или null
async function drawViaProfile(basePrompt, refs, profileId) {
    const svc = ctx().ConnectionManagerRequestService;
    if (!svc?.sendRequest) throw new Error('в этой версии Таверны нет менеджера подключений');
    const prompt = basePrompt + '. Generate this image.';
    const opts = { stream: false, extractData: false, includePreset: false };
    console.log('[npc_notebook] drawViaProfile: start profileId=' + profileId + ', prompt len=' + prompt.length + ', refs=' + (refs?.images?.length || 0));
    let raw = null;
    let refusal = '';
    if (refs?.images?.length) {
        try {
            raw = await withTimeout(svc.sendRequest(profileId, [{ role: 'user', content: [
                { type: 'text', text: prompt + ' ' + refs.note },
                ...refs.images.map(url => ({ type: 'image_url', image_url: { url } })),
            ] }], 8192, opts), 75000, 'рисунок с образцом');
            if (!extractImage(raw)) {
                refusal = detectRefusalOrError(raw);
                console.warn('[npc_notebook] Ref response has no image:', raw);
                raw = null;
            }
        } catch (e) {
            console.warn('[npc_notebook] image with reference failed, retrying without', e);
            refusal = e?.message || '';
            raw = null;
        }
        if (!raw) {
            toastr.info('С образцом лица не вышло — пробую нарисовать без него…', '🎨 Картинка', { timeOut: 4000 });
        }
    }
    if (!raw) {
        console.log('[npc_notebook] drawViaProfile: requesting without reference...');
        raw = await withTimeout(svc.sendRequest(profileId, [{ role: 'user', content: prompt }], 8192, opts), 75000, 'рисунок');
    }
    const url = extractImage(raw);
    if (!url) {
        const refText = detectRefusalOrError(raw) || refusal;
        console.warn('[npc_notebook] Model response has no image:', raw);
        if (refText) throw new Error(`Отказ генератора (фильтр/цензура): «${refText}»`);
        throw new Error('модель ответила без картинки (проверь логи консоли F12)');
    }
    console.log('[npc_notebook] Image extracted successfully');
    return storeImage(url);
}
// ---------- картинки через OpenAI-совместимый адрес /images (gpt-image) ----------
// Браузер может не пустить запрос к чужому сайту (CORS) — тогда пробуем через прокси Таверны.
async function imagesFetch(url, init) {
    try {
        return await fetch(url, init);
    } catch (e) {
        if (e?.name === 'AbortError' || init?.signal?.aborted) throw nnbStopError(); // отменили (⏹ или таймаут) — не идём в прокси
        const viaProxy = '/proxy/' + url;
        // Прокси Таверны — это запрос к самой Таверне: без её CSRF-токена сервер отвечает «Invalid CSRF token»
        let csrf = {};
        try {
            const th = ctx().getRequestHeaders?.() || {};
            const tok = th['X-CSRF-Token'] || th['x-csrf-token'];
            if (tok) csrf = { 'X-CSRF-Token': tok };
        } catch (e2) { /* ignore */ }
        const res = await fetch(viaProxy, { ...init, headers: { ...(init?.headers || {}), ...csrf } }).catch(() => null);
        if (!res || res.status === 404) throw new Error('браузер не пустил запрос к сайту картинок. Включи прокси Таверны: в config.yaml поставь enableCorsProxy: true и перезапусти Таверну');
        return res;
    }
}
function dataUrlToBlob(dataUrl) {
    const [head, b64] = dataUrl.split(',');
    const type = (head.match(/data:([^;]+)/) || [])[1] || 'image/png';
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return new Blob([arr], { type });
}
async function imagesResult(res) {
    const text = await res.text();
    let json = null;
    try { json = JSON.parse(text); } catch (e) { /* не JSON */ }
    if (!res.ok) throw new Error(`сайт картинок ответил ${res.status}: ${String(json?.error?.message || text).slice(0, 200)}`);
    const d = json?.data?.[0];
    if (d?.b64_json) return `data:image/png;base64,${d.b64_json}`;
    if (d?.url) return d.url;
    const any = extractImage(json ?? text);
    if (any) return any;
    throw new Error('сайт картинок ответил без картинки');
}
async function drawViaImagesApi(prompt, refs, size) {
    const s = settings();
    const base = String(s.imgApiBase || '').replace(/\/+$/, '');
    const auth = { Authorization: `Bearer ${s.imgApiKey}` };
    console.log('[npc_notebook] drawViaImagesApi: start model=' + s.imgApiModel + ', base=' + base);
    if (refs?.images?.length) {
        try {
            const fd = new FormData();
            fd.append('model', s.imgApiModel);
            fd.append('prompt', prompt + '. ' + refs.note);
            if (refs.images.length === 1) fd.append('image', dataUrlToBlob(refs.images[0]), 'reference.png');
            else refs.images.forEach((r, i) => fd.append('image[]', dataUrlToBlob(r), `reference${i + 1}.png`));
            fd.append('n', '1');
            if (size) fd.append('size', size);
            const res = await withTimeout(imagesFetch(`${base}/images/edits`, { method: 'POST', headers: auth, body: fd }), 75000, 'рисунок с образцом');
            return storeImage(await imagesResult(res));
        } catch (e) {
            console.warn('[npc_notebook] images/edits failed, retrying without reference', e);
            toastr.info('С образцом лица не вышло — пробую нарисовать без него…', '🎨 Картинка', { timeOut: 4000 });
        }
    }
    const body = { model: s.imgApiModel, prompt, n: 1 };
    if (size) body.size = size;
    const res = await withTimeout(imagesFetch(`${base}/images/generations`, { method: 'POST', headers: { ...auth, 'Content-Type': 'application/json' }, body: JSON.stringify(body) }), 75000, 'рисунок');
    return storeImage(await imagesResult(res));
}

// ---------- картинки через NovelAI (V4.5 / V4 / V3 / V5) ----------
function uint8ToBase64(u8) {
    let binary = '';
    const chunkSize = 0x8000;
    for (let i = 0; i < u8.length; i += chunkSize) {
        binary += String.fromCharCode.apply(null, u8.subarray(i, i + chunkSize));
    }
    return btoa(binary);
}

async function unpackZipFirstFile(u8) {
    const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
    if (u8.byteLength < 30 || dv.getUint32(0, true) !== 0x04034b50) {
        throw new Error('Ответ NovelAI не является ZIP-архивом');
    }
    let compression = dv.getUint16(8, true);
    let crc32 = dv.getUint32(14, true);
    let compSize = dv.getUint32(18, true);
    let uncompSize = dv.getUint32(22, true);
    const nameLen = dv.getUint16(26, true);
    const extraLen = dv.getUint16(28, true);
    const dataStart = 30 + nameLen + extraLen;

    // Если размер в локальном заголовке 0 (потоковый ZIP), читаем точные размеры из Central Directory (PK\x01\x02)
    if (compSize === 0 || uncompSize === 0) {
        for (let i = u8.byteLength - 22; i >= dataStart; i--) {
            if (dv.getUint32(i, true) === 0x02014b50) {
                compression = dv.getUint16(i + 10, true);
                crc32 = dv.getUint32(i + 16, true);
                compSize = dv.getUint32(i + 20, true);
                uncompSize = dv.getUint32(i + 24, true);
                break;
            }
        }
    }
    const compressedSlice = compSize > 0
        ? u8.subarray(dataStart, dataStart + compSize)
        : u8.subarray(dataStart);

    if (compression === 0) {
        return compressedSlice;
    }
    if (compression === 8 && typeof DecompressionStream === 'function') {
        try {
            const ds = new DecompressionStream('deflate-raw');
            const writer = ds.writable.getWriter();
            writer.write(compressedSlice);
            writer.close();
            return new Uint8Array(await new Response(ds.readable).arrayBuffer());
        } catch (e) {
            // Универсальная обёртка в GZIP-конверт (работает во всех браузерах и WebView)
            const gz = new Uint8Array(10 + compressedSlice.byteLength + 8);
            gz.set([0x1f, 0x8b, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03], 0);
            gz.set(compressedSlice, 10);
            const gdv = new DataView(gz.buffer);
            gdv.setUint32(10 + compressedSlice.byteLength, crc32, true);
            gdv.setUint32(10 + compressedSlice.byteLength + 4, uncompSize, true);
            const ds = new DecompressionStream('gzip');
            const writer = ds.writable.getWriter();
            writer.write(gz);
            writer.close();
            return new Uint8Array(await new Response(ds.readable).arrayBuffer());
        }
    }
    throw new Error('Неподдерживаемый метод сжатия ZIP: ' + compression);
}

let naiDirectorRefUnsupportedInSession = false;

function isPermanentAuthOrConfigError(err) {
    const msg = String(err?.message || err || '');
    return /(\b400\b|\b401\s+Unauthorized\b|\b402\b|\b403\b|недостаточно\s+Anlas|заполни\s+адрес\s+API|не\s+выбрано,\s+чем\s+рисовать|\bInvalid\s+API\s+key\b|\bIncorrect\s+API\s+key\b)/i.test(msg);
}

// Защита при общем ключе (когда с одного токена NovelAI или GLM сидят двое):
// автоматически ждёт несколько секунд с небольшим случайным сдвигом (jitter) и повторяет запрос, пока ключ не освободится!
async function withSharedKeyRetry(taskFn, label = 'генерация', maxAttempts = 6, baseDelayMs = 4500) {
    let lastErr = null;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            if (typeof sceneDrawing !== 'undefined' && sceneDrawing) {
                sceneDrawingStartedAt = Date.now();
            }
            return await taskFn(attempt);
        } catch (err) {
            lastErr = err;
            const isHiddenTab = typeof document !== 'undefined' && document.visibilityState === 'hidden';
            if (nnbIsStopError(err) || nnbStopActive() || isPermanentAuthOrConfigError(err) || (!isHiddenTab && attempt >= maxAttempts) || attempt >= maxAttempts + 6) {
                throw err;
            }
            const jitterMs = Math.floor(Math.random() * 1400);
            const waitMs = Math.min(16000, baseDelayMs + (attempt - 1) * 2000 + jitterMs);
            const waitSec = Math.round(waitMs / 100) / 10;
            if (typeof sceneDrawing !== 'undefined' && sceneDrawing) {
                sceneDrawingStartedAt = Date.now();
            }
            logImageDiag(`⏳ Ключ занят / сбой (${label}, попытка ${attempt}/${maxAttempts}) — авто-повтор через ${waitSec} сек.`, err?.message || String(err));
            if (typeof toastr !== 'undefined') {
                toastr.warning(
                    `⏳ Ключ занят или перегружен (${escapeHtml(label)}, повтор ${attempt + 1}/${maxAttempts} через ${waitSec} сек.)…`,
                    '🔄 Очередь ключа',
                    { escapeHtml: false, timeOut: waitMs + 400 }
                );
            }
            const ep = NNB_STOP.epoch;
            await bgSafeSleep(waitMs);
            if (NNB_STOP.epoch !== ep) throw nnbStopError();
            if (typeof sceneDrawing !== 'undefined' && sceneDrawing) {
                sceneDrawingStartedAt = Date.now();
            }
        }
    }
    throw lastErr;
}

async function parseNovelAiResponse(res) {
    if (!res.ok) {
        const errText = await res.text().catch(() => '');
        let msg = errText.slice(0, 220);
        try {
            const j = JSON.parse(errText);
            if (j?.message) msg = j.message;
        } catch (e) { /* ignore */ }
        if (res.status === 401) throw new Error('NovelAI вернул 401 Unauthorized — проверь ключ (Persistent API Token pst-…)');
        if (res.status === 402) throw new Error('NovelAI: недостаточно Anlas или неактивна подписка (402)');
        throw new Error(`NovelAI ответил ${res.status}: ${msg}`);
    }
    const buf = await res.arrayBuffer();
    const u8 = new Uint8Array(buf);
    if (!u8.byteLength) throw new Error('NovelAI вернул пустой ответ');

    // 1. ZIP archive (PK\x03\x04)
    if (u8.byteLength >= 4 && u8[0] === 0x50 && u8[1] === 0x4b && u8[2] === 0x03 && u8[3] === 0x04) {
        const pngBytes = await unpackZipFirstFile(u8);
        return `data:image/png;base64,${uint8ToBase64(pngBytes)}`;
    }
    // 2. Raw PNG (\x89PNG)
    if (u8.byteLength >= 4 && u8[0] === 0x89 && u8[1] === 0x50 && u8[2] === 0x4e && u8[3] === 0x47) {
        return `data:image/png;base64,${uint8ToBase64(u8)}`;
    }
    // 3. Base64 text or JSON (например от встроенного эндпоинта Таверны /api/novelai/generate-image)
    const text = new TextDecoder('utf-8').decode(u8).trim();
    if (text.startsWith('data:image/')) return text;
    if (/^[A-Za-z0-9+/=\r\n]+$/.test(text) && text.length > 200) {
        return `data:image/png;base64,${text.replace(/\s+/g, '')}`;
    }
    try {
        const json = JSON.parse(text);
        if (typeof json === 'string' && json.length > 200) {
            return json.startsWith('data:') ? json : `data:image/png;base64,${json}`;
        }
        const extracted = extractImage(json);
        if (extracted) return extracted;
    } catch (e) { /* ignore */ }
    throw new Error('Не удалось распознать картинку в ответе NovelAI');
}

// Приводит картинку-референс к формату холста NovelAI Director Reference (1024x1536 с чёрными полями, чистый base64 PNG)
async function formatRefForNovelAiDirector(dataUrl) {
    if (!dataUrl || typeof document === 'undefined') return '';
    try {
        const img = await loadDrawableImageInBackground(dataUrl);
        if (!img) {
            const m = String(dataUrl).match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/i);
            return m ? m[1] : '';
        }
        const W = 1024, H = 1536;
        const iw = img.naturalWidth || img.width || W;
        const ih = img.naturalHeight || img.height || H;
        const cv = document.createElement('canvas');
        cv.width = W;
        cv.height = H;
        const g = cv.getContext('2d');
        g.fillStyle = '#000000';
        g.fillRect(0, 0, W, H);
        const scale = Math.min(W / (iw || 1), H / (ih || 1));
        const dw = Math.round(iw * scale);
        const dh = Math.round(ih * scale);
        const dx = Math.floor((W - dw) / 2);
        const dy = Math.floor((H - dh) / 2);
        g.drawImage(img, dx, dy, dw, dh);
        if (typeof img.close === 'function') { try { img.close(); } catch (e) {} }
        const outDataUrl = cv.toDataURL('image/png');
        const m = outDataUrl.match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/i);
        return m ? m[1] : '';
    } catch (e) {
        const m = String(dataUrl).match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/i);
        return m ? m[1] : '';
    }
}


// --- Диагностика генерации картинок и очистка промпта NovelAI ---
const imageDiagHistory = [];
let sceneDrawingStartedAt = 0;

function logImageDiag(step, detail = '') {
    const now = new Date();
    const ts = now.toTimeString().slice(0, 8);
    const entry = `[${ts}] ${step}${detail ? ': ' + String(detail).slice(0, 600) : ''}`;
    imageDiagHistory.push(entry);
    if (imageDiagHistory.length > 60) imageDiagHistory.shift();
    console.log('[npc_notebook][img-diag]', entry);
}

function showImageDiagPopup() {
    const el = $('<div class="nnb-pop"><h3>📋 Диагностика и лог генерации картинок</h3></div>');
    el.append('<div class="nnb-pop-sub" style="margin-bottom:8px;">Здесь записывается каждый шаг последней генерации иллюстрации: запрос к модели промптов (GLM), отделение негативного промпта, отправка в NovelAI и точный текст ошибки, если что-то зависло или не сработало.</div>');
    const logText = imageDiagHistory.length
        ? imageDiagHistory.join('\n\n')
        : 'Пока нет записей за эту сессию. Нажми 🎬 на любом сообщении в чате, чтобы нарисовать сцену.';
    const area = $('<textarea class="text_pole" rows="14" readonly style="width:100%; font-family:monospace; font-size:0.82em; white-space:pre-wrap;"></textarea>').val(logText);
    el.append(area);
    const btnRow = $('<div class="nnb-pop-row" style="margin-top:8px; gap:8px; flex-wrap:wrap;"></div>');
    btnRow.append($('<div class="menu_button"><i class="fa-solid fa-rotate-left"></i> Сбросить зависшую генерацию</div>').on('click', () => {
        sceneDrawing = false;
        sceneDrawingStartedAt = 0;
        logImageDiag('Ручной сброс флага генерации пользователем');
        toastr.success('Флаг генерации сброшен — можно снова нажимать 🎬!', '🎬 Сцена');
        area.val(imageDiagHistory.join('\n\n'));
    }));
    btnRow.append($('<div class="menu_button"><i class="fa-solid fa-trash"></i> Очистить лог</div>').on('click', () => {
        imageDiagHistory.length = 0;
        area.val('Лог очищен.');
    }));
    el.append(btnRow);
    openPopup(el, true);
}

// Отделяет "| NEGATIVE: ..." / "NEGATIVE: ..." / "UC: ..." от позитивного промпта, чтобы негатив НЕ попадал в позитив!
function splitPositiveAndNegativePrompt(rawText) {
    let text = String(rawText || '').trim();
    const extraNegParts = [];

    // Ищем конструкцию вида "| NEGATIVE: ...", "| Negative: ...", "| UC: ...", "NEGATIVE: ...", "Undesired Content: ..."
    const negRegex = /(?:\s*\|\s*|\s+—\s+|\n+\s*|\[\s*)(?:NEGATIVE(?:\s+PROMPT)?|UNDESIRED(?:\s+CONTENT)?|UC)\s*[:：—–-]\s*([\s\S]+)$/i;
    const m = text.match(negRegex);
    if (m) {
        const negTail = m[1].replace(/\]\s*$/, '').trim();
        if (negTail) extraNegParts.push(negTail);
        text = text.slice(0, m.index).trim();
    }

    // Убираем висящие вертикальные черты в конце позитивного промпта (в NovelAI символ | включает смешивание промптов!)
    text = text.replace(/\s*\|+\s*$/g, '').trim();

    return {
        positive: text,
        negative: extraNegParts.join(', '),
    };
}

// Исправляет ловушки тегов Danbooru/NovelAI в позитивном промпте:
// 1) "flat male chest" / "male chest" при наличии кардигана/одежды заставляет NovelAI рисовать голую грудь нараспашку;
// 2) "no breasts" в позитивном промпте активирует токен "breasts" (отрицания с "no ..." должны быть в негативе!).
function sanitizeNovelAiPositiveAndNegative(posPrompt, negPrompt) {
    let pos = String(posPrompt || '').trim();
    let neg = String(negPrompt || '').trim();

    // Вырезаем если вдруг внутри промпта остался "| NEGATIVE: ..."
    const split = splitPositiveAndNegativePrompt(pos);
    pos = split.positive;
    if (split.negative) {
        neg = [neg, split.negative].filter(Boolean).join(', ');
    }

    const isExplicitlyShirtless = /\b(shirtless|bare chest|bare torso|topless|naked torso|unbuttoned|open shirt|open cardigan showing chest)\b/i.test(pos);
    const hasUpperClothes = /\b(cardigan|sweater|jacket|coat|hoodie|shirt|t-shirt|turtleneck|vest|blazer|suit|uniform)\b/i.test(pos);

    if (!isExplicitlyShirtless && hasUpperClothes) {
        // В Danbooru "flat male chest" / "male chest" = оголённая мужская грудь! Заменяем на безопасное описание мужской фигуры
        pos = pos.replace(/\bflat\s+male\s+chest\b/gi, 'masculine upper body');
        pos = pos.replace(/\bmale\s+chest\b/gi, 'masculine torso');
        // Если на персонаже кардиган (cardigan), но не упомянута футболка/рубашка под ним — добавляем shirt under cardigan, чтобы кардиган не рисовался на голое тело
        if (/\bcardigan\b/i.test(pos) && !/\b(shirt|t-shirt|tee|turtleneck|sweater|blouse|top|under\s+cardigan)\b/i.test(pos)) {
            pos = pos.replace(/\b([a-z]+\s+cardigan|cardigan)\b/i, '$1 over plain shirt, closed front');
        }
    }


    // Убираем "no breasts" / "no female chest" из позитивного промпта (в позитиве NovelAI читает само слово после "no")
    if (/\bno\s+(?:breasts|female\s+chest|chest)\b/i.test(pos)) {
        pos = pos.replace(/,?\s*\bno\s+(?:breasts|female\s+chest|chest)\b/gi, '');
        if (!/\bbreasts\b/i.test(neg)) {
            neg = `breasts, female chest, ${neg}`;
        }
    }

    const userStyle = String(settings().naiPrefix || '').trim();
    if (userStyle) {
        pos = pos.replace(/\b(?:anime\s+style|semi-realistic\s+anime|masterpiece|best\s+quality|very\s+aesthetic|amazing\s+quality|highres)\b\s*,?\s*/gi, '');
    }

    pos = pos.replace(/,\s*,+/g, ', ').replace(/^\s*,\s*|\s*,\s*$/g, '').trim();
    return { pos, neg };
}

async function drawViaNovelAi(prompt, orient = 'portrait', refs = null) {
    const s = settings();
    const model = String(s.naiModel || 'nai-diffusion-5-full-medium').trim();
    const isV5Medium = /nai-diffusion-5-full-medium/i.test(model);
    const isV5 = /nai-diffusion-5/i.test(model);
    const isV4Plus = /nai-diffusion-[45]/i.test(model);

    // По умолчанию используем выбранное пользователем количество шагов (по умолч. 26)
    const sampler = String(s.naiSampler || 'k_euler_ancestral').trim();
    const scheduler = String(s.naiScheduler || 'karras').trim();
    const steps = Math.max(1, Math.min(50, Number(s.naiSteps) || 26));
    const scale = Math.max(1, Math.min(20, Number(s.naiScale) || 5.0));
    const cfgRescale = Math.max(0, Math.min(1, Number(s.naiRescale ?? 0)));

    // Пользовательский стиль вставляется 1-в-1 без изменений текстовой моделью!
    const prefix = String(s.naiPrefix ?? '').trim();
    let baseNeg = String(s.naiNegative ?? defaults.naiNegative).trim();
    if (refs?.extraNeg) {
        baseNeg = [baseNeg, refs.extraNeg].filter(Boolean).join(', ');
    }
    const sanitized = sanitizeNovelAiPositiveAndNegative(prompt, baseNeg);
    let negPrompt = sanitized.neg;
    const cleanPrompt = sanitized.pos.replace(/\s+/g, ' ').trim();
    if (/NOT looking at viewer/i.test(cleanPrompt) && !/looking at viewer/i.test(negPrompt)) {
        negPrompt = `looking at viewer, looking at camera, eye contact with viewer, ${negPrompt}`;
    }

    // Стандартные разрешения Opus Free (832x1216)
    let width = 832, height = 1216;
    if (orient === 'landscape') { width = 1216; height = 832; }
    else if (orient === 'square') { width = 1024; height = 1024; }

    const isStrictMonochrome = /\bmonochrome\b/i.test(cleanPrompt) && !/\bspot\s+color\b/i.test(cleanPrompt);
    const effectivePrefix = isStrictMonochrome ? enforceMonochromeMangaPrompt(prefix, false) : prefix;
    if (isStrictMonochrome && !/color,\s*colorful/i.test(negPrompt)) {
        negPrompt = `color, colorful, full color, chromatic, pastel colors, saturated colors, colorized, spot color, yellow, orange, pink, red, blue, green, purple, brown, blonde, watercolor, ${negPrompt}`;
    }
    const fullPrompt = [effectivePrefix, isStrictMonochrome ? enforceMonochromeMangaPrompt(cleanPrompt, true) : cleanPrompt].filter(Boolean).join(', ');
    logImageDiag(`Запуск NovelAI (${model}, steps=${steps}, scale=${scale}, rescale=${cfgRescale}, ${width}x${height})`, `ПОЗИТИВ: ${fullPrompt}\nНЕГАТИВ: ${negPrompt}`);
    const seed = Math.floor(Math.random() * 4294967295);

    const token = String(s.naiApiKey || '').trim();

    // Если указан ключ pst-... в настройках плагина — идём напрямую (или через /proxy/) к image.novelai.net
    if (token) {
        const params = {
            params_version: isV5 ? 4 : 3,
            width,
            height,
            scale,
            sampler,
            steps,
            seed,
            n_samples: 1,
            ucPreset: isV5Medium ? 2 : 0,
            qualityToggle: !prefix,
            sm: false,
            sm_dyn: false,
            dynamic_thresholding: false,
            controlnet_strength: 1,
            legacy: false,
            add_original_image: true,
            cfg_rescale: cfgRescale,
            noise_schedule: scheduler,
            legacy_v3_extend: false,
            uncond_scale: 1,
            negative_prompt: negPrompt,
            prompt: fullPrompt,
            reference_image_multiple: [],
            reference_information_extracted_multiple: [],
            reference_strength_multiple: [],
            extra_noise_seed: seed,
        };
        if (isV4Plus) {
            const rawCharCaps = Array.isArray(refs?.charCaptions) ? refs.charCaptions.filter(Boolean).slice(0, 6) : [];
            const centersForCount = cnt => {
                if (cnt === 2) return [{ x: 0.3, y: 0.5 }, { x: 0.7, y: 0.5 }];
                if (cnt === 3) return [{ x: 0.2, y: 0.5 }, { x: 0.5, y: 0.5 }, { x: 0.8, y: 0.5 }];
                if (cnt === 4) return [{ x: 0.2, y: 0.45 }, { x: 0.4, y: 0.55 }, { x: 0.6, y: 0.45 }, { x: 0.8, y: 0.55 }];
                return rawCharCaps.map((_, idx) => ({ x: Number(((idx + 1) / (cnt + 1)).toFixed(2)), y: 0.5 }));
            };
            const centers = centersForCount(rawCharCaps.length);
            const builtCharCaptions = rawCharCaps.length >= 2
                ? rawCharCaps.map((cc, idx) => {
                    const cleanCc = sanitizeNovelAiPositiveAndNegative(cc, '').pos;
                    return {
                        char_caption: isStrictMonochrome ? enforceMonochromeMangaPrompt(cleanCc, false) : cleanCc,
                        centers: [centers[idx] || { x: 0.5, y: 0.5 }],
                    };
                })
                : [];
            const builtNegCharCaptions = builtCharCaptions.map(cObj => ({
                char_caption: 'lowres, bad anatomy, bad hands, merged bodies, fused limbs',
                centers: cObj.centers,
            })).map(cObj => isStrictMonochrome ? { ...cObj, char_caption: `color, colorful, full color, yellow, orange, pink, red, blue, green, brown, blonde, ${cObj.char_caption}` } : cObj);
            if (builtCharCaptions.length) {
                logImageDiag(`NovelAI V4/V5 Multi-Character слоты (${builtCharCaptions.length} перс.)`, builtCharCaptions.map((c, i) => `CHAR${i + 1}: ${c.char_caption}`).join(' | '));
            }
            params.v4_prompt = {
                use_coords: builtCharCaptions.length >= 2,
                use_order: true,
                caption: { base_caption: fullPrompt, char_captions: builtCharCaptions },
            };
            params.v4_negative_prompt = {
                use_coords: builtNegCharCaptions.length >= 2,
                use_order: false,
                caption: { base_caption: negPrompt, char_captions: builtNegCharCaptions },
            };
        }

        // Прикрепляем картинку-референс внешности в NovelAI (в ч/б манга-режиме цветную аватарку НЕ прикрепляем, чтобы NovelAI не копировал с неё цвета!)
        const refMode = String(s.naiCharRefMode || 'char_no_style');
        const hasRefs = Array.isArray(refs?.images) && refs.images.length > 0;
        const allowRef = refMode !== 'off' && !isStrictMonochrome && !naiDirectorRefUnsupportedInSession;
        let attachedRef = false;
        if (hasRefs && allowRef) {
            const b64 = await formatRefForNovelAiDirector(refs.images[0]);
            if (b64) {
                if (/nai-diffusion-4-5/i.test(model)) {
                    // В NovelAI Director Reference:
                    // base_caption: 'character' = ТОЛЬКО персонаж БЕЗ стиля аватарки (Style Aware ВЫКЛ);
                    // base_caption: 'character&style' = Персонаж + стиль аватарки (Style Aware ВКЛ);
                    // base_caption: 'style' = ТОЛЬКО стиль аватарки.
                    // secondary_strength_values = (1 - Fidelity): при 0.55..0.65 не копирует рисовку и пропорции с аватарки!
                    const isCharAndStyle = refMode === 'char_and_style';
                    const isStyleOnly = refMode === 'style_only';
                    const baseCap = isStyleOnly ? 'style' : (isCharAndStyle ? 'character&style' : 'character');
                    const secStrength = (isCharAndStyle || isStyleOnly) ? 0.2 : 0.55;
                    params.director_reference_images = [b64];
                    params.director_reference_descriptions = [
                        { caption: { base_caption: baseCap, char_captions: [] }, legacy_uc: false },
                    ];
                    params.director_reference_information_extracted = [1];
                    params.director_reference_strength_values = [isStyleOnly ? 0.85 : 0.85];
                    params.director_reference_secondary_strength_values = [secStrength];
                    attachedRef = true;
                    logImageDiag('NovelAI Character Reference прикреплён', `режим=${baseCap}, secondary_strength=${secStrength}`);
                } else if (!isV4Plus) {
                    params.reference_image_multiple = [b64];
                    params.reference_information_extracted_multiple = [1];
                    params.reference_strength_multiple = [0.6];
                    attachedRef = true;
                    logImageDiag('NovelAI V3 Reference прикреплён');
                } else {
                    logImageDiag('Модель NovelAI V5: референс передан подробным текстовым описанием внешности в промпте');
                }
            }
        }

        const sendNaiDirect = async pObj => {
            return await withSharedKeyRetry(async () => {
                const newSeed = Math.floor(Math.random() * 4294967295);
                pObj.seed = newSeed;
                pObj.extra_noise_seed = newSeed;
                const body = {
                    input: fullPrompt,
                    model,
                    action: 'generate',
                    parameters: pObj,
                };
                const abN = nnbNewAbort();
                const res = await withTimeout(
                    imagesFetch('https://image.novelai.net/ai/generate-image', {
                        signal: abN.signal,
                        method: 'POST',
                        headers: {
                            Authorization: `Bearer ${token}`,
                            'Content-Type': 'application/json',
                            Accept: '*/*',
                        },
                        body: JSON.stringify(body),
                    }),
                    90000,
                    'NovelAI рисунок'
                ).catch(e => { try { abN.ctrl.abort(); } catch (x) { /* ignore */ } throw e; }).finally(() => abN.done());
                return await parseNovelAiResponse(res);
            }, 'NovelAI кадр', 2, 3500);
        };

        try {
            const dataUrl = await sendNaiDirect(params);
            return storeImage(dataUrl);
        } catch (err) {
            if (isV5Medium && (params.steps !== 14 || params.negative_prompt)) {
                console.warn('[npc_notebook] V5 Medium rejected custom steps/negative, retrying with V5 Medium fallback:', err);
                logImageDiag(`Повтор V5 Medium: пробуем с совместимыми параметрами (err: ${err?.message || err})`);
                params.steps = 14;
                params.sampler = 'k_euler_ancestral';
                params.cfg_rescale = 0;
                const dataUrl = await sendNaiDirect(params);
                return storeImage(dataUrl);
            }
            if (attachedRef) {
                naiDirectorRefUnsupportedInSession = true;
                console.warn('[npc_notebook] NovelAI Character Reference failed (e.g. 400/402), disabling binary ref for session and retrying with text tags:', err);
                logImageDiag('NovelAI Character Reference отклонён сервером — переключаемся на быстрые текстовые теги внешности без повторных сбоев');
                delete params.director_reference_images;
                delete params.director_reference_descriptions;
                delete params.director_reference_information_extracted;
                delete params.director_reference_strength_values;
                delete params.director_reference_secondary_strength_values;
                params.reference_image_multiple = [];
                params.reference_information_extracted_multiple = [];
                params.reference_strength_multiple = [];
                const dataUrl = await sendNaiDirect(params);
                return storeImage(dataUrl);
            }
            throw err;
        }
    }

    // Если поле ключа пустое — пробуем встроенный эндпоинт SillyTavern /api/novelai/generate-image (ключ из Таверны) с авто-повтором при занятом ключе
    const dataUrl = await withSharedKeyRetry(async () => {
        const stRes = await withTimeout(
            fetch('/api/novelai/generate-image', {
                method: 'POST',
                headers: ctx().getRequestHeaders(),
                body: JSON.stringify({
                    prompt: fullPrompt,
                    model,
                    sampler,
                    scheduler,
                    steps,
                    scale,
                    width,
                    height,
                    negative_prompt: negPrompt,
                    seed: Math.floor(Math.random() * 4294967295),
                    n_samples: 1,
                }),
            }),
            90000,
            'NovelAI через Таверну'
        );
        return await parseNovelAiResponse(stRes);
    }, 'NovelAI через Таверну', 6, 4500);
    return storeImage(dataUrl);
}

function cleanForCommand(t) {
    if (settings().imageSource === 'novelai') {
        return String(t || '').replace(/[\n\r]+/g, ' ').replace(/\s+/g, ' ').trim();
    }
    return String(t || '').replace(/[|{}\n\r]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function imgOrient() {
    return settings().imgOrientation === 'landscape' ? 'landscape' : 'portrait';
}
function looksLayout(n) {
    if (n >= 5) return { rows: 1, cols: 5 };
    return imgOrient() === 'portrait' && n > 2 ? { rows: 2, cols: 2 } : { rows: 1, cols: n };
}
function sheetPrompt(a, layout) {
    const maxN = layout?.rows === 2 ? 4 : Math.min(a.options.length, 5);
    const looks = a.options.slice(0, maxN);
    const who = a.appearance || 'young woman';
    const common = 'full body, standing, plain light background, the same face, hair and body in every figure, evenly spaced, not overlapping';
    if (layout?.rows === 2) {
        const pos = ['top-left', 'top-right', 'bottom-left', 'bottom-right'];
        return cleanForCommand(`character outfit sheet arranged as a 2 by 2 grid of equal cells, the same ${who} shown ${looks.length} times, each figure centered in its own cell, ${common}, ` +
            looks.map((o, i) => `${pos[i]} cell wearing ${o.en || o.title}`).join('; ') + ', no text, no captions');
    }
    const pos = ['first', 'second', 'third', 'fourth', 'fifth'];
    return cleanForCommand(`character outfit sheet, the same ${who} shown ${looks.length} times side by side in a single row, each figure centered in its own equal column of the image, ${common}, ` +
        looks.map((o, i) => `${pos[i]} from the left wearing ${o.en || o.title}`).join('; ') + ', no text, no captions');
}

// Состояние рисования: отдельно для образов и для штрихов
const drawingKind = { looks: false, accents: false, gacha: false };
const drawWaitersOf = { looks: new Set(), accents: new Set(), gacha: new Set() };
const PIC_FIELDS = { looks: ['image', 'imageFailed'], accents: ['accentImage', 'accentImageFailed'], gacha: ['image', 'imageFailed'] };
const activeOf = (kind, st = store()) => (kind === 'gacha' ? st?.gacha?.active : st?.wardrobe?.active);

// orient: 'portrait' | 'landscape' — размер для сайта картинок и подсказка в тексте для остальных
async function drawPicture(prompt, refs, orient = 'landscape') {
    const src = settings().imageSource;
    if (src === 'novelai') return drawViaNovelAi(prompt, orient, refs);
    const size = orient === 'portrait' ? '1024x1536' : orient === 'square' ? '1024x1024' : '1536x1024';
    if (src === 'openai-images') return drawViaImagesApi(prompt, refs, size);
    prompt = `${prompt}, ${orient === 'portrait' ? 'vertical portrait image, 2:3' : orient === 'square' ? 'square image, 1:1' : 'wide landscape image, 3:2'}`;
    if (src) return drawViaProfile(prompt, refs, src);
    const c = ctx();
    const cmd = imageCommand();
    if (!cmd) throw new Error('генерация картинок не подключена');
    const run = c.executeSlashCommandsWithOptions || c.executeSlashCommands;
    if (typeof run !== 'function') throw new Error('эта версия Таверны не умеет запускать команды из расширений');
    console.log('[npc_notebook] executing slash command: /' + cmd);
    const r = await withTimeout(Promise.resolve(run(`/${cmd} quiet=true ${prompt}`)), 75000, 'генерация картинок');
    const url = String(typeof r === 'string' ? r : (r?.pipe ?? '')).trim();
    if (!url || /\s/.test(url)) {
        if (url && (url.toLowerCase().includes('error') || url.toLowerCase().includes('fail') || url.toLowerCase().includes('censor'))) {
            throw new Error(`генератор вернул ошибку: ${url}`);
        }
        throw new Error('генератор не вернул картинку');
    }
    return url;
}

// предметы рисуем в том же духе, что и образы: иллюстрация, а не фото
const ITEM_STYLE = 'semi-realistic anime illustration, soft painterly digital art, clean outlines, warm gentle colors, visual novel item art, not a photo';

function accentsLayout(n) {
    return n >= 4 ? { rows: 2, cols: 2 } : { rows: 1, cols: n };
}

function cleanMakeupEn(en, x, who) {
    const raw = String(en || '').trim();
    const person = who || 'beautiful young woman';
    let details = raw;
    if (!details || details.length < 5) {
        details = x?.desc || 'subtle elegant makeup';
    }
    return `close-up beauty portrait of ${person}, complete face with natural proportions, well-defined nose, eyes and lips, wearing ${details}, soft studio lighting, looking towards camera`;
}

function accentEnDesc(x, who) {
    let en = String(x.en || x.title || '').trim();
    if (x.kind === 'makeup' || /макияж|makeup|lipstick|тени|помад/i.test(x.kind || x.title)) {
        return cleanMakeupEn(en, x, who);
    }
    return en;
}

function accentsPrompt(a, layout) {
    const items = (a.accents || []).slice(0, 4);
    const L = layout || accentsLayout(items.length);
    const who = a.appearance || 'young woman';
    if (L.rows === 2) {
        const pos = ['top-left cell', 'top-right cell', 'bottom-left cell', 'bottom-right cell'];
        return cleanForCommand(`${ITEM_STYLE}, sheet arranged as a 2 by 2 grid of 4 equal cells, each cell with its own isolated item or portrait, solid plain light cream background, ` +
            items.map((x, i) => `${pos[i]}: ${accentEnDesc(x, who)}`).join('; ') + ', no text, no captions');
    }
    const pos = ['first', 'second', 'third', 'fourth'];
    return cleanForCommand(`${ITEM_STYLE}, ${items.length} separate elements in a row, wide spacing, each element small and centered with wide empty space around it, solid plain light cream background, ` +
        items.map((x, i) => `${pos[i]} from the left: ${accentEnDesc(x, who)}`).join('; ') + ', no text, no captions');
}



function getHeroineAppearanceEn(st, activeWardrobe = null) {
    const fromCustom = st?.wardrobe?.customAppearanceEn ? String(st.wardrobe.customAppearanceEn).trim() : '';
    if (fromCustom) return fromCustom;
    const fromActive = activeWardrobe?.appearance ? String(activeWardrobe.appearance).trim() : '';
    const fromStore = st?.wardrobe?.appearance ? String(st.wardrobe.appearance).trim() : '';
    const rawPersona = ctx().powerUserSettings?.persona_description || ctx().extensionSettings?.persona?.description || '';
    const fromPersona = rawPersona ? ctx().substituteParams(String(rawPersona)).replace(/\s+/g, ' ').trim().slice(0, 450) : '';
    // Если в анкете Персоны уже есть английские слова/теги, а в гардеробе пусто — берём их
    return fromActive || fromStore || (/[a-zA-Z]{4,}/.test(fromPersona) ? fromPersona : '') || 'adult woman, natural proportions';
}

async function ensureHeroineAppearanceEnForNai(st, activeWardrobe = null) {
    const custom = st?.wardrobe?.customAppearanceEn ? String(st.wardrobe.customAppearanceEn).trim() : '';
    if (custom) return custom;
    const rawPersona = ctx().powerUserSettings?.persona_description || ctx().extensionSettings?.persona?.description || '';
    const cleanPersona = rawPersona ? ctx().substituteParams(String(rawPersona)).replace(/\s+/g, ' ').trim().slice(0, 800) : '';
    const worldApp = st?.worldProfile?.appearance ? String(st.worldProfile.appearance).trim() : '';
    const sourceText = [cleanPersona, worldApp].filter(Boolean).join('; ');
    // Если есть описание Персоны на русском, а закреплённых английских тегов ещё нет — один раз переводим внешность Персоны в точные теги Danbooru для NovelAI!
    if (sourceText && /[а-яА-ЯёЁ]/.test(sourceText)) {
        try {
            const trPrompt = `[OOC: Extract ONLY the physical appearance from the character description (sex, age adult, exact hair colour and length, hairstyle, eye colour, height, body type, breast size, waist/hips, skin tone, glasses/moles/distinctive marks) and turn it into short exact English Danbooru tags, comma-separated, for NovelAI. Do NOT write personality, biography or clothes. Output ONLY one line of English tags, no intro:\n«${sourceText}»]`;
            const rawEn = await quietGenerateImagePrompt(trPrompt);
            const cleanedEn = String(rawEn || '').replace(/^APPEARANCE\s*[:：—–-]\s*/i, '').replace(/[\r\n]+/g, ', ').trim();
            if (cleanedEn && /[a-zA-Z]{3,}/.test(cleanedEn)) {
                if (st?.wardrobe) {
                    st.wardrobe.customAppearanceEn = cleanedEn;
                    st.wardrobe.appearance = cleanedEn;
                }
                if (activeWardrobe) activeWardrobe.appearance = cleanedEn;
                await ctx().saveMetadata();
                return cleanedEn;
            }
        } catch (e) {
            console.warn('[npc_notebook] auto translate persona appearance error:', e);
        }
    }
    return getHeroineAppearanceEn(st, activeWardrobe);
}

function buildSingleOutfitPromptForNai(who, outfitObj) {
    // Убираем случайные теги смущения/румянца (blush, shy, embarrassed, flustered), которые модель или NovelAI часто лепят на примерке одежды
    const stripBlush = s => String(s || '')
        .replace(/\b(?:full-face\s+blush|deep\s+blush|heavy\s+blush|light\s+blush|blushing|blush|embarrassed|flustered|shy\s+smile|shy\s+expression|shy|timid)\b\s*,?\s*/gi, '')
        .replace(/,\s*,+/g, ', ')
        .trim();
    const outfitText = stripBlush(outfitObj?.en || outfitObj?.desc || outfitObj?.title || 'stylish outfit');
    const cleanWho = stripBlush(String(who || 'adult woman').replace(/^1girl\s*,\s*/i, ''));
    return cleanForCommand(`1girl, solo, full body, standing, simple background, 1.3::${cleanWho}::, 1.2::wearing ${outfitText}::, calm confident expression, relaxed neutral face, single character, adult proportions, anatomically correct hands, no text, no captions`);
}

function buildSingleAccentPromptForNai(who, accentObj) {
    return cleanForCommand(`1item, solo, ${ITEM_STYLE}, solid plain light cream background, ${accentEnDesc(accentObj, who)}, no text, no captions`);
}

// Рисует картинку для текущего выбора (kind: looks | accents); onDone получает адрес картинки или ''
async function ensurePicture(kind, force, onDone) {
    const st = store();
    const a = activeOf(kind, st);
    const [field, failField] = PIC_FIELDS[kind];
    const okState = kind === 'looks' || kind === 'gacha' ? a?.status === 'choosing' : (a && (a.status === 'choosing' || (a.status === 'worn' && !a.accent)) && (a.accents || []).length);
    if (!a || !okState || !wantImages()) { onDone?.(a?.[field] || ''); return; }
    if (onDone) drawWaitersOf[kind].add(onDone);
    if (drawingKind[kind]) return;
    if (a[field] && !force) { flushPicture(kind, a[field]); return; }
    drawingKind[kind] = true;
    let url = '';
    try {
        const isNai = settings().imageSource === 'novelai';
        const who = isNai ? await ensureHeroineAppearanceEnForNai(st, a) : getHeroineAppearanceEn(st, a);

        // Если выбран NovelAI и мы рисуем гардероб (5 образов) или штрихи (4 штриха):
        // 1) Никогда не передаём референс с аватарки (refs = null), чтобы не ломать генерацию!
        // 2) Делаем отдельные запросы к NovelAI по каждому образу (5 отдельных запросов для 5 нарядов), чтобы не было мешанины на одном листе!
        if (isNai && kind === 'looks') {
            const prevUrl = a[field];
            const prevIndiv = Array.isArray(a.individualImages) ? [...a.individualImages] : null;
            const count = Math.min((a.options || []).length, 5);
            const singleUrls = [];
            for (let i = 0; i < count; i++) {
                const opt = a.options[i];
                setStatus(`🎨 NovelAI рисует наряд ${i + 1} из ${count} («${opt.title}»)…`);
                logImageDiag(`Гардероб NovelAI: запрос наряда ${i + 1}/${count}`, opt.title);
                const singlePrompt = buildSingleOutfitPromptForNai(who, opt);
                const singleUrl = await drawViaNovelAi(singlePrompt, 'portrait', { extraNeg: 'blush, blushing, nose blush, full-face blush, heavy blush, embarrassed, shy, flustered, timid, awkward smile' });
                if (singleUrl) {
                    opt.image = singleUrl;
                    opt.imageLayout = { rows: 1, cols: 1 };
                    opt.crop = { x: 0, y: 0, w: 1, h: 1 };
                    opt.isSingleImage = true;
                    singleUrls.push(singleUrl);
                } else {
                    singleUrls.push('');
                }
            }
            a.individualImages = singleUrls;
            url = singleUrls.find(Boolean) || '';
            if (!url) throw new Error('NovelAI не вернул картинки нарядов');
            const histKey = field + 'History';
            if (!Array.isArray(a[histKey])) a[histKey] = [];
            if (prevUrl && !a[histKey].some(h => h.url === prevUrl)) {
                a[histKey].push({ url: prevUrl, layout: a[field + 'Layout'] || { rows: 1, cols: 1 }, individualImages: prevIndiv });
            }
            if (url && !a[histKey].some(h => h.url === url)) {
                a[histKey].push({ url, layout: { rows: 1, cols: 1 }, individualImages: [...singleUrls] });
            }
            a[field] = url;
            a[field + 'Layout'] = { rows: 1, cols: 1 };
            a[failField] = false;
            await ctx().saveMetadata();
        } else if (isNai && kind === 'accents') {
            const items = (a.accents || []).slice(0, 4);
            const singleUrls = [];
            for (let i = 0; i < items.length; i++) {
                const ac = items[i];
                setStatus(`🎨 NovelAI рисует штрих ${i + 1} из ${items.length} («${ac.title}»)…`);
                const singlePrompt = buildSingleAccentPromptForNai(who, ac);
                const isMakeup = ac.kind === 'makeup' || /макияж|makeup|lipstick|тени|помад/i.test(ac.kind || ac.title);
                const singleUrl = await drawViaNovelAi(singlePrompt, isMakeup ? 'portrait' : 'square', isMakeup ? { extraNeg: 'blush, blushing, nose blush, full-face blush, heavy blush, embarrassed, shy, flustered, timid' } : null);
                if (singleUrl) {
                    ac.image = singleUrl;
                    ac.imageLayout = { rows: 1, cols: 1 };
                    ac.crop = { x: 0, y: 0, w: 1, h: 1 };
                    ac.isSingleImage = true;
                    singleUrls.push(singleUrl);
                } else {
                    singleUrls.push('');
                }
            }
            a.individualAccentImages = singleUrls;
            url = singleUrls.find(Boolean) || '';
            if (!url) throw new Error('NovelAI не вернул картинки штрихов');
            a[field] = url;
            a[field + 'Layout'] = { rows: 1, cols: 1 };
            a[failField] = false;
            await ctx().saveMetadata();
        } else if (isNai && kind === 'gacha') {
            const prevUrl = a[field];
            const prevIndiv = Array.isArray(a.individualGachaImages) ? [...a.individualGachaImages] : null;
            const items = (a.options || []).slice(0, 3);
            const singleUrls = [];
            for (let i = 0; i < items.length; i++) {
                const opt = items[i];
                setStatus(`🎨 NovelAI рисует находку ${i + 1} из ${items.length} («${opt.title}»)…`);
                const itemDesc = opt.en || opt.desc || opt.title;
                const singlePrompt = cleanForCommand(`1item, solo, ${ITEM_STYLE}, solid plain light cream background, centered item: ${itemDesc}, no people, no hands, no text, no captions`);
                const singleUrl = await drawViaNovelAi(singlePrompt, 'square', null);
                if (singleUrl) {
                    opt.image = singleUrl;
                    opt.imageLayout = { rows: 1, cols: 1 };
                    opt.crop = { x: 0, y: 0, w: 1, h: 1 };
                    opt.isSingleImage = true;
                    singleUrls.push(singleUrl);
                } else {
                    singleUrls.push('');
                }
            }
            a.individualGachaImages = singleUrls;
            url = singleUrls.find(Boolean) || '';
            if (!url) throw new Error('NovelAI не вернул картинки находок');
            const histKey = field + 'History';
            if (!Array.isArray(a[histKey])) a[histKey] = [];
            if (prevUrl && !a[histKey].some(h => h.url === prevUrl)) {
                a[histKey].push({ url: prevUrl, layout: a[field + 'Layout'] || { rows: 1, cols: 1 }, individualImages: prevIndiv });
            }
            if (url && !a[histKey].some(h => h.url === url)) {
                a[histKey].push({ url, layout: { rows: 1, cols: 1 }, individualImages: [...singleUrls] });
            }
            a[field] = url;
            a[field + 'Layout'] = { rows: 1, cols: 1 };
            a[failField] = false;
            await ctx().saveMetadata();
        } else {
            let refs = null;
            // Для не-NovelAI генераторов берём аватар только если включена галочка imageRef И режим референса не выключен
            if (!isNai && (kind === 'looks' || kind === 'accents') && settings().imageRef && settings().naiCharRefMode !== 'off') {
                const me = await personaAvatarDataUrl();
                if (me) {
                    const note = kind === 'looks'
                        ? 'The input picture is the reference: keep exactly this character — the same face, hair, eyes and body — and only change the clothes.'
                        : 'The input picture is the reference for the character face: keep the same face, hair, eyes, nose and facial features recognizable, showing her with the specified makeup in the portrait cell.';
                    refs = { images: [me], note };
                }
            }
            const layout = kind === 'looks' ? looksLayout(Math.min(a.options.length, 5)) : kind === 'accents' ? accentsLayout((a.accents || []).length) : { rows: 1, cols: Math.min(a.options.length, 3) };
            const orient = (kind === 'looks' || kind === 'accents') && layout.rows === 2 ? 'portrait' : 'landscape';
            const prevUrl = a[field];
            const prevLayout = a[field + 'Layout'] || layout;
            url = await drawPicture(kind === 'looks' ? sheetPrompt(a, layout) : kind === 'gacha' ? gachaPicPrompt(a) : accentsPrompt(a, layout), refs, orient);
            const histKey = field + 'History';
            if (!Array.isArray(a[histKey])) a[histKey] = [];
            if (prevUrl && !a[histKey].some(h => h.url === prevUrl)) {
                a[histKey].push({ url: prevUrl, layout: prevLayout });
            }
            if (url && !a[histKey].some(h => h.url === url)) {
                a[histKey].push({ url, layout });
            }
            a[field] = url;
            a[field + 'Layout'] = layout;
            a[failField] = false;
            await ctx().saveMetadata();
        }
    } catch (err) {
        a[failField] = true;
        console.warn('[npc_notebook] image', kind, err);
        toastr.warning(`Картинку ${kind === 'looks' ? 'с образами' : kind === 'gacha' ? 'с находками' : 'со штрихами'} нарисовать не вышло: ${escapeHtml(err?.message || err)}. Выбирать можно и по названиям.`, kind === 'gacha' ? '🎰 Находки' : '👗 Гардероб', { escapeHtml: false, timeOut: 10000 });
    } finally {
        drawingKind[kind] = false;
        setStatus('');
        flushPicture(kind, url);
    }
    // штрихи рисуем следом за образами, пока игрок выбирает наряд
    if (kind === 'looks' && url && accentsOn(st) && (a.accents || []).length && !a.accentImage && !a.accentImageFailed) ensurePicture('accents', false);
}
function flushPicture(kind, url) {
    const waiters = [...drawWaitersOf[kind]];
    drawWaitersOf[kind].clear();
    waiters.forEach(fn => { try { fn(url); } catch (e) { /* окно уже закрыто */ } });
}

// ---------- 🎬 Картинка сцены ----------
function canDrawScene() {
    const s = settings();
    if (s.imageSource === 'novelai') return true;
    if (s.imageSource === 'openai-images') return !!(s.imgApiBase && s.imgApiKey && s.imgApiModel);
    if (s.imageSource) return !!ctx().ConnectionManagerRequestService?.sendRequest;
    return !!imageCommand();
}

function collectRecentScenePrompts(st, chat, beforeIdx, maxCount = 5) {
    const list = [];
    if (Array.isArray(chat)) {
        // Если для текущего поста уже нарисована 1-я страница манхвы, включаем её промпт первым, чтобы на 2-й и 3-й странице этого же поста одежда и внешность героев были 1-в-1!
        for (let i = Math.min(beforeIdx - 1, chat.length - 1); i >= 0 && list.length < maxCount; i--) {
            // сам перерисовываемый пост пропускаем: его старый промпт — как раз то, что пытаемся исправить
            const d = chat[i]?.extra?.nnbScene?.desc || chat[i]?.extra?.nsiScene?.desc;
            if (d && String(d).trim() && !list.includes(String(d).trim())) {
                list.unshift(String(d).trim());
            }
        }
    }
    if (list.length < maxCount && Array.isArray(st?.scenes)) {
        for (let i = st.scenes.length - 1; i >= 0 && list.length < maxCount; i--) {
            if (Number(st.scenes[i]?.mesId) >= beforeIdx) continue;
            const d = st.scenes[i]?.desc;
            if (d && String(d).trim() && !list.includes(String(d).trim())) {
                list.unshift(String(d).trim());
            }
        }
    }
    return list.slice(-maxCount);
}


