function getAllComicStyles() {
    const s = settings();
    const custom = Array.isArray(s.customComicStyles) ? s.customComicStyles : [];
    return [...KADR_COMIC_STYLES, ...custom];
}

function getComicStyleById(id) {
    const all = getAllComicStyles();
    return all.find(x => x.id === id) || all[0];
}

// Очистка ролевых технических шапок вида [Date: ...], [Location: ... Characters: ...] и замена спец-пробелов (  Figure Space и др.) на обычные пробелы
function capitalizeSentenceFirstChar(str) {
    const s = String(str || '').trim();
    if (!s) return '';
    return s.replace(/^([«"„“'\(\s]*)([а-яёa-z])/i, (_, prefix, ch) => prefix + ch.toUpperCase());
}

function stripRoleplayHeaderBracketsAndWeirdSpaces(rawStr) {
    if (!rawStr) return '';
    return String(rawStr)
        // Заменяем фигурные/неразрывные/тонкие пробелы (U+2007, U+00A0, U+202F и др.) на обычный пробел и убираем двойные звёздочки жирного шрифта (**БУМ-БУМ** -> БУМ-БУМ), чтобы они не ломали курсив мыслей *...*
        .replace(/[\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]/g, ' ')
        .replace(/\*\*([^*\n]+)\*\*/g, '$1')
        // Убираем технические шапки в квадратных скобках в начале поста/строки: [Date: ...], [Location: ...], [Time: ...], [Characters: ...]
        .replace(/^\s*(?:\[[^\]\n]{2,260}\]\s*)+/gi, '')
        .replace(/\n\s*\[(?:Date|Location|Time|Characters|Место|Время|Дата|Персонажи|Локация)\s*:[^\]\n]{1,260}\]\s*/gi, '\n')
        .trim();
}

// forcePages: ровно столько страниц (для дорисовки главы, начатой при других рамках «от … до …»)
function splitPostIntoComicChunks(rawPostText, targetChunkChars = 540, forcePages = 0) {
    const rawWithSceneMarkers = String(rawPostText || '')
        .replace(/<[^>]+>/g, '')
        .replace(/\r\n/g, '\n')
        .replace(/[\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]/g, ' ')
        .replace(/\*\*([^*\n]+)\*\*/g, '$1')
        .replace(/^\s*(?:\[[^\]\n]{2,260}\]\s*)+/gi, '')
        .replace(/\n\s*\[(?:Date|Time|Characters|Время|Дата|Персонажи)\s*:[^\]\n]{1,260}\]\s*/gi, '\n')
        .replace(/\n\s*\[(?:Location|Локация|Место)\s*:[^\]\n]{1,260}\]\s*/gi, '\n[[SCENE_BREAK]]\n')
        .trim();
    if (!rawWithSceneMarkers) return [];
    // Сколько страниц: по содержанию, а не по числу абзацев. Раньше каждый абзац становился страницей (8–10 стр. по 3 кадра
    // на пост, где почти ничего не происходит → одинаковые кадры). Кадр ≈ один «момент» ≈ 2–3 предложения (~430 знаков),
    // страница из 3 кадров ≈ 1300 знаков; реплик на странице помещается ~4. Плюс рамки пользователя «от … до …».
    let sCfg = {};
    try { sCfg = settings() || {}; } catch (e) { /* настройки недоступны — берём умолчания */ }
    const userMax = Math.max(1, Math.min(10, Math.round(Number(sCfg.comicMaxPages) || 6)));
    const userMin = Math.max(1, Math.min(userMax, Math.round(Number(sCfg.comicMinPages) || 1)));
    const plainForCount = stripRoleplayHeaderBracketsAndWeirdSpaces(rawWithSceneMarkers.replace(/\[\[SCENE_BREAK\]\]/g, '\n'));
    const quoteCount = (plainForCount.match(/[«“"][^«»“”"\n]{3,}[»”"]/g) || []).length;
    const sceneCount = rawWithSceneMarkers.split(/\[\[SCENE_BREAK\]\]/).filter(b => b.trim()).length;
    const byContent = Math.max(Math.round(plainForCount.length / 1300), Math.ceil(quoteCount / 4), Math.min(sceneCount, 3), 1);
    const maxPages = Number(forcePages) > 0 ? Math.min(10, Math.round(Number(forcePages))) : Math.max(userMin, Math.min(userMax, byContent));

    const splitParagraphIntoSentences = (para) => {
        const out = [];
        let buf = '';
        let inDoubleQuotes = false;
        let inGuillemets = false;
        let inAsterisk = false;
        for (let i = 0; i < para.length; i++) {
            const ch = para[i];
            buf += ch;
            if (ch === '“') inDoubleQuotes = true;
            else if (ch === '”') inDoubleQuotes = false;
            else if (ch === '"') inDoubleQuotes = !inDoubleQuotes;
            else if (ch === '«' && !inDoubleQuotes) inGuillemets = true;
            else if (ch === '»') inGuillemets = false;
            else if (ch === '*') inAsterisk = !inAsterisk;
            const inQuotes = inDoubleQuotes || inGuillemets;

            const isClosingEndedQuoteOrThought = !inQuotes && !inAsterisk && /[»”"*]/.test(ch) && i > 0 && /[.!?…]/.test(para[i - 1]);
            if (!inQuotes && !inAsterisk && (/[.!?…]/.test(ch) || isClosingEndedQuoteOrThought)) {
                const nextPart = para.slice(i + 1);
                const attrMatch = nextPart.match(/^(\s*[»”"*]?\s*,?\s*[—–-]\s*[а-яё][^.!?;\n]{2,180}[.!?…])/i);
                if (attrMatch) {
                    buf += attrMatch[1];
                    i += attrMatch[1].length;
                }
                if (i + 1 >= para.length || /^\s+[А-ЯЁA-Z«“"*—–-]/.test(para.slice(i + 1))) {
                    if (buf.trim()) out.push(buf.trim());
                    buf = '';
                }
            }
        }
        if (buf.trim()) out.push(buf.trim());
        return out.filter(Boolean);
    };

    const sceneBlocks = rawWithSceneMarkers.split(/\[\[SCENE_BREAK\]\]/).map(b => b.trim()).filter(Boolean);
    let pages = [];

    for (let sIdx = 0; sIdx < sceneBlocks.length; sIdx++) {
        const sLines = stripRoleplayHeaderBracketsAndWeirdSpaces(sceneBlocks[sIdx])
            .split(/\n+/)
            .map(p => p.replace(/\s+/g, ' ').trim())
            .filter(Boolean);
        let scenePages = sLines.map(l => ({ text: l, sents: splitParagraphIntoSentences(l), sceneIdx: sIdx }));

        // Внутри одной сцены объединяем короткие 1–2-предложенческие абзацы (< 285 симв., вроде одиночного предложения «Скосив сонный зеленый глаз...») с соседним абзацем этой же сцены, чтобы не плодить полупустые страницы из 1 предложения!
        let i = 0;
        while (i < scenePages.length) {
            const cur = scenePages[i];
            if (cur.text.length < 285 || cur.sents.length <= 1) {
                if (i > 0 && (scenePages[i - 1].text.length + cur.text.length <= 860)) {
                    scenePages[i - 1].text = `${scenePages[i - 1].text} ${cur.text}`.trim();
                    scenePages[i - 1].sents = splitParagraphIntoSentences(scenePages[i - 1].text);
                    scenePages.splice(i, 1);
                    continue;
                } else if (i + 1 < scenePages.length && (cur.text.length + scenePages[i + 1].text.length <= 860)) {
                    scenePages[i + 1].text = `${cur.text} ${scenePages[i + 1].text}`.trim();
                    scenePages[i + 1].sents = splitParagraphIntoSentences(scenePages[i + 1].text);
                    scenePages.splice(i, 1);
                    continue;
                }
            }
            i++;
        }
        pages.push(...scenePages);
    }

    // Не хватает страниц до нужного числа — делим самый длинный кусок пополам по предложениям (каждой половине минимум 2)
    const splitMinLen = 0;
    const splitMinSents = 4; // каждой половине — минимум 2 предложения
    while (pages.length < maxPages) {
        let bestIdx = -1;
        let bestLen = splitMinLen;
        for (let i = 0; i < pages.length; i++) {
            const pg = pages[i];
            if (pg.text.length > bestLen && pg.sents.length >= splitMinSents) {
                bestLen = pg.text.length;
                bestIdx = i;
            }
        }
        if (bestIdx < 0) break;
        const target = pages[bestIdx];
        const totalChars = target.text.length;
        let splitAt = Math.max(2, Math.floor(target.sents.length / 2));
        let acc = 0;
        let bestDiff = 999999;
        for (let k = 2; k <= target.sents.length - 2; k++) {
            acc = target.sents.slice(0, k).join(' ').length;
            const diff = Math.abs(acc - totalChars / 2);
            if (diff < bestDiff) {
                bestDiff = diff;
                splitAt = k;
            }
        }
        const firstHalfTxt = target.sents.slice(0, splitAt).join(' ').trim();
        const secondHalfTxt = target.sents.slice(splitAt).join(' ').trim();
        if (!firstHalfTxt || !secondHalfTxt) break;
        pages.splice(
            bestIdx,
            1,
            { text: firstHalfTxt, sents: target.sents.slice(0, splitAt), sceneIdx: target.sceneIdx },
            { text: secondHalfTxt, sents: target.sents.slice(splitAt), sceneIdx: target.sceneIdx }
        );
    }

    if (pages.length > maxPages) {
        // Ровно maxPages страниц примерно одинакового объёма (раньше склеивались две самые короткие соседние —
        // выходили страницы 1000 и 2100 знаков). Разрыв между сценами ([Location: …]) внутри страницы — штраф.
        const n = pages.length, k = maxPages;
        const pre = [0];
        pages.forEach(pg => pre.push(pre[pre.length - 1] + pg.text.length));
        const cost = (a, b) => { // абзацы a..b-1 на одной странице
            let pen = 0;
            for (let i = a + 1; i < b; i++) if (pages[i].sceneIdx !== pages[i - 1].sceneIdx) pen += 5000;
            return pre[b] - pre[a] + pen;
        };
        const best = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(Infinity));
        const cut = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(0));
        best[0][0] = 0;
        for (let j = 1; j <= k; j++) {
            for (let i = j; i <= n; i++) {
                for (let m = j - 1; m < i; m++) {
                    const v = Math.max(best[j - 1][m], cost(m, i));
                    if (v < best[j][i]) { best[j][i] = v; cut[j][i] = m; }
                }
            }
        }
        const bounds = [];
        for (let j = k, i = n; j > 0; j--) { const m = cut[j][i]; bounds.unshift([m, i]); i = m; }
        pages = bounds.map(([a, b]) => {
            const txt = pages.slice(a, b).map(pg => pg.text).join('\n\n');
            return { text: txt, sents: splitParagraphIntoSentences(txt), sceneIdx: pages[a].sceneIdx };
        });
    }

    return pages.map((pg, idx) => {
        const flat = pg.text.replace(/\s+/g, ' ').trim();
        const preview = flat.length <= 72 ? flat : `${flat.slice(0, 52).trim()}…`;
        return {
            index: idx,
            total: pages.length,
            text: pg.text,
            preview,
        };
    });
}

const NARRATOR_SPEECH_VERBS_RE = /^(?:сказал|сказала|ответил|ответила|спросил|спросила|хмыкнул|хмыкнула|буркнул|буркнула|прошептал|прошептала|рявкнул|рявкнула|усмехнулся|усмехнулась|добавил|добавила|парировал|парировала|заметил|заметила|пояснил|пояснила|отозвался|отозвалась|фыркнул|фыркнула|ф-фыркнул|ф-фыркнула|вздохнул|вздохнула|протянул|протянула|воскликнул|воскликнула|крикнул|крикнула|процедил|процедила|пробормотал|пробормотала|пророкотал|пророкотала|проворковал|проворковала|прочитал|прочитала|заявил|заявила|отбрил|отбрила|уронил|уронила|заверещал|заверещала|кивнул|кивнула|подумал|подумала|подумалось|мелькнуло|пронеслось|бросил|бросила|выдохнул|выдохнула|произнес|произнесла|проворчал|проворчала|хихикнул|хихикнула|рассмеялся|рассмеялась)(?=$|[^а-яёa-z0-9])/i;

function stripNarratorDashAttribution(rawText) {
    const s = String(rawText || '').replace(/\s+/g, ' ').trim();
    if (!s) return '';
    const parts = s.split(/(\s+[—–-]\s+)/);
    if (parts.length <= 1) return s;
    let out = parts[0];
    let i = 1;
    while (i + 1 < parts.length) {
        const sep = parts[i];
        const nxt = parts[i + 1].trim();
        if (NARRATOR_SPEECH_VERBS_RE.test(nxt)) {
            if (i + 3 < parts.length) {
                out = out.replace(/[,;:\s]+$/, '');
                if (!/[.!?…]$/.test(out)) out += '.';
                out += ' ' + parts[i + 3].trim();
                i += 4;
                continue;
            } else {
                out = out.replace(/[,;:\s]+$/, '');
                if (!/[.!?…]$/.test(out)) out += '.';
                break;
            }
        } else {
            out += sep + parts[i + 1];
            i += 2;
        }
    }
    return out.trim();
}

function formatCompleteQuoteSentence(rawStr, maxChars = 330) {
    let s = stripRoleplayHeaderBracketsAndWeirdSpaces(rawStr).replace(/\s+/g, ' ').replace(/^[«"„“*]+|[»"”*]+$/g, '').trim();
    s = capitalizeSentenceFirstChar(s);
    if (!s) return '';
    const effMax = Math.max(320, Number(maxChars) || 330);
    // Если до конца предложения остаётся 1–45 символов (например последнее слово «...во все четыре глаза.»), НИКОГДА не отрезаем концовку троеточием!
    if (s.length <= effMax + 45) return s;
    const sentences = s.split(/(?<=[.!?])\s+/).filter(Boolean);
    if (sentences.length > 1) {
        let acc = '';
        for (const sent of sentences) {
            const next = acc ? `${acc} ${sent}` : sent;
            if (next.length <= effMax + 35) acc = next;
            else break;
        }
        if (acc && acc.length >= 15) return acc.trim();
        if (sentences[0].length <= effMax + 60) return sentences[0].trim();
    }
    const sub = s.slice(0, effMax);
    const clauseBreak = Math.max(sub.lastIndexOf(' — '), sub.lastIndexOf(' – '), sub.lastIndexOf(' - '), sub.lastIndexOf('; '), sub.lastIndexOf(': '), sub.lastIndexOf(', '));
    if (clauseBreak > 140) {
        return sub.slice(0, clauseBreak).replace(/[,;:\s—–-]+$/, '') + '.';
    }
    const sp = sub.lastIndexOf(' ');
    return (sp > 100 ? sub.slice(0, sp) : sub).replace(/[,;:\s]+$/, '') + '…';
}

function restoreFullQuoteFromSource(rawQuote, sourceText, strictVerbatim = false) {
    let s = stripRoleplayHeaderBracketsAndWeirdSpaces(rawQuote).replace(/\s+/g, ' ').replace(/^[«"„“*]+|[»"”*]+$/g, '').trim();
    if (!s || !sourceText) return capitalizeSentenceFirstChar(s);
    const prefix = s.replace(/[.…,;:\s—–-]+$/, '').trim();
    if (prefix.length < 2) return capitalizeSentenceFirstChar(s);

    const cleanSrc = stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(sourceText))).replace(/<[^>]+>/g, '').replace(/\r\n/g, '\n'));
    const lowSrc = cleanSrc.toLowerCase().replace(/ё/g, 'е');
    const lowPref = prefix.toLowerCase().replace(/ё/g, 'е');
    let hitIdx = lowSrc.indexOf(lowPref);
    if (hitIdx < 0 && lowPref.length >= 14) {
        hitIdx = lowSrc.indexOf(lowPref.slice(0, 14).trim());
    }
    const prefWords = lowPref.replace(/[^a-zа-я0-9\s-]+/gi, ' ').split(/\s+/).filter(w => w.length >= 2);
    if (hitIdx < 0 && prefWords.length >= 3) {
        for (let wIdx = 0; wIdx <= prefWords.length - 3; wIdx++) {
            const win3 = prefWords.slice(wIdx, wIdx + 3).join(' ');
            if (win3.length >= 10) {
                const pos = lowSrc.indexOf(win3);
                if (pos >= 0) {
                    hitIdx = pos;
                    break;
                }
            }
        }
    }
    if (hitIdx < 0) {
        if (strictVerbatim) return '';
        return capitalizeSentenceFirstChar(stripNarratorDashAttribution(s));
    }

    const qSpanRe = /(?:"([^"\n]{2,2500}?)"|«([^«»\n]{2,2500}?)»|“([^“”\n]{2,2500}?)”)/g;
    let qm;
    while ((qm = qSpanRe.exec(cleanSrc)) !== null) {
        const innerQStr = qm[1] || qm[2] || qm[3] || '';
        if (isInlineTitleOrTarotQuote(cleanSrc, qm.index, qm[0], innerQStr)) continue;
        const spanStart = qm.index;
        const spanEnd = qm.index + qm[0].length;
        if (hitIdx >= spanStart && hitIdx <= spanEnd) {
            const fullSpoken = stripNarratorDashAttribution(innerQStr.replace(/\s+/g, ' ').trim());
            if (fullSpoken.length <= 335) {
                return capitalizeSentenceFirstChar(fullSpoken);
            }
            break;
        }
    }

    const astSpanRe = /\*([^*\n]{2,1500}?)\*/g;
    let am;
    while ((am = astSpanRe.exec(cleanSrc)) !== null) {
        const spanStart = am.index;
        const spanEnd = am.index + am[0].length;
        if (hitIdx >= spanStart && hitIdx <= spanEnd) {
            const fullThought = stripNarratorDashAttribution(am[1].replace(/\s+/g, ' ').trim());
            if (fullThought.length <= 335) {
                return capitalizeSentenceFirstChar(fullThought);
            }
            break;
        }
    }

    let startIdx = hitIdx;
    const lookbackMax = 180;
    const lookFrom = Math.max(0, hitIdx - lookbackMax);
    const lookback = cleanSrc.slice(lookFrom, hitIdx);
    const boundaryMatch = lookback.match(/.*(?:[.!?;\n]|[»”"*])/s);
    if (boundaryMatch) {
        const candidateStart = lookFrom + boundaryMatch[0].length;
        if (hitIdx - candidateStart <= 165) {
            startIdx = candidateStart;
        }
    } else if (hitIdx <= 165) {
        startIdx = 0;
    }

    const extraLeadLen = Math.max(0, hitIdx - startIdx);
    let lineRem = cleanSrc.slice(startIdx, hitIdx + 390).split('\n')[0].replace(/\s+/g, ' ').trim();
    lineRem = lineRem.replace(/^[,;:\s—–-]+/, '').trim();
    const closeQ = lineRem.search(/[»”"*]/);
    const openQ = lineRem.search(/[«“]/);
    if (closeQ >= 0 && (openQ < 0 || closeQ < openQ)) {
        lineRem = lineRem.slice(0, closeQ).trim();
    }
    lineRem = stripNarratorDashAttribution(lineRem);
    const matchStart = Math.min(prefix.length + extraLeadLen, lineRem.length);
    if (lineRem.length >= matchStart) {
        const tailMatch = lineRem.slice(matchStart).match(/^[^.!?;]*[.!?;]/);
        if (tailMatch && tailMatch[0] !== undefined) {
            lineRem = (lineRem.slice(0, matchStart) + tailMatch[0]).replace(/;$/, '.').trim();
        }
    }
    if (lineRem && !/[.!?…]$/.test(lineRem)) lineRem += '.';
    return capitalizeSentenceFirstChar(lineRem);
}

function isInlineTitleOrTarotQuote(fullText, matchIndex, matchFullStr, innerText) {
    const inner = String(innerText || '').trim();
    if (!inner) return true;
    const words = inner.split(/\s+/).filter(Boolean);
    const before = String(fullText || '').slice(Math.max(0, matchIndex - 35), matchIndex);
    const after = String(fullText || '').slice(matchIndex + String(matchFullStr || '').length, matchIndex + String(matchFullStr || '').length + 60);
    // Считаем тире после кавычек атрибуцией прямой речи ТОЛЬКО если перед закрывающей кавычкой есть !/? или после кавычки стоит запятая перед тире, ИЛИ сразу после тире идёт глагол речи!
    const afterDashWord = (after.match(/^\s*,?\s*[—–-]\s*([а-яё\-]+)/i) || [])[1] || '';
    const hasCommaOrExclBeforeDash = /^\s*,\s*[—–-]/.test(after) || (/[!?…]$/.test(inner) && /^\s*[—–-]/.test(after));
    const hasSpeechVerbAfterDash = afterDashWord && NARRATOR_SPEECH_VERBS_RE.test(afterDashWord);
    if (hasCommaOrExclBeforeDash || hasSpeechVerbAfterDash) return false;

    const precededByInlineWord = /[а-яёa-z]\s+$/i.test(before);
    if (precededByInlineWord && words.length <= 4 && inner.length <= 36 && !/[!?]$/.test(inner)) {
        return true;
    }
    if (words.length <= 2 && inner.length <= 22 && !/[.!?…]$/.test(inner) && !/^\s*$/.test(before)) {
        return true;
    }
    return false;
}

function classifyCaptionKindAndSpeaker(rawQuoteObj, sourceText, defaultSpeaker = '', cast = [], st = null, fullStoryText = '') {
    const rawKind = String(rawQuoteObj?.kind || '').toLowerCase().trim();
    let rawSpk = String(rawQuoteObj?.speaker || defaultSpeaker || '').trim();
    const txt = String(rawQuoteObj?.text || '').trim();
    if (!txt) return { kind: 'narration', speaker: '' };

    // Явные маркеры в поле speaker или kind
    if (rawKind === 'narration' || /^(?:narration|narrator|описание|автор|нарратив|за кадром|закадр|текст|none|-)$/i.test(rawSpk)) {
        return { kind: 'narration', speaker: '' };
    }
    const explicitThought = rawKind === 'thought' || /^💭|(?:^|[^а-яёa-z0-9])(?:мысл[ьи]|thought|про себя)(?=$|[^а-яёa-z0-9])/i.test(rawSpk);
    rawSpk = rawSpk.replace(/^💭\s*/, '').replace(/\s*\((?:мысл[ьи]|thought|про себя)\)\s*$/i, '').trim();

    const norm = t => String(t || '').toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9]+/gi, ' ').trim();
    const cleanSrc = stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(sourceText || ''))).replace(/<[^>]+>/g, ''));
    const nTxt = norm(txt);
    const words = nTxt.split(/\s+/).filter(w => w.length >= (nTxt.length <= 14 ? 1 : 2));

    const speechSpans = [];
    const thoughtSpans = [];
    let m;
    const qRe = /(?:"([^"\n]{2,2500}?)"|«([^«»\n]{2,2500}?)»|“([^“”\n]{2,2500}?)”)/g;
    while ((m = qRe.exec(cleanSrc)) !== null) {
        const innerQStr = m[1] || m[2] || m[3] || '';
        if (isInlineTitleOrTarotQuote(cleanSrc, m.index, m[0], innerQStr)) continue;
        const spanNorm = norm(innerQStr);
        const ctxWindow = cleanSrc.slice(Math.max(0, m.index - 85), Math.min(cleanSrc.length, m.index + m[0].length + 85)).toLowerCase().replace(/ё/g, 'е');
        if (/(?:^|[^а-яёa-z0-9])(подумал|подумала|подумалось|мысленно|про себя|в мыслях|мелькнуло в голове|пронеслось в голове|подумать)(?=$|[^а-яёa-z0-9])/i.test(ctxWindow)) {
            thoughtSpans.push(spanNorm);
        } else {
            speechSpans.push(spanNorm);
        }
    }
    const dRe = /(?:^|\n)\s*[—–-]\s*([^\n]{2,2500})/g;
    while ((m = dRe.exec(cleanSrc)) !== null) {
        const ctxLow = m[1].toLowerCase().replace(/ё/g, 'е');
        if (/[,!?…]\s*[—–-]\s*(?:[а-яё]+\s+)?(?:подумал|подумала|подумалось|мелькнуло в голове|пронеслось в голове)(?=$|[^а-яёa-z0-9])/i.test(ctxLow)) {
            thoughtSpans.push(norm(m[1]));
        } else {
            speechSpans.push(norm(m[1]));
        }
    }
    const astRe = /\*([^*\n]{2,1500})\*/g;
    while ((m = astRe.exec(cleanSrc)) !== null) {
        thoughtSpans.push(norm(m[1]));
    }

    const matchesSpanList = spans => {
        if (!words.length) return false;
        for (const sp of spans) {
            const padded = ' ' + sp + ' ';
            const hits = words.filter(w => padded.includes(' ' + w)).length;
            if ((hits / words.length) >= 0.62) return true;
        }
        return false;
    };

    // «THOUGHT» от модели, но в посте это не мысль (не в *звёздочках*), а фраза без «я/ты» и с «он/она/ей» — это повествование
    const tLowQ = ' ' + String(txt || '').toLowerCase().replace(/ё/g, 'е').replace(/[^а-я]+/g, ' ') + ' ';
    const hasFirstSecondPerson = / (я|меня|мне|мной|мой|моя|мое|мои|моих|мы|нас|нам|нами|наш|наша|ты|тебя|тебе|тобой|твой|твоя|вы|вас|вам) /.test(tLowQ);
    const hasThirdPerson = / (он|она|они|его|ее|ей|ему|их|им|него|нее|ней|нему|ним) /.test(tLowQ);
    const fakeThought = explicitThought && !matchesSpanList(thoughtSpans) && !hasFirstSecondPerson && hasThirdPerson;
    const inThoughtSpan = (explicitThought && !fakeThought) || matchesSpanList(thoughtSpans);
    const inSpeechSpan = matchesSpanList(speechSpans);
    const detectedKind = inThoughtSpan ? 'thought' : (inSpeechSpan ? 'speech' : 'narration');
    const validSpk = validateAndSanitizeQuoteSpeaker(rawSpk, txt, cleanSrc, cast, st, detectedKind, fullStoryText || cleanSrc);

    // Если имя персонажа упоминается внутри самой фразы в 3-м лице (например: «София застегнула пальто...», «Седан Софии шуршал...», «На заднем сиденье Джулия расстегнула...») и эта фраза не из прямой речи — это 100% авторское описание БЕЗ подписи имени!
    const selfMentionedIn3rdPerson = validSpk && isNameMentionedInText(validSpk, txt);

    if (inThoughtSpan && !selfMentionedIn3rdPerson) {
        return { kind: 'thought', speaker: validSpk };
    }
    if (inSpeechSpan && !selfMentionedIn3rdPerson) {
        return { kind: 'speech', speaker: validSpk };
    }
    // Если фраза НЕ находится ни в кавычках прямой речи, ни в диалоге с тире — это авторский нарратив (описание), убираем имя персонажа!
    if (cleanSrc && (speechSpans.length > 0 || !inSpeechSpan)) {
        return { kind: 'narration', speaker: '' };
    }
    return { kind: validSpk ? 'speech' : 'narration', speaker: validSpk || '' };
}

function parseRawQuoteLinePayload(qBody, fallbackPanel = 1) {
    const cleanBody = String(qBody || '').trim().replace(/\]$/, '');
    if (!cleanBody || /^\(?нет\)?$/i.test(cleanBody)) return null;
    const parts = cleanBody.split('|').map(x => x.trim()).filter(Boolean);
    let kind = '';
    let speaker = '';
    let text = '';

    if (parts.length >= 3 && /^(?:SPEECH|РЕЧЬ|THOUGHT|МЫСЛЬ|МЫСЛИ|NARRATION|ОПИСАНИЕ|АВТОР|НАРРАТИВ)$/i.test(parts[0])) {
        const tag = parts[0].toUpperCase();
        kind = (tag === 'THOUGHT' || tag === 'МЫСЛЬ' || tag === 'МЫСЛИ') ? 'thought' : ((tag === 'NARRATION' || tag === 'ОПИСАНИЕ' || tag === 'АВТОР' || tag === 'НАРРАТИВ') ? 'narration' : 'speech');
        speaker = kind === 'narration' ? '' : parts[1];
        text = parts.slice(2).join(' | ');
    } else if (parts.length === 2) {
        if (/^(?:NARRATION|ОПИСАНИЕ|АВТОР|НАРРАТИВ|ЗА КАДРОМ)$/i.test(parts[0])) {
            kind = 'narration';
            speaker = '';
            text = parts[1];
        } else if (/^(?:THOUGHT|МЫСЛЬ|МЫСЛИ)$/i.test(parts[0])) {
            kind = 'thought';
            speaker = '';
            text = parts[1];
        } else {
            speaker = parts[0];
            kind = /^💭|\((?:мысл[ьи]|thought)\)/i.test(speaker) ? 'thought' : 'speech';
            text = parts[1];
        }
    } else {
        text = parts[0] || cleanBody;
        kind = 'narration';
    }
    text = text
        .replace(/^[«"„“*]+|[»"”*]+$/g, '')
        .replace(/,\s*\./g, '.')
        .replace(/[,;:]\s*$/, '.')
        .trim();
    if (speaker) {
        speaker = speaker.replace(/(^|\s)(💭\s*)?([a-zа-яё])/g, (m, sp, ico, ch) => `${sp}${ico || ''}${ch.toUpperCase()}`);
    }
    if (!text) return null;
    return { panel: fallbackPanel, kind, speaker, text };
}

// Извлечение прямых реплик, мыслей И авторских описаний из кусочка поста, чтобы КАЖДЫЙ из 3–4 фреймов страницы гарантированно получил свой текст без пустых кадров!
function extractRealQuotesFromPostText(rawText, defaultSpeaker = '', desiredCount = 3) {
    const clean = stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(rawText || ''))).replace(/<[^>]+>/g, '').replace(/\r\n/g, '\n'));
    const maxQ = Math.max(3, Math.min(4, Number(desiredCount) || 3));
    const candidates = [];

    const cleanSpeechBlock = x => {
        let s = stripNarratorDashAttribution(String(x || ''));
        s = formatCompleteQuoteSentence(s, 330);
        return s.length >= 2 ? s : '';
    };

    const pushBlockOrSentences = (rawBlock, kindHint) => {
        const cleaned = stripNarratorDashAttribution(rawBlock);
        const sents = cleaned.split(/(?<=[.!?…])\s+/).map(x => x.trim()).filter(x => x.length >= 4);
        if (sents.length >= 2 && cleaned.length > 335) {
            for (const sn of sents) {
                const f = formatCompleteQuoteSentence(sn, 330);
                if (f) candidates.push({ kind: kindHint, speaker: defaultSpeaker, text: f });
            }
        } else {
            const f = cleanSpeechBlock(rawBlock);
            if (f) candidates.push({ kind: kindHint, speaker: defaultSpeaker, text: f });
        }
    };

    const qRe = /(?:"([^"\n]{2,2500}?)"|«([^«»\n]{2,2500}?)»|“([^“”\n]{2,2500}?)”)/g;
    let m;
    while ((m = qRe.exec(clean)) !== null && candidates.length < 8) {
        const innerQStr = m[1] || m[2] || m[3] || '';
        if (isInlineTitleOrTarotQuote(clean, m.index, m[0], innerQStr)) continue;
        const ctxAround = clean.slice(Math.max(0, m.index - 80), Math.min(clean.length, m.index + m[0].length + 80)).toLowerCase().replace(/ё/g, 'е');
        const isTh = /(?:^|[^а-яёa-z0-9])(подумал|подумала|подумалось|мысленно|про себя|в мыслях|мелькнуло в голове)(?=$|[^а-яёa-z0-9])/i.test(ctxAround);
        pushBlockOrSentences(innerQStr, isTh ? 'thought' : 'speech');
    }
    const dRe = /(?:^|\n)\s*[—–-]\s*([^\n]{2,2500})/g;
    while ((m = dRe.exec(clean)) !== null && candidates.length < 8) {
        pushBlockOrSentences(m[1], 'speech');
    }
    const astRe = /\*([^*\n]{3,1200})\*/g;
    while ((m = astRe.exec(clean)) !== null && candidates.length < 8) {
        pushBlockOrSentences(m[1], 'thought');
    }

    // Если в отрывке меньше реплик/мыслей, чем фреймов на странице (или это чисто описательный отрывок, как поездка в машине!),
    // добираем предложения авторского описания (narration, без имени говорящего), чтобы ни один фрейм не остался пустым без текста!
    const speechVerbAttrStartRe = /^(?:пророкотал[аи]?|пробормотал[аи]?|проворковал[аи]?|прочитал[аи]?|заявил[аи]?|отбрил[аи]?|уронил[аи]?|заметил[аи]?|заверещал[аи]?|возмущ[её]нно|безапелляционно|рассудительно|сварливо|невинно|задумчиво|коротко|тихо|громко|сердито|усмехнул[ась]*|хмыкнул[аи]?|фыркнул[аи]?|ф-фыркнул[аи]?|шепнул[аи]?|крикнул[аи]?|выкрикнул[аи]?|добавил[аи]?|ответил[аи]?|спросил[аи]?|произн[её]с(?:ла)?|сказал[аи]?|бросил[аи]?|отозвал[ась]*)(?=$|[^а-яёa-z0-9])/i;
    const allNarrativeSents = clean
        .replace(/\*[^*\n]{2,1500}\*/g, ' ')
        .replace(/[^.!?…\n]{0,80}:\s*(?=[«“"])/g, '. ')
        .replace(/(?:"([^"\n]*)"|«([^«»\n]*)»|“([^“”\n]*)”)(\s*,?\s*[—–-]\s*[^.!?…\n]+[.!?…])?/g, (fullM, q1, q2, q3, attrTail, offset, fullS) => {
            const innerQ = q1 ?? q2 ?? q3 ?? '';
            if (isInlineTitleOrTarotQuote(fullS, offset, `«${innerQ}»`, innerQ)) {
                return fullM;
            }
            return '. ';
        })
        .replace(/(?:^|\n)\s*[—–-]\s*[^\n]+/g, ' ')
        .split(/(?<=[.!?…])\s+|\n+/)
        .filter(rawS => !/^\s*[—–-]\s*/.test(rawS) || !speechVerbAttrStartRe.test(rawS.replace(/^\s*[—–-]+\s*/, '')))
        .map(s => s.replace(/^[,;:\s—–-]+/, '').replace(/[:;\s—–-]+$/, '').replace(/\s+/g, ' ').trim())
        .filter(s => s.length >= 16 && /[.!?…]$/.test(s) && !/^(?:пророкотал[аи]?|пробормотал[аи]?|проворковал[аи]?|прочитал[аи]?|заявил[аи]?|отбрил[аи]?|уронил[аи]?|заверещал[аи]?|фыркнул[аи]?|ф-фыркнул[аи]?)\s+(?:кот|п[её]с|он|она|девушка|женщина|мужчина|хозяйка|гадалка|журналистка|юристка)(?=$|[^а-яёa-z0-9])/i.test(s));
    if (candidates.length + allNarrativeSents.length < maxQ) {
        const expandedNarr = [];
        for (const ns of allNarrativeSents) {
            if (ns.length > 140 && (ns.includes('; ') || ns.includes(' — ') || ns.includes(' - '))) {
                const subParts = ns.split(/(?:;\s+|\s+[—–-]\s+)/).map(x => x.trim()).filter(x => x.length >= 25);
                if (subParts.length >= 2) {
                    subParts.forEach(sp => expandedNarr.push(/[.!?…]$/.test(sp) ? sp : (sp + '.')));
                    continue;
                }
            }
            expandedNarr.push(ns);
        }
        allNarrativeSents.length = 0;
        allNarrativeSents.push(...expandedNarr);
    }

    for (const ns of allNarrativeSents) {
        const f = formatCompleteQuoteSentence(ns, 330);
        if (f) candidates.push({ kind: 'narration', speaker: '', text: f });
    }

    const norm = t => String(t || '').toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9]+/gi, ' ').trim();
    const normClean = norm(clean);
    const seen = new Set();
    const uniqueCands = [];
    for (const c of candidates) {
        const n = norm(c.text);
        if (n && !seen.has(n)) {
            seen.add(n);
            const posInText = normClean.indexOf(n.slice(0, 24));
            uniqueCands.push({
                ...c,
                pos: posInText >= 0 ? posInText : 999999,
            });
        }
    }
    uniqueCands.sort((a, b) => a.pos - b.pos);
    // Если в абзаце 4–5 смысловых блоков, а фреймов на странице maxQ (3), аккуратно объединяем соседние блоки одного типа (например два соседних предложения описания про бланк увольнения Наои или две реплики подряд одной героини), если их сумма <= 345 символов, чтобы НИ ОДНО предложение абзаца не пропало!
    while (uniqueCands.length > maxQ) {
        let mergedAny = false;
        let bestPairIdx = -1;
        let bestPairLen = 350;
        for (let i = 0; i < uniqueCands.length - 1; i++) {
            const a = uniqueCands[i];
            const b = uniqueCands[i + 1];
            if (a.kind === b.kind && (a.kind === 'narration' || a.kind === 'speech')) {
                const combLen = a.text.length + 1 + b.text.length;
                if (combLen <= 345 && combLen < bestPairLen) {
                    bestPairLen = combLen;
                    bestPairIdx = i;
                }
            }
        }
        if (bestPairIdx >= 0) {
            const a = uniqueCands[bestPairIdx];
            const b = uniqueCands[bestPairIdx + 1];
            const aTxt = /[.!?…]$/.test(a.text) ? a.text : (a.text + '.');
            uniqueCands.splice(bestPairIdx, 2, {
                ...a,
                text: `${aTxt} ${b.text}`.trim(),
            });
            mergedAny = true;
        }
        if (!mergedAny) break;
    }

    let firstNarr = uniqueCands.find(c => c.kind === 'narration' && c.pos <= 40);
    const dialogueAndThoughts = uniqueCands.filter(c => c.kind === 'speech' || c.kind === 'thought');
    // Если в отрывке 2 реплики вслух одного героя + мысль + описание (всего > 3 блоков, как во 2-м и 5-м абзацах со складом), объединяем 2 реплики вслух в одну плашку речи (если их сумма <= 335 симв.), чтобы не потерять вторую реплику!
    if (uniqueCands.length > maxQ) {
        const speechIndices = [];
        dialogueAndThoughts.forEach((dt, idx) => { if (dt.kind === 'speech') speechIndices.push(idx); });
        if (speechIndices.length >= 2) {
            const idxA = speechIndices[0];
            const idxB = speechIndices[1];
            const spA = dialogueAndThoughts[idxA];
            const spB = dialogueAndThoughts[idxB];
            if (spA.text.length + 3 + spB.text.length <= 335) {
                const aTxt = /[.!?…]$/.test(spA.text) ? spA.text : (spA.text + '.');
                dialogueAndThoughts[idxA] = { ...spA, text: `${aTxt} ${spB.text}`.trim() };
                dialogueAndThoughts.splice(idxB, 1);
            }
        }
    }
    const restNarr = uniqueCands.filter(c => c.kind === 'narration' && c !== firstNarr);
    // И если после этого остаётся важное финальное описание действия в конце абзаца (restNarr), а слоты заняты (firstNarr + thought + speech = 3), объединяем firstNarr и restNarr[0] (если в сумме <= 355 симв.), чтобы финальное действие абзаца тоже не потерялось!
    if (firstNarr && restNarr.length > 0 && (1 + dialogueAndThoughts.length + restNarr.length > maxQ)) {
        const combNarrLen = firstNarr.text.length + 1 + restNarr[0].text.length;
        if (combNarrLen <= 355) {
            const fTxt = /[.!?…]$/.test(firstNarr.text) ? firstNarr.text : (firstNarr.text + '.');
            firstNarr.text = `${fTxt} ${restNarr[0].text}`.trim();
            restNarr.shift();
        }
    }
    const picked = [];
    if (firstNarr && (dialogueAndThoughts.length < maxQ || firstNarr.pos === 0)) {
        picked.push(firstNarr);
    }
    for (const dt of dialogueAndThoughts) {
        if (picked.length < maxQ && !picked.includes(dt)) picked.push(dt);
    }
    for (const rn of restNarr) {
        if (picked.length < maxQ && !picked.includes(rn)) picked.push(rn);
    }
    picked.sort((a, b) => a.pos - b.pos);
    while (picked.length > 0 && picked.length < maxQ) {
        let longestIdx = -1;
        let longestLen = 52;
        for (let i = 0; i < picked.length; i++) {
            if (picked[i].text.length > longestLen) {
                longestLen = picked[i].text.length;
                longestIdx = i;
            }
        }
        if (longestIdx < 0) break;
        const item = picked[longestIdx];
        const txt = item.text;
        const mid = Math.floor(txt.length / 2);
        const breakPatterns = ['; ', ' — ', ' – ', ' - ', ': ', ', и ', ', а ', ', но ', ', однако ', ', где ', ', то ли ', ', при ', ', хотя ', ', пока ', ', стоя ', ', прикрыв ', ', закрепляя ', ', глядя ', ', словно ', ', втирая ', ', перебивая ', ', доставленный ', ', оставив ', ', расцветая '];
        let bestSplitPos = -1;
        let bestSplitSepLen = 0;
        let bestDist = 999999;
        for (const bp of breakPatterns) {
            let searchFrom = 22;
            while (searchFrom < txt.length - 22) {
                const p = txt.indexOf(bp, searchFrom);
                if (p < 0 || p > txt.length - 22) break;
                const dist = Math.abs(p - mid);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestSplitPos = p;
                    bestSplitSepLen = bp.startsWith(',') ? 1 : bp.length;
                }
                searchFrom = p + bp.length;
            }
        }
        if (bestSplitPos < 0) break;
        let part1 = txt.slice(0, bestSplitPos).replace(/[,;:\s—–-]+$/, '').trim();
        if (part1 && !/[.!?…]$/.test(part1)) part1 += '.';
        let part2 = capitalizeSentenceFirstChar(txt.slice(bestSplitPos + bestSplitSepLen).replace(/^[,;:\s—–-]+/, '').trim());
        if (part2 && !/[.!?…]$/.test(part2)) part2 += '.';
        if (part1.length < 18 || part2.length < 18) break;
        picked.splice(
            longestIdx,
            1,
            { ...item, text: part1 },
            { ...item, pos: item.pos + 1, text: part2 }
        );
    }
    return picked.slice(0, maxQ).map((c, idx) => ({
        panel: idx + 1,
        kind: c.kind || 'speech',
        speaker: c.kind === 'narration' ? '' : defaultSpeaker,
        text: c.text,
    }));
}

function isMonochromeComicStyle(cStyle) {
    if (!cStyle) return false;
    const tags = `${cStyle.naiTags || ''} ${cStyle.promptEn || ''}`;
    return /\b(monochrome|greyscale|black and white)\b/i.test(tags) && !/\bspot\s+color\b/i.test(tags);
}

function enforceMonochromeMangaPrompt(rawText, withWeightedPrefix = false) {
    if (!rawText) return '';
    let s = String(rawText);
    s = s.replace(/\b(blonde|blond|yellow|golden|platinum blonde|strawberry blonde)\s+hair\b/gi, 'light hair, white screentone hair');
    s = s.replace(/\b(dyed hair|black roots)\b/gi, 'two-tone screentone hair');
    s = s.replace(/\b(brown|chestnut|auburn|red|crimson|pink|blue|green|purple|violet|lavender|orange|silver|grey)\s+hair\b/gi, 'toned manga hair, screentone hair');
    s = s.replace(/\b(blue|green|hazel|amber|violet|purple|red|pink|yellow|orange|turquoise|crimson|emerald|golden|brown|aqua)\s+eyes\b/gi, 'detailed inked manga eyes');
    s = s.replace(/\b(pink|red|warm|rosy|soft pink)\s+blush\b/gi, 'manga blush lines, crosshatching blush');
    s = s.replace(/\b(full color|colorful|colourful|pastel palette|pastel colors|vibrant colors|saturated colors|rich colors|warm colors|cool colors|watercolor|colorized|chromatic|spot color|warm golden hour glow|warm lamp glow|deep amber and burgundy tones)\b\s*,?/gi, '');
    s = s.replace(/\bno\s+color\b\s*,?/gi, '');
    s = s.replace(/\b(blonde|red|blue|green|yellow|orange|pink|purple|violet|magenta|cyan|turquoise|crimson|scarlet|emerald|amber|golden|peach|coral|lavender|mint|beige|tan|brown|burgundy|navy|teal|maroon|olive)\b/gi, '');
    s = s.replace(/,\s*,+/g, ', ').replace(/^\s*,\s*|\s*,\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
    if (withWeightedPrefix && !/2\.0::monochrome/i.test(s)) {
        s = `2.0::monochrome, greyscale, black and white, manga ink, screentones, G-pen lineart::, ${s}`;
    }
    return s;
}

function getHeroNameStems(nameStr) {
    const withoutParens = String(nameStr || '').replace(/\([^)]*\)/g, ' ').replace(/\[[^\]]*\]/g, ' ');
    const clean = withoutParens.toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9\s-]+/gi, ' ').replace(/\s+/g, ' ').trim();
    if (!clean) return [];
    const tokens = clean.split(/\s+/).filter(t => t.length >= 2);
    const stems = new Set([clean]);
    for (const t of tokens) {
        stems.add(t);
        // Для 3-буквенных женских/гласных имён (Аня -> Ани/Ане/Аню/Аниного, Ева -> Евы/Еве, Зоя -> Зои) добавляем 2-буквенную основу перед гласной
        if (t.length === 3 && /[аяеиоуыэю]$/.test(t)) {
            stems.add(t.slice(0, 2) + '__vowel3');
        }
        if (t.length >= 4) stems.add(t.slice(0, t.length - 1));
        if (t.length >= 5) stems.add(t.slice(0, t.length - 2));
    }
    return Array.from(stems).filter(x => x.length >= 2);
}

function isNameMentionedInText(nameStr, textStr) {
    const stems = getHeroNameStems(nameStr);
    if (!stems.length || !textStr) return false;
    const low = String(textStr).toLowerCase().replace(/ё/g, 'е');
    return stems.some(st => {
        if (st.endsWith('__vowel3')) {
            const base2 = st.slice(0, -8).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const reV = new RegExp(`(?:^|[^а-яa-z0-9])${base2}(?:[аяиеуюы]|ей|ой|ин(?:[аоыуе]|ого|ому|ым|ой)?)(?=$|[^а-яa-z0-9])`, 'i');
            return reV.test(low);
        }
        const esc = st.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const suffix = st.length <= 3 ? '(?:[ауеюиы]|ом|ем|ой|ей|ям)?' : '[а-яa-z]{0,3}';
        const re = new RegExp(`(?:^|[^а-яa-z0-9])${esc}${suffix}(?=$|[^а-яa-z0-9])`, 'i');
        return re.test(low);
    });
}

function findDominantPovThinkerInPost(fullPostText, candidates = []) {
    if (!fullPostText || !Array.isArray(candidates) || !candidates.length) return '';
    const clean = stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(fullPostText))).replace(/<[^>]+>/g, ''));
    const paras = clean.split(/\n+/).map(p => p.trim()).filter(Boolean);
    const scores = new Map();
    for (const c of candidates) scores.set(c, 0);

    for (const p of paras) {
        const hasThought = /\*[^*\n]{3,1200}\*/.test(p);
        const mentionedHere = candidates.filter(cName => isNameMentionedInText(cName, p));
        if (mentionedHere.length === 1) {
            scores.set(mentionedHere[0], (scores.get(mentionedHere[0]) || 0) + (hasThought ? 4 : 2));
        } else if (mentionedHere.length > 1 && hasThought) {
            const astIdx = p.indexOf('*');
            const beforeAst = astIdx > 0 ? p.slice(0, astIdx) : p;
            for (const cName of mentionedHere) {
                if (isNameMentionedInText(cName, beforeAst)) {
                    scores.set(cName, (scores.get(cName) || 0) + 1);
                }
            }
        }
    }
    let bestName = '';
    let bestScore = 0;
    for (const [name, sc] of scores.entries()) {
        if (sc > bestScore) {
            bestScore = sc;
            bestName = name;
        }
    }
    return bestScore >= 2 ? bestName : '';
}

// Род ремарки сразу после реплики/мысли: «— простонал он», «— произнесла она» → 'boy' / 'girl'
function nnbAttributionGender(afterText) {
    const raw = String(afterText || '').toLowerCase().replace(/ё/g, 'е');
    // только настоящая ремарка: сразу после фразы идёт тире («…*, — простонал он»), а не новое предложение
    if (!/^[\s*»"”.,!?…]*[—–-]/.test(raw)) return '';
    const t = raw.replace(/^[\s,—–\-*»"”.!?…]+/, '').slice(0, 70);
    const words = t.split(/[^а-я]+/).filter(Boolean).slice(0, 5);
    for (const w of words) {
        if (w === 'она') return 'girl';
        if (w === 'он') return 'boy';
        if (w.length >= 4 && /(?:ла|лась)$/.test(w)) return 'girl';
        if (w.length >= 4 && /(?:[^л]л|лся)$/.test(w)) return 'boy';
    }
    return '';
}
function windowBeforeForAttr(txt, idx) { return String(txt || '').slice(Math.max(0, idx - 260), idx); }
function nnbGenderOfName(name, st) {
    const nm = String(name || '').toLowerCase().replace(/ё/g, 'е');
    if (!nm) return '';
    const cards = [...(st?.npcs || [])];
    if (st?.mainCharCard) cards.push(st.mainCharCard);
    let card = cards.find(n => String(n?.name || '').toLowerCase().replace(/ё/g, 'е') === nm);
    if (!card) {
        try {
            const c = ctx();
            if (String(c.name1 || '').toLowerCase().replace(/ё/g, 'е') === nm) {
                card = nnbPersonaCard(st, c.name1, c);
            }
        } catch (e) { /* ignore */ }
    }
    if (!card) return '';
    try { return guessCardGender(card, parseCanonFromAppearance(card.appearanceEn)) || ''; } catch (e) { return ''; }
}

function inferSpeakerFromPostContext(postText, quoteText, cast = [], st = null, kindHint = '', fullStoryText = '') {
    if (!postText || !quoteText) return '';
    const names = storyNames() || {};
    const cleanPost = stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(postText))).replace(/<[^>]+>/g, '')).replace(/[^\S\n]+/g, ' ');
    const cleanFull = fullStoryText
        ? stripRoleplayHeaderBracketsAndWeirdSpaces(stripTags(stripActionTags(String(fullStoryText))).replace(/<[^>]+>/g, '')).replace(/[^\S\n]+/g, ' ')
        : cleanPost;
    const norm = t => stripRoleplayHeaderBracketsAndWeirdSpaces(String(t || '')).toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ');
    const qShort = norm(quoteText).slice(0, 28).trim();
    if (!qShort) return '';

    const activeCast = Array.isArray(cast)
        ? cast.map(c => (typeof c === 'string' ? c : (c?.name || ''))).filter(c => c && c !== '__none__')
        : [];
    const candidates = [];
    if (names.user) candidates.push(names.user);
    if (names.char) candidates.push(names.char);
    for (const npc of (st?.npcs || [])) {
        if (npc?.name && !candidates.includes(npc.name)) candidates.push(npc.name);
    }
    for (const cName of activeCast) {
        if (cName && !candidates.includes(cName)) candidates.push(cName);
    }

    const validCandidates = candidates.filter(cName => {
        if (!isNameMentionedInText(cName, cleanPost) && !isNameMentionedInText(cName, cleanFull)) return false;
        if (activeCast.length > 0) {
            return activeCast.some(c => isNameMentionedInText(cName, c) || isNameMentionedInText(c, cName));
        }
        return true;
    });

    const povThinker = findDominantPovThinkerInPost(cleanFull, validCandidates.length ? validCandidates : candidates);

    const idx = norm(cleanPost).indexOf(qShort);
    if (idx < 0) {
        return ((kindHint === 'thought' || kindHint === 'speech') && povThinker) ? povThinker : '';
    }
    // Маскируем внутренности прямых реплик "..." (где имена — это обращения к собеседнику, например «Одевайся и ищи паспорт, Ян!») и притяжательные дополнения («ногтей Этель», «квартиры Яна»), сохраняя точные индексы символов!
    const narrativeOnlyPost = cleanPost
        .replace(/(?:"[^"\n]*"|«[^«»\n]*»|“[^“”\n]*”|\*[^*\n]*\*)/g, m => ' '.repeat(m.length))
        .replace(/(?:квартир[аыеуой]|дом[аеу]?|комнат[аыеу]|кабинет[аеу]?|ногт[ейями]+|сапог[аеу]?|пальц[ыаеевм]+)\s+[А-ЯЁA-Z][а-яёa-z]+/gi, m => ' '.repeat(m.length))
        .replace(/(?:^|[^а-яёa-z0-9])(?:перед|за|над|под|рядом\s+с|вместе\s+с|мимо|вокруг|против|между)\s+[А-ЯЁA-Z][а-яёa-z]+/gi, m => ' '.repeat(m.length))
        .replace(/[А-ЯЁA-Z][а-яёa-z]+ин(?:ого|ому|ым|ой|а|ы|у|е)(?=$|[^а-яёa-z0-9])/g, m => ' '.repeat(m.length));

    // Находим реальный конец первой кавычки/мысли в cleanPost после idx (на случай если quoteText состоит из двух склеенных реплик, между которыми в тексте стояло «Пробормотал Кайлар в складки шарфа»!)
    const closeTagMatch = cleanPost.slice(idx).match(/[»”"*]/);
    const firstQuoteEndIdx = closeTagMatch ? (idx + closeTagMatch.index + 1) : (idx + quoteText.length);

    const rawBefore = narrativeOnlyPost.slice(Math.max(0, idx - 85), idx);
    const rawAfter = narrativeOnlyPost.slice(firstQuoteEndIdx, Math.min(narrativeOnlyPost.length, firstQuoteEndIdx + 110));
    const immediateAfterFull = (rawAfter.split(/[.!?…\n]/)[0] || '');
    // Отрезаем придаточные предложения с союзами переключения субъекта (“, однако стоило Софии...”, “, но когда...”, “, пока Этель...”), чтобы имя второго героя в хвосте не перебивало говорящего!
    const immediateAfter = immediateAfterFull.split(/,\s*(?:однако|но|хотя|пока|тогда как|прежде чем)(?=$|[^а-яёa-z0-9])/i)[0] || '';
    const beforeParts = rawBefore.split(/[.!?…\n]/);
    const immediateBefore = beforeParts[beforeParts.length - 1] || '';
    const immediateContext = `${immediateBefore} ${immediateAfter}`;
    // Ремарка «— простонал / — произнесла» сразу после фразы однозначно говорит о роде говорящего: если такой герой в сцене один — это он
    {
        const attrG = nnbAttributionGender(cleanPost.slice(firstQuoteEndIdx, firstQuoteEndIdx + 90));
        if (attrG) {
            const sameG = validCandidates.filter(cName => nnbGenderOfName(cName, st) === attrG);
            if (sameG.length === 1) return sameG[0];
            if (sameG.length > 1) {
                const near = sameG.filter(cName => isNameMentionedInText(cName, `${immediateContext} ${windowBeforeForAttr(narrativeOnlyPost, idx)}`));
                if (near.length === 1) return near[0];
            }
        }
    }
    const windowBefore = narrativeOnlyPost.slice(Math.max(0, idx - 260), idx);
    const windowAfter = immediateAfter;
    const nearContext = `${windowBefore} ${windowAfter}`;

    // Если это ВНУТРЕННЯЯ МЫСЛЬ (*...*), проверяем, не описан ли перед ней другой персонаж СО СТОРОНЫ глазами главной POV-героини (например: «На лестничной площадке возвышался промокший Ян... из-под подола подозрительно наглухо запахнутого... *Если соседка снизу...* "Раствор стынет, госпожа гадалка..." - пророкотал кот»)!
    if (kindHint === 'thought' && povThinker) {
        const beforePara = cleanPost.slice(Math.max(0, idx - 650), idx).split(/\n\s*\n/).pop() || '';
        const afterPara = cleanPost.slice(idx + quoteText.length, Math.min(cleanPost.length, idx + quoteText.length + 450));
        const observedFromOutsideRe = /(?:на лестничной площадке|в дверях|на пороге|возвышал[ась]*|подозрительно|торчали|шагая через порог|хозяйка|гадалка|журналистка)/i;
        const mentionedInThisChunk = validCandidates.filter(cName => isNameMentionedInText(cName, cleanPost));
        if (!mentionedInThisChunk.length) {
            return povThinker;
        }
        if (mentionedInThisChunk.length === 1 && mentionedInThisChunk[0] !== povThinker && observedFromOutsideRe.test(beforePara + ' ' + afterPara)) {
            return povThinker;
        }
    }

    const presentInChunkCandidates = validCandidates.filter(cName => isNameMentionedInText(cName, cleanPost));
    const pool = presentInChunkCandidates.length ? presentInChunkCandidates : validCandidates;

    const matchedImmediate = pool.filter(cName => isNameMentionedInText(cName, immediateContext));
    if (matchedImmediate.length === 1) return matchedImmediate[0];
    const matchedInWindow = pool.filter(cName => isNameMentionedInText(cName, nearContext));
    if (matchedInWindow.length === 1) return matchedInWindow[0];

    const paraBefore = narrativeOnlyPost.slice(Math.max(0, idx - 950), idx).split(/\n\s*\n/).pop() || '';
    const matchedInPara = pool.filter(cName => isNameMentionedInText(cName, paraBefore));
    if (matchedInPara.length === 1) return matchedInPara[0];
    if (matchedInPara.length > 1) {
        const normPara = norm(paraBefore);
        let latestCand = '';
        let latestPos = -1;
        for (const cName of matchedInPara) {
            for (const stStem of getHeroNameStems(cName)) {
                if (stStem.endsWith('__vowel3')) continue;
                const esc = stStem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const reG = new RegExp(`(?:^|[^а-яa-z0-9])(${esc})`, 'gi');
                let mPos;
                while ((mPos = reG.exec(normPara)) !== null) {
                    if (mPos.index >= latestPos) {
                        latestPos = mPos.index;
                        latestCand = cName;
                    }
                }
            }
        }
        if (latestCand) return latestCand;
    }
    if (povThinker && (kindHint === 'thought' || presentInChunkCandidates.length <= 1)) return povThinker;
    if (presentInChunkCandidates.length === 1) return presentInChunkCandidates[0];
    return '';
}

// ================= Кто субъект в этом месте текста =================
// Одна функция на всё: чья мысль (*…*), чья вещь («кожаной куртки»). Ищем подлежащее: имя в именительном падеже + глагол
// прошедшего времени рядом («Кайлар за столом сузил», «вальяжно привалился Ян», «Ямико, заехавшая …, прижимала»),
// или «он/она» + глагол → последний названный герой этого пола в абзаце. Падежные формы («к Ане», «на Энджела») — не подлежащее.
const NNB_PAST_VERB_RE = /^[а-я]{2,}(?:л|ла|ли|лся|лась|лись)$/;
